"use strict";(globalThis.webpackChunktemp_dir=globalThis.webpackChunktemp_dir||[]).push([[8413],{1592(n){n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"modern-robotics-part-1","metadata":{"permalink":"/ko/blog/modern-robotics-part-1","editUrl":"https://github.com/CMaybe/cmaybe.github.io/tree/main/blog/2026-09-07-modern-robotics-part-1.md","source":"@site/i18n/ko/docusaurus-plugin-content-blog/2026-09-07-modern-robotics-part-1.md","title":"Modern Robotics, Part 1 - \uac15\uccb4 \uc6b4\ub3d9\uacfc \uc9c0\uc218 \uacf1 \uacf5\uc2dd","description":"\uac15\uccb4 \uc6b4\ub3d9, \ube44\ud2c0\ub9bc, \ub098\uc120\ucd95, \uadf8\ub9ac\uace0 \ub85c\ubd07 \uae30\uad6c\ud559\uc758 \uc9c0\uc218 \uacf1 \uacf5\uc2dd\uc744 \ub2e4\ub8e8\ub294 Modern Robotics \uc785\ubb38 \uae00\uc785\ub2c8\ub2e4.","date":"2026-09-07T00:00:00.000Z","tags":[{"inline":false,"label":"Robotics","permalink":"/ko/blog/tags/robotics","description":"Robot software, systems, and experiments."},{"inline":false,"label":"Modern Robotics","permalink":"/ko/blog/tags/modern-robotics","description":"Concepts, methods, and intuition behind rigid-body motion and robot kinematics."},{"inline":false,"label":"Kinematics","permalink":"/ko/blog/tags/kinematics","description":"Forward and inverse kinematics for robots."},{"inline":false,"label":"Screw Theory","permalink":"/ko/blog/tags/screw-theory","description":"Twists, screw axes, and the geometry of rigid-body motion."}],"readingTime":6.64,"hasTruncateMarker":true,"authors":[{"name":"Jaegyeom Kim","title":"Robotics Software Engineer","url":"https://github.com/CMaybe","page":{"permalink":"/ko/blog/authors/endi"},"socials":{"github":"https://github.com/CMaybe","linkedin":"https://www.linkedin.com/in/Jaegyeom-kim-185b8a2a4/"},"imageURL":"https://github.com/CMaybe.png","key":"endi"}],"frontMatter":{"slug":"modern-robotics-part-1","title":"Modern Robotics, Part 1 - \uac15\uccb4 \uc6b4\ub3d9\uacfc \uc9c0\uc218 \uacf1 \uacf5\uc2dd","authors":["endi"],"tags":["robotics","modern-robotics","kinematics","screw-theory"],"description":"\uac15\uccb4 \uc6b4\ub3d9, \ube44\ud2c0\ub9bc, \ub098\uc120\ucd95, \uadf8\ub9ac\uace0 \ub85c\ubd07 \uae30\uad6c\ud559\uc758 \uc9c0\uc218 \uacf1 \uacf5\uc2dd\uc744 \ub2e4\ub8e8\ub294 Modern Robotics \uc785\ubb38 \uae00\uc785\ub2c8\ub2e4."},"unlisted":false,"nextItem":{"title":"Modern Robotics, Part 2A - \ub098\uc120\ucd95, Twist, \uadf8\ub9ac\uace0 \uc9c0\uc218 \uc0ac\uc0c1","permalink":"/ko/blog/modern-robotics-part-2"}},"content":"\ub85c\ubd07 \uae30\uad6c\ud559\uc740 \ud754\ud788 \uad00\uc808 \ubcc0\uc218\uc640 \uc88c\ud45c\uacc4\uc758 \ubaa8\uc74c\uc73c\ub85c \uc18c\uac1c\ub429\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc2e4\uc81c\ub85c \uc6b0\ub9ac\uac00 \ub2e4\ub8e8\ub294 \ub300\uc0c1\uc740 \ubb3c\ub9ac\uc801 \uc81c\uc57d\uc744 \ubc1b\uc73c\uba70 \uacf5\uac04\uc744 \uc6c0\uc9c1\uc774\ub294 \uac15\uccb4\uc785\ub2c8\ub2e4. Modern Robotics\ub294 \uc774\ub7ec\ud55c \uc6b4\ub3d9\uc744 \uc124\uba85\ud558\uae30 \uc704\ud574 \ube44\ud2c0\ub9bc(twist), \ub098\uc120\ucd95(screw axis), \ub3d9\ucc28 \ubcc0\ud658, \uc9c0\uc218 \uc0ac\uc0c1\uc774\ub77c\ub294 \ud1b5\uc77c\ub41c \uc218\ud559\uc801 \uc5b8\uc5b4\ub97c \uc81c\uacf5\ud569\ub2c8\ub2e4.\\n\\n\uc774 \uae00\uc740 [modern-robotics-wasm](https://cmaybe.github.io/modern-robotics-wasm/) \ud504\ub85c\uc81d\ud2b8\uc758 \uc774\ub860\uc801 \ubc30\uacbd\uc744 \uc124\uba85\ud558\ub294 \uc2dc\ub9ac\uc988\uc758 \uccab \uae00\uc785\ub2c8\ub2e4. \uac19\uc740 \uac1c\ub150\uc774 \ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c \uc5b4\ub5bb\uac8c \uc0c1\ud638\uc791\uc6a9 \uac00\ub2a5\ud55c \ud615\ud0dc\ub85c \uad6c\ud604\ub418\ub294\uc9c0\ub3c4 \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.\\n\\n\x3c!-- truncate --\x3e\\n\\n## 1. \uace0\uc804\uc801\uc778 \uc88c\ud45c \uacc4\uc0b0\uc774 \ubcf5\uc7a1\ud574\uc9c0\ub294 \uc774\uc720\\n\\n\ub85c\ubd07 \ud314\uc740 \ub2e8\uc21c\ud788 \uac01\ub3c4\ub97c \uc774\uc5b4 \ubd99\uc778 \uccb4\uc778\uc774 \uc544\ub2d9\ub2c8\ub2e4. \ub85c\ubd07\uc758 configuration\uc740 \uad00\uc808 \ubcc0\uc218\ubfd0 \uc544\ub2c8\ub77c \ub9c1\ud06c\uc758 \ud615\uc0c1\uacfc \ub9c1\ud06c\uac00 \uc6c0\uc9c1\uc774\ub294 \uacf5\uac04\uc758 \uad6c\uc870\uc5d0 \uc758\ud574 \uacb0\uc815\ub429\ub2c8\ub2e4.\\n\\n\uad00\uc808 \uac12 $\\theta_1, \\\\dots, \\\\theta_n$\ub9cc \uc54c\uace0 \uc788\ub2e4\uace0 \ud574\uc11c \uacf5\uac04\uc5d0\uc11c \ub9d0\ub2e8 \uc7a5\uce58\uc758 pose\ub97c \uc54c \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4. \uad00\uc808 \uacf5\uac04\uc5d0\uc11c \uc791\uc5c5 \uacf5\uac04\uc73c\ub85c \uac00\ub294 \uc0ac\uc0c1\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.\\n\\n$$\\nT_{sb} = f(\\\\theta_1, \\\\dots, \\\\theta_n),\\n$$\\n\\n\uc5ec\uae30\uc11c $T_{sb}$\ub294 \ub85c\ubd07 \ubca0\uc774\uc2a4 \uc88c\ud45c\uacc4 $\\\\{s\\\\}$\uc5d0\uc11c \ub9d0\ub2e8 \uc7a5\uce58 \uc88c\ud45c\uacc4 $\\\\{b\\\\}$\ub85c \uac00\ub294 \ub3d9\ucc28 \ubcc0\ud658\uc785\ub2c8\ub2e4.\\n\\n\uc774 \uc0ac\uc0c1\uc740 \uae30\uad6c\ud559\uc758 \ud575\uc2ec \ub300\uc0c1\uc785\ub2c8\ub2e4. $n$\uac1c\uc758 \uad00\uc808\uc744 \uac00\uc9c4 \ub85c\ubd07\uc5d0\uc11c \ub9d0\ub2e8 \uc7a5\uce58\uc758 pose\ub294 \uc77c\ubc18\uc801\uc73c\ub85c \uad00\uc808 configuration\uc758 \ud568\uc218\uc785\ub2c8\ub2e4. \uc911\uc694\ud55c \uc810\uc740 \uc774 \uac12\uc744 \uacc4\uc0b0\ud558\ub294 \ub370 \uadf8\uce58\uc9c0 \uc54a\ub294\ub2e4\ub294 \uac83\uc785\ub2c8\ub2e4. \ud68c\uc804\uacfc \ubcd1\uc9c4, \uc11c\ub85c \ub2e4\ub978 \uae30\uc900 \uc88c\ud45c\uacc4 \uc0ac\uc774\uc758 \ubcc0\ud658\uae4c\uc9c0 \uc218\ud559\uc801\uc73c\ub85c \uc77c\uad00\ub41c \ubc29\uc2dd\uc73c\ub85c \ub2e4\ub904\uc57c \ud569\ub2c8\ub2e4.\\n\\nModern Robotics\ub294 \uc774\ub97c \uc704\ud574 \uac15\uccb4 \uc6b4\ub3d9\uc744 \uc88c\ud45c\uc2dd\uc744 \uc784\uc758\ub85c \uc870\ud569\ud55c \uacb0\uacfc\uac00 \uc544\ub2c8\ub77c \ud558\ub098\uc758 \uae30\ud558\ud559\uc801 \ub300\uc0c1\uc73c\ub85c \ub2e4\ub8f9\ub2c8\ub2e4.\\n\\n## 2. \ubcc0\ud658\uc73c\ub85c \ud45c\ud604\ud558\ub294 \uac15\uccb4 \uc6b4\ub3d9\\n\\n\uac15\uccb4\ub294 \uac01 \uc810 \uc0ac\uc774\uc758 \uac70\ub9ac\ub97c \uc720\uc9c0\ud558\uba74\uc11c 3\ucc28\uc6d0 \uacf5\uac04\uc744 \uc6c0\uc9c1\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uac15\uccb4\uc758 pose\ub294 \ud68c\uc804\uacfc \ubcd1\uc9c4\uc73c\ub85c \uc644\uc804\ud788 \ud45c\ud604\ub429\ub2c8\ub2e4.\\n\\n$$\\nR \\\\in SO(3), \\\\qquad p \\\\in \\\\mathbb{R}^3.\\n$$\\n\\n\uc774 \ub458\uc744 \ud569\uce58\uba74 \ub3d9\ucc28 \ubcc0\ud658\uc744 \uc5bb\uc2b5\ub2c8\ub2e4.\\n\\n$$\\nT = \\\\begin{bmatrix}\\nR & p \\\\\\\\\\n0 & 1\\n\\\\end{bmatrix}.\\n$$\\n\\n\uc774 \ud589\ub82c\uc740 \ud55c \uc88c\ud45c\uacc4\uc5d0\uc11c \ud45c\ud604\ud55c \uc810\uc744 \ub2e4\ub978 \uc88c\ud45c\uacc4\uc758 \ud45c\ud604\uc73c\ub85c \ubc14\uafc9\ub2c8\ub2e4. \uc5b4\ub5a4 \uc810 $q$\uac00 \uac15\uccb4 \uc88c\ud45c\uacc4\uc5d0\uc11c \ud45c\ud604\ub418\uc5b4 \uc788\ub2e4\uba74, \uacf5\uac04 \uc88c\ud45c\uacc4\uc5d0\uc11c\uc758 \ud45c\ud604\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.\\n\\n$$\\n\\\\begin{bmatrix}\\nq_s \\\\\\\\\\n1\\n\\\\end{bmatrix}\\n= T_{sb}\\n\\\\begin{bmatrix}\\nq_b \\\\\\\\\\n1\\n\\\\end{bmatrix}.\\n$$\\n\\n\uc774\uac83\uc774 \ub85c\ubd07 \uae30\uad6c\ud559\uc5d0\uc11c \uac00\uc7a5 \uc911\uc694\ud55c \uae30\ubcf8 \uc694\uc18c\uc785\ub2c8\ub2e4. \ub85c\ubd07\uc740 \uac01 \ub9c1\ud06c\uc5d0 \ubd99\uc740 \uc88c\ud45c\uacc4 \uc0ac\uc774\ub97c \uc5f0\uacb0\ud558\ub294 \uac15\uccb4 \ubcc0\ud658\uc758 \uc5f0\uc1c4\ub85c \ud45c\ud604\ub429\ub2c8\ub2e4.\\n\\n\uae30\ud558\ud559\uc801\uc73c\ub85c \uc5b4\ub824\uc6b4 \uc810\uc740 \uad00\uc808\uc774 \uc6c0\uc9c1\uc77c \ub54c \uc774 \ubcc0\ud658\ub3c4 \uc5f0\uc18d\uc801\uc73c\ub85c \ubcc0\ud55c\ub2e4\ub294 \ub370 \uc788\uc2b5\ub2c8\ub2e4. \uacb0\uad6d \uc774 \ubcc0\ud654\ub97c \uac04\uacb0\ud558\uba74\uc11c\ub3c4 \uc77c\ubc18\uc801\uc778 \ubc29\uc2dd\uc73c\ub85c \ubaa8\ub378\ub9c1\ud574\uc57c \ud569\ub2c8\ub2e4.\\n\\n## 3. \uac15\uccb4 \uc6b4\ub3d9\uc758 \uc21c\uac04\uc801\uc778 \ud45c\ud604: twist\\n\\nModern Robotics\ub294 \uc6b4\ub3d9\uc744 \uc720\ud55c\ud55c \ud68c\uc804\uacfc \ubcd1\uc9c4\uc73c\ub85c \ubc14\ub85c \ud45c\ud604\ud558\ub294 \ub300\uc2e0, \uba3c\uc800 \uc21c\uac04\uc801\uc778 \uc6b4\ub3d9\uc744 twist\ub85c \ub098\ud0c0\ub0c5\ub2c8\ub2e4.\\n\\nTwist $\\\\xi$\ub294 \ub2e4\uc74c\uacfc \uac19\uc774 \uc815\uc758\ub429\ub2c8\ub2e4.\\n\\n$$\\n\\\\xi = \\\\begin{bmatrix}\\n\\\\omega \\\\\\\\\\nv\\n\\\\end{bmatrix},\\n$$\\n\\n\uc5ec\uae30\uc11c $\\\\omega \\\\in \\\\mathbb{R}^3$\ub294 \uac01\uc18d\ub3c4\uc774\uace0, $v \\\\in \\\\mathbb{R}^3$\ub294 \ubcf4\ud1b5 \uc120\ud0dd\ud55c \uc88c\ud45c\uacc4\uc5d0\uc11c \ud45c\ud604\ud55c \uac15\uccb4 \uae30\uc900\uc810\uc758 \uc120\uc18d\ub3c4\uc785\ub2c8\ub2e4.\\n\\n\uc810 $q$\ub97c \uc9c0\ub098\ub294 \ucd95 $\\\\omega$\ub97c \uc911\uc2ec\uc73c\ub85c \uc21c\uc218 \ud68c\uc804\ud558\ub294 \uacbd\uc6b0 twist\ub294 \ub2e4\uc74c\uacfc \uac19\uc774 \uc4f8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n$$\\n\\\\xi = \\\\begin{bmatrix}\\n\\\\omega \\\\\\\\\\n-\\\\omega \\\\times q\\n\\\\end{bmatrix}.\\n$$\\n\\n\ubc29\ud5a5 $v$\ub97c \ub530\ub77c \uc21c\uc218 \ubcd1\uc9c4\ud558\ub294 \uacbd\uc6b0\uc5d0\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.\\n\\n$$\\n\\\\xi = \\\\begin{bmatrix}\\n0 \\\\\\\\\\nv\\n\\\\end{bmatrix}.\\n$$\\n\\nTwist\ub294 \ub2e8\uc21c\ud55c \uc720\ud074\ub9ac\ub4dc \uacf5\uac04\uc758 \uc18d\ub3c4 \ubca1\ud130\uac00 \uc544\ub2d9\ub2c8\ub2e4. \uac15\uccb4 \uc804\uccb4\uc758 \uc18d\ub3c4\uc7a5\uc744 \ub098\ud0c0\ub0c5\ub2c8\ub2e4. \ub2e4\uc2dc \ub9d0\ud574 \uac15\uccb4 \uc6b4\ub3d9\uc5d0\ub294 \ud558\ub098\uc758 \uac01\uc18d\ub3c4\uc640 \uadf8 \ud68c\uc804 \ubc0f \ubcd1\uc9c4\uc5d0 \ub300\uc751\ud558\ub294 \uc120\uc18d\ub3c4\uc7a5\uc774 \uc874\uc7ac\ud569\ub2c8\ub2e4.\\n\\nTwist\uc5d0 \uc2a4\uce7c\ub77c \uad00\uc808 \uc18d\ub3c4 $\\\\dot{\\\\theta}$\ub97c \uacf1\ud558\uba74 \uad00\uc808 \uc18d\ub3c4\uc5d0 \ub530\ub978 \uac15\uccb4\uc758 \uc21c\uac04 \uc6b4\ub3d9\uc744 \uc5bb\uc2b5\ub2c8\ub2e4.\\n\\n$$\\n\\\\dot{T} = \\\\xi \\\\dot{\\\\theta} T\\n$$\\n\\n\ub610\ub294 \uc88c\ud45c\uacc4 convention\uc5d0 \ub530\ub77c \ub2e4\uc74c\uacfc \uac19\uc774 \uc4f8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n$$\\n\\\\dot{T} = T \\\\hat{\\\\xi}.\\n$$\\n\\n\uc774 \uc2dd\uc740 \uc21c\uac04 \uc18d\ub3c4\uc640 \uac15\uccb4 \ubcc0\ud658\uc744 \uc5f0\uacb0\ud569\ub2c8\ub2e4.\\n\\n## 4. \uad00\uc808 \uc6b4\ub3d9\uc5d0\uc11c \uac15\uccb4 \uc6b4\ub3d9\uc73c\ub85c: exponential map\\n\\n\ub2e4\uc74c \ub2e8\uacc4\ub294 \uc2a4\uce7c\ub77c \uad00\uc808 \ubcc0\uc218 $\\\\theta$\ub97c \uc720\ud55c\ud55c \uac15\uccb4 \ubcc0\ud658\uacfc \uc5f0\uacb0\ud558\ub294 \uac83\uc785\ub2c8\ub2e4.\\n\\n\uace0\uc815\ub41c \ub098\uc120\ucd95 $\\\\xi$\uac00 \uc788\uc744 \ub54c, \uac01\ub3c4 \ub610\ub294 \ubcc0\uc704 $\\\\theta$\ub9cc\ud07c \ubc1c\uc0dd\ud558\ub294 \uc6b4\ub3d9\uc740 \ub2e4\uc74c\uacfc \uac19\uc774 \ud45c\ud604\ub429\ub2c8\ub2e4.\\n\\n$$\\nT(\\\\theta) = e^{\\\\hat{\\\\xi}\\\\theta}.\\n$$\\n\\n\uc5ec\uae30\uc11c $\\\\hat{\\\\xi}$\ub294 twist\ub97c \ud589\ub82c\ub85c \ud45c\ud604\ud55c \uac83\uc73c\ub85c, \ubcf4\ud1b5 \ub2e4\uc74c\uacfc \uac19\uc774 \uc501\ub2c8\ub2e4.\\n\\n$$\\n\\\\hat{\\\\xi} =\\n\\\\begin{bmatrix}\\n[\\\\omega] & v \\\\\\\\\\n0 & 0\\n\\\\end{bmatrix},\\n$$\\n\\n$[\\\\omega]$\ub294 $\\\\omega$\uc640\uc758 \uc678\uc801\uc744 \ub098\ud0c0\ub0b4\ub294 \ubc18\ub300\uce6d \ud589\ub82c\uc785\ub2c8\ub2e4.\\n\\n\uc774 \ubd80\ubd84\uc774 Modern Robotics \uc815\uc2dd\ud654\uc758 \ud575\uc2ec\uc785\ub2c8\ub2e4. \uc9c0\uc218 \uc0ac\uc0c1\uc740 \uc811\uacf5\uac04\uc5d0\uc11c \ud45c\ud604\ud55c \uc6b4\ub3d9\uc744 \uac15\uccb4 pose \uacf5\uac04\uc758 \uc720\ud55c\ud55c \ubcc0\ud658\uc73c\ub85c \ubc14\uafc9\ub2c8\ub2e4.\\n\\n\ud68c\uc804 \uad00\uc808\uc758 \uacbd\uc6b0 \uc6b4\ub3d9\uc740 \ub098\uc120\ucd95\uc744 \uc911\uc2ec\uc73c\ub85c \ud55c \ud68c\uc804\uc785\ub2c8\ub2e4.\\n\\n$$\\nT(\\\\theta) = e^{[\\\\omega]_{\\\\times}\\\\theta}.\\n$$\\n\\n\uc9c1\ub3d9 \uad00\uc808\uc758 \uacbd\uc6b0\uc5d0\ub294 \ud55c \ubc29\ud5a5\uc744 \ub530\ub978 \ubcd1\uc9c4\uc774 \ub429\ub2c8\ub2e4.\\n\\n$$\\nT(d) = e^{\\\\begin{bmatrix}0 & v \\\\\\\\ 0 & 0\\\\end{bmatrix} d}.\\n$$\\n\\n\uc774\ub807\uac8c \ud558\uba74 \uc6b4\ub3d9\uc758 \uae30\ud558\uac00 \ubd84\uba85\ud574\uc9d1\ub2c8\ub2e4. \ucd95\uc758 \uc704\uce58\uc640 \ubc29\ud5a5, \uadf8\ub9ac\uace0 \uc6b4\ub3d9\ub7c9\uc774 \ucd5c\uc885 \ubcc0\ud658\uc744 \uacb0\uc815\ud569\ub2c8\ub2e4.\\n\\n## 5. \uc815\uc2dd\ud654\uc758 \uae30\ud558\ud559\uc801 \uc911\uc2ec\uc778 \ub098\uc120\ucd95\\n\\n\ub098\uc120\ucd95\uc740 \uc6b4\ub3d9\uc758 \ubc29\ud5a5\uacfc \ucd95\uc774 \uacf5\uac04\uc5d0\uc11c \ub193\uc778 \uc704\uce58\ub97c \ud568\uaed8 \ub2f4\uc2b5\ub2c8\ub2e4. \ud68c\uc804 \uad00\uc808\uc5d0\uc11c\ub294 \ud68c\uc804\uc774 \uc77c\uc5b4\ub098\ub294 3\ucc28\uc6d0 \uc9c1\uc120\uc774\uace0, \uc9c1\ub3d9 \uad00\uc808\uc5d0\uc11c\ub294 \ubcd1\uc9c4\uc774 \uc77c\uc5b4\ub098\ub294 \uc9c1\uc120\uc785\ub2c8\ub2e4.\\n\\n\uc77c\ubc18\uc801\uc778 \ub098\uc120\ucd95\uc740 \ub2e4\uc74c\uacfc \uac19\uc774 \uc4f8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n$$\\n\\\\mathcal{S} = \\\\begin{bmatrix}\\n\\\\omega \\\\\\\\\\nv_0\\n\\\\end{bmatrix},\\n$$\\n\\n\uc5ec\uae30\uc11c $\\\\omega$\ub294 \ucd95\uc758 \ub2e8\uc704 \ubc29\ud5a5 \ubca1\ud130\uc774\uace0 $v_0$\ub294 \uc6b4\ub3d9\uc73c\ub85c \uc778\ud574 \ucd95 \uc704\uc758 \ud55c \uc810\uc5d0 \uc0dd\uae30\ub294 \uc120\uc18d\ub3c4\uc785\ub2c8\ub2e4.\\n\\n\uc6d0\uc810\uc744 \uc9c0\ub098\uc9c0 \uc54a\ub294 \uc9c1\uc120\uc744 \uc911\uc2ec\uc73c\ub85c \ud68c\uc804\ud55c\ub2e4\uba74 \uc120\ud615 \uc131\ubd84\uc740 \uc784\uc758\ub85c \uc815\ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4. \ucd95\uc758 \uae30\ud558\uc5d0 \uc758\ud574 \ub2e4\uc74c\uacfc \uac19\uc774 \uc81c\ud55c\ub429\ub2c8\ub2e4.\\n\\n$$\\nv_0 = -\\\\omega \\\\times q,\\n$$\\n\\n\uc5ec\uae30\uc11c $q$\ub294 \ucd95 \uc704\uc758 \uc784\uc758\uc758 \uc810\uc785\ub2c8\ub2e4. \uc774\ub294 \ucd95\uc744 \uc911\uc2ec\uc73c\ub85c \ud55c \uc21c\uac04 \ud68c\uc804\uc774 \uac15\uccb4 \uae30\uad6c\ud559\uacfc \uc77c\uad00\ub41c \ubc29\uc2dd\uc73c\ub85c \uac15\uccb4 \uacf3\uacf3\uc5d0 \uc120\uc18d\ub3c4\ub97c \ub9cc\ub4e0\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ubc18\uc601\ud569\ub2c8\ub2e4.\\n\\nScrew theory\uac00 \uc720\uc6a9\ud55c \uc774\uc720\ub3c4 \uc5ec\uae30\uc5d0 \uc788\uc2b5\ub2c8\ub2e4. \uc6b4\ub3d9 \ubc29\ud5a5\uacfc \ucd95\uc758 \uae30\ud558\ub97c \ubd84\ub9ac\ud574\uc11c \ub2e4\ub8f0 \uc218 \uc788\uace0, \uac15\uccb4 \uc6b4\ub3d9\uc744 \uad6c\uc870\ud654\ub41c \uae30\uad6c\ud559 \ubaa8\ub378\uc758 \ud558\ub098\uc758 \uc6d0\uc18c\ub85c \ud45c\ud604\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n## 6. \ubaa8\ub4e0 \uad00\uc808\uc744 \uc870\ud569\ud558\ub294 Product of Exponentials\\n\\n\uac01 \uad00\uc808\uc5d0 \ub098\uc120\ucd95\uc744 \ub300\uc751\uc2dc\ud0a4\uba74, \uac01 \uad00\uc808\uc774 \uc21c\uc11c\ub300\ub85c \ub9cc\ub4e4\uc5b4 \ub0b4\ub294 \uc6b4\ub3d9\uc744 \uc870\ud569\ud574 \ub85c\ubd07 \uc804\uccb4\ub97c \ubaa8\ub378\ub9c1\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\ub9d0\ub2e8 \uc7a5\uce58\uc758 pose\ub294 \ub2e4\uc74c\uacfc \uac19\uc774 \ud45c\ud604\ub429\ub2c8\ub2e4.\\n\\n$$\\nT_{sb}(\\\\theta) = e^{\\\\hat{\\\\xi}_1 \\\\theta_1} e^{\\\\hat{\\\\xi}_2 \\\\theta_2} \\\\cdots e^{\\\\hat{\\\\xi}_n \\\\theta_n} T_{sb}(0),\\n$$\\n\\n\uc5ec\uae30\uc11c $T_{sb}(0)$\uc740 \ubca0\uc774\uc2a4\uc5d0 \ub300\ud55c \ub9d0\ub2e8 \uc7a5\uce58\uc758 \ucd08\uae30 configuration\uc785\ub2c8\ub2e4.\\n\\n\uc774\uac83\uc774 Product of Exponentials \uacf5\uc2dd\uc785\ub2c8\ub2e4. \uac01 \uad00\uc808 \uc6b4\ub3d9\uc774 \ub9cc\ub4e4\uc5b4 \ub0b4\ub294 \ubcc0\ud658\uc744 \uacf1\ud558\uba74 \ub85c\ubd07\uc758 \ub9d0\ub2e8 \uc7a5\uce58 \ubcc0\ud658\uc744 \uc5bb\ub294\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4.\\n\\n\uc774\ub294 \ub2e8\uc21c\ud55c \ud45c\uae30\uc0c1\uc758 \ud3b8\uc758\uac00 \uc544\ub2d9\ub2c8\ub2e4. \ub85c\ubd07 \uc804\uccb4\uc758 \uc6b4\ub3d9\uc774 \uac01\uac01\uc758 \ub098\uc120\ucd95\uc744 \ub530\ub978 \uc6b4\ub3d9\uc758 \ud569\uc131\uc774\ub77c\ub294 \uae30\ud558\ud559\uc801 \uc0ac\uc2e4\uc744 \ub098\ud0c0\ub0c5\ub2c8\ub2e4. \uac15\uccb4 \ubcc0\ud658\uc740 \uacf1\uc148\uc73c\ub85c \ud569\uc131\ub418\ubbc0\ub85c \ucd5c\uc885 pose\uac00 \uc790\uc5f0\uc2a4\ub7fd\uac8c \uc9c0\uc218 \ud568\uc218\uc758 \uacf1\uc73c\ub85c \ud45c\ud604\ub429\ub2c8\ub2e4.\\n\\n\ube0c\ub77c\uc6b0\uc800 \ub370\ubaa8\ub3c4 \uc774 \uc815\uc2dd\ud654\ub97c \ubc14\ud0d5\uc73c\ub85c \uad6c\ud604\ud588\uc2b5\ub2c8\ub2e4. \ub85c\ubd07\uc740 \uad00\uc808\ucd95\uc73c\ub85c \uad6c\uc131\ub418\uace0, \uac01 \ubcc0\ud658\uc744 \uc774\uc6a9\ud574 \ub9d0\ub2e8 \uc7a5\uce58 pose\ub97c \uc2e4\uc2dc\uac04\uc73c\ub85c \ub2e4\uc2dc \uacc4\uc0b0\ud569\ub2c8\ub2e4.\\n\\n## 7. Twist \uc815\uc2dd\ud654\uc5d0\uc11c \uc790\uc5f0\uc2a4\ub7fd\uac8c \ub098\uc624\ub294 Jacobian\\n\\n\ub2e4\uc74c\uc73c\ub85c \uc911\uc694\ud55c \ub300\uc0c1\uc740 Jacobian\uc785\ub2c8\ub2e4. \uad00\uc808 \uc18d\ub3c4\ub97c $\\\\dot{\\\\theta}$\ub85c \ub450\uba74 \ub9d0\ub2e8 \uc7a5\uce58\uc758 twist\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.\\n\\n$$\\n\\\\nu = J(\\\\theta) \\\\dot{\\\\theta},\\n$$\\n\\n\uc5ec\uae30\uc11c $\\\\nu$\ub294 \ub9d0\ub2e8 \uc7a5\uce58\uc758 twist\uc774\uace0 $J(\\\\theta)$\ub294 Jacobian\uc785\ub2c8\ub2e4.\\n\\nJacobian\uc740 \uad00\uc808 \ubcc0\uc218\uc758 \uc791\uc740 \ubcc0\ud654\uac00 \ub9d0\ub2e8 \uc7a5\uce58 \uc18d\ub3c4\uc5d0 \uc5b4\ub5a4 \uc601\ud5a5\uc744 \uc8fc\ub294\uc9c0 \uc54c\ub824\uc90d\ub2c8\ub2e4. \uc989, \ub85c\ubd07\uc758 configuration\uacfc \uacf5\uac04\uc5d0\uc11c\uc758 \uc6b4\ub3d9\uc744 \uc787\ub294 \ud575\uc2ec \uc5f0\uacb0\uace0\ub9ac\uc785\ub2c8\ub2e4.\\n\\nConvention\uc5d0 \ub530\ub77c \ub2e4\uc74c \ub450 Jacobian\uc744 \uad6c\ubd84\ud569\ub2c8\ub2e4.\\n\\n- spatial Jacobian $J_s$\\n- body Jacobian $J_b$\\n\\nSpatial Jacobian\uc740 \uad00\uc808 \uc18d\ub3c4\uc640 spatial twist\ub97c \uc5f0\uacb0\ud569\ub2c8\ub2e4.\\n\\n$$\\n\\\\xi_s = J_s(\\\\theta)\\\\dot{\\\\theta}.\\n$$\\n\\n\uc774\ub294 \uc81c\uc5b4\uc640 \uacc4\ud68d\uc5d0\uc11c \uc911\uc694\ud569\ub2c8\ub2e4. Spatial twist\ub294 \uc6d4\ub4dc \uc88c\ud45c\uacc4\uc5d0\uc11c \ubcf8 \ub9d0\ub2e8 \uc7a5\uce58\uc758 \uc21c\uac04 \uc18d\ub3c4\ub97c \ub098\ud0c0\ub0b4\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.\\n\\nJacobian\uc740 \uadfc\ubcf8\uc801\uc73c\ub85c configuration \uc0ac\uc0c1\uc744 \uad00\uc808 \ubcc0\uc218\uc5d0 \ub300\ud574 \ubbf8\ubd84\ud55c \uacb0\uacfc\uc785\ub2c8\ub2e4. \ub2e4\uc2dc \ub9d0\ud574,\\n\\n$$\\nJ(\\\\theta) = \\\\frac{\\\\partial f}{\\\\partial \\\\theta},\\n$$\\n\\n\uc785\ub2c8\ub2e4. \uac15\uccb4 \uc6b4\ub3d9\uc774 \uc9c0\uc218 \ubcc0\ud658\uc73c\ub85c \ud45c\ud604\ub418\uae30 \ub54c\ubb38\uc5d0, \uc774 \ubbf8\ubd84\uc744 \ub098\uc120\ucd95\uc744 \uc774\uc6a9\ud574 \uad6c\uc870\uc801\uc73c\ub85c \uae54\ub054\ud558\uac8c \uacc4\uc0b0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\nModern Robotics\uac00 \uac15\ub825\ud55c \uc774\uc720 \uc911 \ud558\ub098\uac00 \uc5ec\uae30\uc5d0 \uc788\uc2b5\ub2c8\ub2e4. Jacobian\uc740 \ub098\uc911\uc5d0 \ub367\ubd99\uc778 \ud589\ub82c\uc774 \uc544\ub2c8\ub77c \ub85c\ubd07 \uc6b4\ub3d9\uc758 \uae30\ud558\uc640 \uc790\uc5f0\uc2a4\ub7fd\uac8c \uc5f0\uacb0\ub41c \uacb0\uacfc\uc785\ub2c8\ub2e4.\\n\\n## 8. \uc774 \uc815\uc2dd\ud654\uac00 \uc2e4\uc81c\ub85c \uc911\uc694\ud55c \uc774\uc720\\n\\n\uc55e\uc5d0\uc11c \ub2e4\ub8ec \uc218\ud559\uc801 \uad6c\uc870\ub294 \ubcf4\uae30 \uc88b\uc740 \ucd94\uc0c1\ud654\uc5d0 \uadf8\uce58\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \ub85c\ubd07\uc744 \uc2e4\uc81c\ub85c \uc6c0\uc9c1\uc774\uac8c \ub9cc\ub4dc\ub294 \uc54c\uace0\ub9ac\uc998\uc758 \ubc14\ud0d5\uc785\ub2c8\ub2e4.\\n\\n- \uc21c\uae30\uad6c\ud559\uc740 \uad00\uc808 \uac12\uc73c\ub85c\ubd80\ud130 \ub9d0\ub2e8 \uc7a5\uce58 pose\ub97c \uacc4\uc0b0\ud569\ub2c8\ub2e4.\\n- \uc5ed\uae30\uad6c\ud559\uc740 \ubaa9\ud45c pose\ub97c \ub9cc\ub4e4 \uc218 \uc788\ub294 \uad00\uc808 \ubcc0\uc218\ub97c \ucc3e\uc2b5\ub2c8\ub2e4.\\n- Jacobian\uc740 \uad00\uc808 \uc18d\ub3c4\uc640 \uc791\uc5c5 \uacf5\uac04 \uc6b4\ub3d9\uc744 \uc5f0\uacb0\ud569\ub2c8\ub2e4.\\n- \uada4\uc801 \uacc4\ud68d\uc740 \uc774 \uac12\ub4e4\uc744 \uc774\uc6a9\ud574 \uc2e4\ud589 \uac00\ub2a5\ud55c \uc6b4\ub3d9\uc744 \uc0dd\uc131\ud569\ub2c8\ub2e4.\\n- \ub3d9\uc5ed\ud559\uacfc \uc81c\uc5b4\ub294 \uac19\uc740 \uae30\ud558\ud559\uc801 \ud45c\ud604 \uc704\uc5d0 \uc138\uc6cc\uc9d1\ub2c8\ub2e4.\\n\\n\ube0c\ub77c\uc6b0\uc800 \ub370\ubaa8\uac00 \uc720\uc6a9\ud55c \uc774\uc720\ub294 \uc774\ub7f0 \uac1c\ub150\ub4e4\uc744 \uc9c1\uc811 \ub208\uc73c\ub85c \ud655\uc778\ud560 \uc218 \uc788\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4. \uc2ac\ub77c\uc774\ub354\ub97c \uc6c0\uc9c1\uc774\uba74 $\\\\theta_i$\uac00 \ubc14\ub00c\uace0, \uc774\uc5d0 \ub530\ub77c $T_{sb}$\uac00 \uac31\uc2e0\ub429\ub2c8\ub2e4. \uadf8\ub7ec\uba74 \ub9d0\ub2e8 \uc7a5\uce58 pose\uac00 \ubcc0\ud558\uace0, \ub3d9\uc2dc\uc5d0 \ub85c\ubd07\uc758 \uc21c\uac04 \uc6b4\ub3d9\uacfc \ub3c4\ub2ec \uac00\ub2a5\ud55c \uc791\uc5c5 \uacf5\uac04\ub3c4 \ub2ec\ub77c\uc9d1\ub2c8\ub2e4.\\n\\n\uc989, \uc774 \ub370\ubaa8\ub294 \ub2e8\uc21c\ud55c \uc2dc\uac01\ud654 \uc7a5\ub09c\uac10\uc774 \uc544\ub2d9\ub2c8\ub2e4. \ub2e4\uc74c \uc218\ud559\uc801 \ud750\ub984\uc744 \uc9c1\uc811 \uad6c\ud604\ud55c \uacb0\uacfc\uc785\ub2c8\ub2e4.\\n\\n$$\\n\\\\theta \\\\rightarrow T_{sb}(\\\\theta) \\\\rightarrow \\\\xi \\\\rightarrow J(\\\\theta) \\\\rightarrow \\\\text{motion}.\\n$$\\n\\n## 9. \ud575\uc2ec \uac1c\ub150 \uc815\ub9ac\\n\\nModern Robotics\uc758 \ud575\uc2ec\uc740 \ub2e4\uc74c \uba87 \uac00\uc9c0\ub85c \uc694\uc57d\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n1. \ub85c\ubd07\uc740 configuration\uc744 \ud558\ub098\uc758 \ubcc0\ud658\uc73c\ub85c \ud45c\ud604\ud558\ub294 \uac15\uccb4 \uba54\ucee4\ub2c8\uc998\uc785\ub2c8\ub2e4.\\n2. \uc21c\uac04 \uc6b4\ub3d9\uc740 twist\ub85c \ud45c\ud604\ud569\ub2c8\ub2e4.\\n3. \uad00\uc808\uc740 \ub098\uc120\ucd95\uc744 \ub530\ub77c \uc6b4\ub3d9\uc744 \ub9cc\ub4e4\uc5b4 \ub0c5\ub2c8\ub2e4.\\n4. \uc720\ud55c\ud55c \uc6b4\ub3d9\uc740 \uc9c0\uc218 \uc0ac\uc0c1\uc73c\ub85c \uc0dd\uc131\ud569\ub2c8\ub2e4.\\n5. \ub85c\ubd07 \uc804\uccb4\uc758 \uc6b4\ub3d9\uc740 \uc774\ub7ec\ud55c \uc9c0\uc218 \ubcc0\ud658\ub4e4\uc758 \ud569\uc131\uc785\ub2c8\ub2e4.\\n6. Jacobian\uc740 \uad00\uc808 \uc18d\ub3c4\uc640 \ub9d0\ub2e8 \uc7a5\uce58 twist \uc0ac\uc774\uc758 \uc120\ud615 \uc0ac\uc0c1\uc785\ub2c8\ub2e4.\\n\\n\uc774 \ucd94\uc0c1\ud654\ub294 \ub85c\ubd07 \uae30\uad6c\ud559\uacfc \ub3d9\uc5ed\ud559\uc744 \ub354 \uc6b0\uc544\ud558\uac8c \ub9cc\ub4e4 \ubfd0 \uc544\ub2c8\ub77c, \uc2dc\ubbac\ub808\uc774\uc158\xb7\uacc4\ud68d\xb7\uc81c\uc5b4 \uc804\ubc18\uc744 \uc77c\uad00\ub418\uac8c \ucd94\ub860\ud558\uace0 \uad6c\ud604\ud558\uae30 \uc27d\uac8c \ud574\uc90d\ub2c8\ub2e4.\\n\\n## 10. \ub2e4\uc74c \uae00\uc5d0\uc11c \ub2e4\ub8f0 \ub0b4\uc6a9\\n\\n\uc774\ubc88 \uae00\uc5d0\uc11c\ub294 \uc804\uccb4 \uc2dc\ub9ac\uc988\uc758 \uae30\ucd08\ub97c \ub193\uc558\uc2b5\ub2c8\ub2e4. \ub2e4\uc74c \uae00\ubd80\ud130\ub294 \ub2e4\uc74c \uc8fc\uc81c\ub97c \ub354 \uc790\uc138\ud788 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.\\n\\n- \ub098\uc120\ucd95\uc758 \uad6c\uccb4\uc801\uc778 \uae30\ud558\\n- Product of Exponentials\ub97c \uc774\uc6a9\ud55c \uc21c\uae30\uad6c\ud559\\n- Jacobian \uad6c\uc131\uacfc \uc2e4\uc81c \uacc4\uc0b0\\n- \uc5ed\uae30\uad6c\ud559\uacfc \uada4\uc801 \uc0dd\uc131\\n- \uc774\ub7ec\ud55c \uac1c\ub150\uc774 interactive `modern-robotics-wasm` \uad6c\ud604\uc5d0 \ub098\ud0c0\ub098\ub294 \ubc29\uc2dd\\n\\n\ubaa9\ud45c\ub294 \uc6b0\uc544\ud55c \uc218\ud559\uc744 \ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c \uc2e4\uc81c\ub85c \ub85c\ubd07\uc744 \uc6c0\uc9c1\uc774\ub294 \uc18c\ud504\ud2b8\uc6e8\uc5b4\uc640 \uc5f0\uacb0\ud558\ub294 \uac83\uc785\ub2c8\ub2e4.\\n\\n\ub2e4\uc74c \uae00\uc5d0\uc11c\ub294 \ub098\uc120\ucd95\uc744 \ub354 \uc790\uc138\ud788 \uc0b4\ud3b4\ubcf4\uace0, \uad00\uc808 \uc6b4\ub3d9\uc774 \uc9c0\uc218 \uc0ac\uc0c1\uc744 \ud1b5\ud574 \uc5b4\ub5bb\uac8c \uc790\uc5f0\uc2a4\ub7fd\uac8c \uac15\uccb4 \uc6b4\ub3d9\uc744 \ub9cc\ub4e4\uc5b4 \ub0b4\ub294\uc9c0 \uc54c\uc544\ubcf4\uaca0\uc2b5\ub2c8\ub2e4."},{"id":"modern-robotics-part-2","metadata":{"permalink":"/ko/blog/modern-robotics-part-2","editUrl":"https://github.com/CMaybe/cmaybe.github.io/tree/main/blog/2026-09-07-modern-robotics-part-2a.md","source":"@site/i18n/ko/docusaurus-plugin-content-blog/2026-09-07-modern-robotics-part-2a.md","title":"Modern Robotics, Part 2A - \ub098\uc120\ucd95, Twist, \uadf8\ub9ac\uace0 \uc9c0\uc218 \uc0ac\uc0c1","description":"Modern Robotics\uc758 \ub098\uc120\ucd95, twist, \uc9c0\uc218 \uc0ac\uc0c1\uc744 \uc790\uc138\ud788 \uc0b4\ud3b4\ubcf4\uace0 \uc774\ub97c \ub85c\ubd07 \uae30\uad6c\ud559\uacfc Jacobian \uacc4\uc0b0\uc73c\ub85c \uc5f0\uacb0\ud569\ub2c8\ub2e4.","date":"2026-09-07T00:00:00.000Z","tags":[{"inline":false,"label":"Robotics","permalink":"/ko/blog/tags/robotics","description":"Robot software, systems, and experiments."},{"inline":false,"label":"Modern Robotics","permalink":"/ko/blog/tags/modern-robotics","description":"Concepts, methods, and intuition behind rigid-body motion and robot kinematics."},{"inline":false,"label":"Kinematics","permalink":"/ko/blog/tags/kinematics","description":"Forward and inverse kinematics for robots."},{"inline":false,"label":"Screw Theory","permalink":"/ko/blog/tags/screw-theory","description":"Twists, screw axes, and the geometry of rigid-body motion."}],"readingTime":6.46,"hasTruncateMarker":true,"authors":[{"name":"Jaegyeom Kim","title":"Robotics Software Engineer","url":"https://github.com/CMaybe","page":{"permalink":"/ko/blog/authors/endi"},"socials":{"github":"https://github.com/CMaybe","linkedin":"https://www.linkedin.com/in/Jaegyeom-kim-185b8a2a4/"},"imageURL":"https://github.com/CMaybe.png","key":"endi"}],"frontMatter":{"slug":"modern-robotics-part-2","title":"Modern Robotics, Part 2A - \ub098\uc120\ucd95, Twist, \uadf8\ub9ac\uace0 \uc9c0\uc218 \uc0ac\uc0c1","authors":["endi"],"tags":["robotics","modern-robotics","kinematics","screw-theory"],"description":"Modern Robotics\uc758 \ub098\uc120\ucd95, twist, \uc9c0\uc218 \uc0ac\uc0c1\uc744 \uc790\uc138\ud788 \uc0b4\ud3b4\ubcf4\uace0 \uc774\ub97c \ub85c\ubd07 \uae30\uad6c\ud559\uacfc Jacobian \uacc4\uc0b0\uc73c\ub85c \uc5f0\uacb0\ud569\ub2c8\ub2e4."},"unlisted":false,"prevItem":{"title":"Modern Robotics, Part 1 - \uac15\uccb4 \uc6b4\ub3d9\uacfc \uc9c0\uc218 \uacf1 \uacf5\uc2dd","permalink":"/ko/blog/modern-robotics-part-1"},"nextItem":{"title":"Modern Robotics, Part 2B \u2014 \uc88c\ud45c\uacc4, Lie group, \uadf8\ub9ac\uace0 Jacobian\uc758 \uc5f0\uacb0","permalink":"/ko/blog/modern-robotics-part-2b"}},"content":"\uc9c0\ub09c \uae00\uc5d0\uc11c\ub294 \ub85c\ubd07 \uc6b4\ub3d9\uc744 \ub2e8\uc21c\ud788 \uad00\uc808 \uac01\ub3c4\uc758 \ubaa8\uc74c\uc73c\ub85c \ubcf4\uae30\ubcf4\ub2e4 \uacf5\uac04\uc5d0\uc11c \uc77c\uc5b4\ub098\ub294 \uac15\uccb4 \uc6b4\ub3d9\uc73c\ub85c \uc774\ud574\ud574\uc57c \ud55c\ub2e4\ub294 \uc810\uc744 \uc0b4\ud3b4\ubd24\uc2b5\ub2c8\ub2e4. \ud575\uc2ec \ub300\uc0c1\uc740 \ud68c\uc804\uacfc \ubcd1\uc9c4\uc744 \ud568\uaed8 \ub098\ud0c0\ub0b4\ub294 \ubcc0\ud658\\n\\n$$\\nT \\\\in SE(3),\\n$$\\n\\n\uc600\uc2b5\ub2c8\ub2e4. \uc774\uc81c \uad00\uc808\uc774 \uc6c0\uc9c1\uc77c \ub54c \uc774 \ubcc0\ud658\uc774 \uc5f0\uc18d\uc801\uc73c\ub85c \uc5b4\ub5bb\uac8c \ubcc0\ud558\ub294\uc9c0 \uc54c\uc544\ubcfc \ucc28\ub840\uc785\ub2c8\ub2e4.\\n\\n\uc5ec\uae30\uc11c \ub098\uc120\ucd95\uacfc twist\uac00 \ub4f1\uc7a5\ud569\ub2c8\ub2e4. \uc774 \ub458\uc740 \ubbf8\uc18c \uac15\uccb4 \uc6b4\ub3d9\uc744 \uac04\uacb0\ud558\uace0 \uae30\ud558\ud559\uc801\uc73c\ub85c \uc758\ubbf8 \uc788\ub294 \ubc29\uc2dd\uc73c\ub85c \ud45c\ud604\ud558\uba70, \uc9c0\uc218 \uc0ac\uc0c1\uc744 \ud1b5\ud574 \uc720\ud55c\ud55c \uc6b4\ub3d9\uacfc \uc5f0\uacb0\ud569\ub2c8\ub2e4.\\n\\n\x3c!-- truncate --\x3e\\n\\n## 1. \uac15\uccb4\uc758 \ubbf8\uc18c \uc6b4\ub3d9\\n\\n\uac15\uccb4\uac00 $\\\\mathbb{R}^3$ \uc548\uc5d0\uc11c \uc6c0\uc9c1\uc778\ub2e4\uace0 \ud569\uc2dc\ub2e4. \uac15\uccb4\uc758 \uc21c\uac04 \uc6b4\ub3d9\uc740 \ub2e4\uc74c \ub450 \uc591\uc73c\ub85c \ud45c\ud604\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n- \uac01\uc18d\ub3c4 $\\\\omega \\\\in \\\\mathbb{R}^3$\\n- \uc120\uc18d\ub3c4 $v \\\\in \\\\mathbb{R}^3$\\n\\n\uc774 \ub458\uc744 \ud569\uce58\uba74 twist\uac00 \ub429\ub2c8\ub2e4.\\n\\n$$\\n\\\\xi = \\\\begin{bmatrix}\\n\\\\omega \\\\\\\\\\n v\\n\\\\end{bmatrix}.\\n$$\\n\\nTwist\ub294 \ub2e8\uc21c\ud788 \ub450 \ubca1\ud130\ub97c \ud55c\ub370 \ubb36\uc740 \uac83\uc774 \uc544\ub2d9\ub2c8\ub2e4. \uac15\uccb4 \uc804\uccb4\uc758 \uc18d\ub3c4\uc7a5\uc744 \ud45c\ud604\ud569\ub2c8\ub2e4. \uac15\uccb4 \uc704\uc758 \ud55c \uc810 $p$\uc758 \uc704\uce58 \ubca1\ud130\uac00 $p$\ub77c\uba74, \uadf8 \uc810\uc758 \uc18d\ub3c4\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.\\n\\n$$\\nv_p = \\\\omega \\\\times p + v.\\n$$\\n\\n\uac15\uccb4 \uc6b4\ub3d9\uc774 \ud2b9\ubcc4\ud55c \uc774\uc720\uac00 \ubc14\ub85c \uc5ec\uae30\uc5d0 \uc788\uc2b5\ub2c8\ub2e4. \ubcd1\uc9c4 \uc18d\ub3c4\ub294 \uc784\uc758\ub85c \uc815\ud574\uc9c0\ub294 \uac12\uc774 \uc544\ub2c8\ub77c \uac01\uc18d\ub3c4\uc640 \uac15\uccb4\uc758 \uae30\ud558\uc5d0 \ub530\ub77c \uacb0\uc815\ub429\ub2c8\ub2e4.\\n\\n\ud589\ub82c\ub85c \uc4f0\uba74 \uac15\uccb4\uc758 \uc18d\ub3c4\ub294 \ub2e4\uc74c\uacfc \uac19\uc774 \ud45c\ud604\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n$$\\n\\\\begin{bmatrix}\\n\\\\dot{p} \\\\\\\\\\n\\\\omega\\n\\\\end{bmatrix}\\n=\\n\\\\begin{bmatrix}\\n[\\\\omega] & v \\\\\\\\\\n0 & 0\\n\\\\end{bmatrix}\\n\\\\begin{bmatrix}\\n p \\\\\\\\\\n1\\n\\\\end{bmatrix},\\n$$\\n\\n\uadf8\ub9ac\uace0 \ubcf4\ud1b5 \ub2e4\uc74c\ucc98\ub7fc \uac04\ub2e8\ud788 \uc501\ub2c8\ub2e4.\\n\\n$$\\n\\\\hat{\\\\xi} =\\n\\\\begin{bmatrix}\\n[\\\\omega] & v \\\\\\\\\\n0 & 0\\n\\\\end{bmatrix}.\\n$$\\n\\n\uc5ec\uae30\uc11c $[\\\\omega]$\ub294 \uc678\uc801 \uc5f0\uc0b0\uc790\uc5d0 \ub300\uc751\ud558\ub294 \ubc18\ub300\uce6d \ud589\ub82c\uc785\ub2c8\ub2e4.\\n\\n$$\\n[\\\\omega]x = \\\\omega \\\\times x.\\n$$\\n\\n\uc774 \uad6c\uc870 \ub355\ubd84\uc5d0 \ub85c\ubd07 \uae30\uad6c\ud559\uc744 \ubbf8\ubd84\uae30\ud558\ud559\uc801\uc73c\ub85c \ub2e4\ub8f0 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n## 2. \uc6b4\ub3d9 \uc0dd\uc131\uc790\ub85c\uc11c\uc758 twist\\n\\n\ub85c\ubd07 \uad00\uc808\uc774 $\\\\dot{\\\\theta}$\uc758 \uc18d\ub3c4\ub85c \uc6c0\uc9c1\uc778\ub2e4\uace0 \ud569\uc2dc\ub2e4. \uadf8\ub7ec\uba74 \ub9d0\ub2e8 \uc7a5\uce58\uc758 \uc6b4\ub3d9\uc740 \uadf8 \uc18d\ub3c4\ub9cc\ud07c \uc2a4\ucf00\uc77c\ub41c twist\uc5d0 \uc758\ud574 \uc0dd\uc131\ub429\ub2c8\ub2e4.\\n\\n$$\\n\\\\dot{T} = \\\\hat{\\\\xi}\\\\,\\\\dot{\\\\theta}\\\\,T.\\n$$\\n\\n\uc774 \uc2dd\uc740 \uac15\uccb4 \ubcc0\ud658\uc758 \ubcc0\ud654\uc728\uc774 \uc6b4\ub3d9 \uc0dd\uc131\uc790 $\\\\hat{\\\\xi}$\uc640 \uc2a4\uce7c\ub77c \uad00\uc808 \uc6b4\ub3d9 $\\\\dot{\\\\theta}$\uc5d0 \uc758\ud574 \uacb0\uc815\ub41c\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4.\\n\\n\ub530\ub77c\uc11c twist\ub294 \ub85c\ubd07 \uc6b4\ub3d9\uc758 \ubbf8\uc18c \uc0dd\uc131\uc790 \uc5ed\ud560\uc744 \ud569\ub2c8\ub2e4. configuration \uacf5\uac04\uc758 \ubcc0\uc218\ub97c \uc791\uc5c5 \uacf5\uac04\uc758 \ubcc0\ud658\uc73c\ub85c \uc5f0\uacb0\ud569\ub2c8\ub2e4.\\n\\n\ub2e4\ub974\uac8c \ub9d0\ud558\uba74 \ub85c\ubd07\uc740 \uad00\uc808 \uac01\ub3c4 \uc9d1\ud569\ub9cc\uc73c\ub85c \uc124\uba85\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uac01 \uad00\uc808\uc5d0\ub294 \uace0\uc720\ud55c \uc6b4\ub3d9 \uc0dd\uc131\uc790\uac00 \ub300\uc751\ud558\uace0, \uc804\uccb4 \uc6b4\ub3d9\uc740 \uc774 \uc0dd\uc131\uc790\ub4e4\uc744 \uc870\ud569\ud574 \ub9cc\ub4ed\ub2c8\ub2e4.\\n\\n## 3. \uad00\uc808 \uc6b4\ub3d9\uc758 \uae30\ud558\ud559\uc801 \ud45c\ud604\uc778 \ub098\uc120\ucd95\\n\\n\ub098\uc120\ucd95\uc740 \uad00\uc808\uc758 \uc791\uc6a9\uc73c\ub85c \uac15\uccb4\uac00 \uc6c0\uc9c1\uc774\ub294 \uacf5\uac04\uc0c1\uc758 \uc9c1\uc120\uc744 \ub098\ud0c0\ub0c5\ub2c8\ub2e4. \ud68c\uc804 \uad00\uc808\uc5d0\uc11c\ub294 \ucd95\uc744 \uc911\uc2ec\uc73c\ub85c \ud68c\uc804\ud558\uace0, \uc9c1\ub3d9 \uad00\uc808\uc5d0\uc11c\ub294 \ucd95\uc744 \ub530\ub77c \ubcd1\uc9c4\ud569\ub2c8\ub2e4.\\n\\n\uc77c\ubc18\uc801\uc778 \ub098\uc120\ucd95\uc740 \ub2e4\uc74c\uacfc \uac19\uc774 \ud45c\ud604\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n$$\\n\\\\mathcal{S} = \\\\begin{bmatrix}\\n\\\\omega \\\\\\\\\\n v_0\\n\\\\end{bmatrix},\\n$$\\n\\n\uc5ec\uae30\uc11c \ub2e4\uc74c\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4.\\n\\n- $\\\\omega$\ub294 \ucd95\uc758 \ubc29\ud5a5\uc785\ub2c8\ub2e4.\\n- $v_0$\ub294 \ucd95 \uc704\uc758 \ud55c \uc810\uc774 \uac16\ub294 \uc120\uc18d\ub3c4\uc785\ub2c8\ub2e4.\\n\\n\ubc29\ud5a5 $\\\\omega$\ub97c \uac00\uc9c0\uba70 \uc810 $q$\ub97c \uc9c0\ub098\ub294 \uc9c1\uc120\uc744 \uc911\uc2ec\uc73c\ub85c \uc21c\uc218 \ud68c\uc804\ud55c\ub2e4\uba74 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.\\n\\n$$\\n\\\\mathcal{S} = \\\\begin{bmatrix}\\n\\\\omega \\\\\\\\\\n-\\\\omega \\\\times q\\n\\\\end{bmatrix}.\\n$$\\n\\n\uc774 \uc2dd\uc740 \ud68c\uc804\ucd95\uc758 \ubc29\ud5a5\uc774 twist\uc758 \ubcd1\uc9c4 \uc131\ubd84\uc744 \uc5b4\ub5bb\uac8c \uacb0\uc815\ud558\ub294\uc9c0 \uc815\ud655\ud788 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.\\n\\n\ud68c\uc804 \uad00\uc808\uc5d0\uc11c\ub294 \ubcf4\ud1b5 \ub098\uc120\ucd95\uc744 \uc815\uaddc\ud654\ud574 $\\\\omega$\ub97c \ub2e8\uc704 \ubca1\ud130\ub85c \ub9cc\ub4e4\uace0, \uc6b4\ub3d9 \ubcc0\uc218 $\\\\theta$\ub97c \uad00\uc808 \uac01\ub3c4\ub85c \uc0ac\uc6a9\ud569\ub2c8\ub2e4. \uc9c1\ub3d9 \uad00\uc808\uc5d0\uc11c\ub294 \uac01 \uc131\ubd84\uc774 0\uc774\uace0 \ubcd1\uc9c4 \uc131\ubd84\uc774 \ubbf8\ub044\ub7ec\uc9c0\ub294 \ubc29\ud5a5\uc744 \uac00\ub9ac\ud0b5\ub2c8\ub2e4.\\n\\n\ub530\ub77c\uc11c \ub098\uc120\ucd95\uc740 \uacf5\uac04\uc5d0\uc11c \uad00\uc808 \uc6b4\ub3d9\uc744 \uae30\ud558\ud559\uc801\uc73c\ub85c \ub098\ud0c0\ub0b8\ub2e4\uace0 \ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n## 4. \ub85c\ubd07\uacf5\ud559\uc5d0\uc11c \ub098\uc120\ucd95\uc774 \uc790\uc5f0\uc2a4\ub7ec\uc6b4 \uc774\uc720\\n\\n\ub85c\ubd07\uc758 \uae30\ud558\ub294 \ubcf4\ud1b5 \ub9c1\ud06c\uc758 \uc704\uce58\uc640 \ubc29\ud5a5\uc73c\ub85c \uc124\uba85\ud569\ub2c8\ub2e4. \ub098\uc120\ucd95\uc740 \uac19\uc740 \uc815\ubcf4\ub97c \uc6b4\ub3d9 \uc0dd\uc131\uc5d0 \ud6e8\uc52c \uc720\uc6a9\ud55c \ubc29\uc2dd\uc73c\ub85c \ub2f4\uc544\ub0c5\ub2c8\ub2e4.\\n\\n\ud68c\uc804 \uad00\uc808\uc740 \ub2e8\uc21c\ud55c \uc2a4\uce7c\ub77c \uac01\ub3c4\uac00 \uc544\ub2d9\ub2c8\ub2e4. 3\ucc28\uc6d0 \uacf5\uac04\uc758 \ud55c \uc9c1\uc120\uc744 \uc911\uc2ec\uc73c\ub85c \ud558\ub294 \uac15\uccb4 \uc6b4\ub3d9\uc785\ub2c8\ub2e4. \uc9c1\ub3d9 \uad00\uc808 \uc5ed\uc2dc \ud55c \uc9c1\uc120\uc744 \ub530\ub978 \uac15\uccb4 \uc6b4\ub3d9\uc785\ub2c8\ub2e4. \uad00\uc808\uc758 \uc9c4\uc9dc \uae30\ud558\ud559\uc801 \uc815\uccb4\uc131\uc740 \uadf8 \ucd95\uc5d0 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\ub098\uc120\ucd95\uc774 \uc815\ud574\uc9c0\uba74 \uad00\uc808 \ubcc0\uc218 $\\\\theta$\uac00 \ub9cc\ub4e4\uc5b4 \ub0b4\ub294 \uc6b4\ub3d9\ub3c4 \uc644\uc804\ud788 \uc815\ud574\uc9d1\ub2c8\ub2e4.\\n\\n- \uad00\uc808 \ubcc0\uc218 $\\\\theta_i$\\n- \ub098\uc120\ucd95 $\\\\mathcal{S}_i$\\n- \ub300\uc751\ud558\ub294 \uac15\uccb4 \uc6b4\ub3d9 $e^{\\\\hat{\\\\mathcal{S}}_i \\\\theta_i}$\\n\\n\uc774 \uad6c\uc870\uac00 Modern Robotics\uc5d0\uc11c \ub85c\ubd07 \uae30\uad6c\ud559\uc758 \ud1a0\ub300\uac00 \ub429\ub2c8\ub2e4.\\n\\n## 5. \uc9c0\uc218 \uc0ac\uc0c1\uacfc \uc720\ud55c\ud55c \uc6b4\ub3d9\\n\\n\uc55e\uc5d0\uc11c \uc124\uba85\ud55c \ubbf8\ubd84 \uad00\uacc4\ub9cc\uc73c\ub85c\ub294 \ucda9\ubd84\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uc21c\uac04 \uc6b4\ub3d9\uc744 \uad00\uc808 \ubcc0\uc704\uc5d0 \uac78\uce5c \uc720\ud55c\ud55c \ubcc0\ud658\uc73c\ub85c \uc801\ubd84\ud560 \ubc29\ubc95\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.\\n\\n\uadf8 \uc5ed\ud560\uc744 \ud558\ub294 \uac83\uc774 \uc9c0\uc218 \uc0ac\uc0c1\uc785\ub2c8\ub2e4. \ub098\uc120\ucd95 $\\\\mathcal{S}$\uc640 \uad00\uc808 \uc88c\ud45c $\\\\theta$\uac00 \uc8fc\uc5b4\uc84c\uc744 \ub54c \uc720\ud55c\ud55c \uac15\uccb4 \ubcc0\ud658\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.\\n\\n$$\\nT(\\\\theta) = e^{\\\\hat{\\\\mathcal{S}}\\\\theta}.\\n$$\\n\\n\uc774 \uc2dd\uc740 Modern Robotics\ub97c \uc815\uc758\ud558\ub294 \ud575\uc2ec \uacb0\uacfc \uc911 \ud558\ub098\uc785\ub2c8\ub2e4. \uc720\ud55c\ud55c \uac15\uccb4 \uc6b4\ub3d9\uc774 \ubbf8\uc18c \uc6b4\ub3d9 \uc0dd\uc131\uc790\ub97c \uc9c0\uc218\ud654\ud574 \ub9cc\ub4e4\uc5b4\uc9c4\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4.\\n\\n\ud68c\uc804 \uad00\uc808\uc5d0\uc11c\ub294\\n\\n$$\\nT(\\\\theta) = e^{[\\\\omega]_{\\\\times}\\\\theta},\\n$$\\n\\n\uac00 \ub418\uc5b4 \ucd95 $\\\\omega$\ub97c \uc911\uc2ec\uc73c\ub85c \uac01\ub3c4 $\\\\theta$\ub9cc\ud07c \ud68c\uc804\ud55c \uac15\uccb4 \ubcc0\ud658\uc744 \uc90d\ub2c8\ub2e4.\\n\\n\uc9c1\ub3d9 \uad00\uc808\uc5d0\uc11c\ub294\\n\\n$$\\nT(d) = e^{\\\\begin{bmatrix}0 & v \\\\\\\\ 0 & 0\\\\end{bmatrix} d},\\n$$\\n\\n\uac00 \ub418\uc5b4 \ubc29\ud5a5 $v$\ub97c \ub530\ub77c \uac70\ub9ac $d$\ub9cc\ud07c \uc774\ub3d9\ud55c \ubcc0\ud658\uc744 \uc90d\ub2c8\ub2e4.\\n\\n\uc774\ub294 \ub2e8\uc21c\ud55c \uc218\ud559\uc801 \ud638\uae30\uc2ec\uc774 \uc544\ub2d9\ub2c8\ub2e4. \uc5ec\ub7ec \uae30\uad6c\ud559 \uc815\uc2dd\ud654\uc5d0\uc11c \uad00\uc808 \uac12\uc73c\ub85c \ub85c\ubd07 pose\ub97c \uacc4\uc0b0\ud558\ub294 \uc815\ud655\ud55c \ubc29\uc2dd\uc785\ub2c8\ub2e4.\\n\\n## 6. \ud589\ub82c \ub85c\uadf8\uc640 \uc5ed\uad00\uacc4\\n\\n\uc9c0\uc218 \uc0ac\uc0c1\uc740 \uc801\uc808\ud55c \uc758\ubbf8\uc5d0\uc11c \uc5ed\ubcc0\ud658\uc744 \uac16\uc2b5\ub2c8\ub2e4. \uac15\uccb4 \ubcc0\ud658 $T$\uac00 \uc8fc\uc5b4\uc9c0\uba74 \ub2e4\uc74c\uc744 \ub9cc\uc871\ud558\ub294 twist $\\\\hat{\\\\xi}$\ub97c \uacc4\uc0b0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n$$\\nT = e^{\\\\hat{\\\\xi}}.\\n$$\\n\\n\uc774\ub294 \ud589\ub82c \ub85c\uadf8\ub85c \ud45c\ud604\ub429\ub2c8\ub2e4.\\n\\n$$\\n\\\\hat{\\\\xi} = \\\\log(T).\\n$$\\n\\n\ub85c\uadf8\ub97c \uc774\uc6a9\ud558\uba74 \uc720\ud55c\ud55c \ubcc0\ud658\uc5d0\uc11c \uadf8\uc5d0 \ub300\uc751\ud558\ub294 \ubbf8\uc18c \uc6b4\ub3d9 \uc0dd\uc131\uc790\ub85c \ub418\ub3cc\uc544\uac08 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc0c1\ub300 \uc6b4\ub3d9 \ucd94\uc815\uc774\ub098 \uc81c\uc5b4\uae30 \uc124\uacc4 \uac19\uc740 \uc5ec\ub7ec \uc791\uc5c5\uc5d0\uc11c \uc774 \uad00\uacc4\uac00 \uc911\uc694\ud569\ub2c8\ub2e4.\\n\\n\uc9c0\uc218\uc640 \ub85c\uadf8\ub97c \ud568\uaed8 \uc0ac\uc6a9\ud55c\ub2e4\ub294 \uac83\uc740 \uc6b0\ub9ac\uac00 Lie group\uacfc Lie algebra\uc758 \uad6c\uc870 \uc548\uc5d0\uc11c \uc791\uc5c5\ud55c\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4.\\n\\n- \uad70 $SE(3)$\ub294 \uac15\uccb4 \ubcc0\ud658\uc744 \ub098\ud0c0\ub0c5\ub2c8\ub2e4.\\n- \ub300\uc218 $se(3)$\ub294 twist\ub97c \ub098\ud0c0\ub0c5\ub2c8\ub2e4.\\n\\n\uc774\uac83\uc774 Modern Robotics\uc758 \ubc14\ud0d5\uc774 \ub418\ub294 \uc218\ud559\uc801 \uc5b8\uc5b4\uc785\ub2c8\ub2e4.\\n\\n## 7. \uc9c0\uc218 \uc0ac\uc0c1\uc774 \uc720\uc6a9\ud55c \uc774\uc720\\n\\n\uc9c0\uc218 \uc0ac\uc0c1\uc740 \ubbf8\uc18c \uc6b4\ub3d9 \uc0dd\uc131\uc790\ub85c\ubd80\ud130 \ub9cc\ub4e4\uc5b4\uc9c4 \uc720\ud55c \uc6b4\ub3d9\uc744 \ud558\ub098\uc758 \uc77c\uad00\ub41c \ud45c\ud604\uc73c\ub85c \uc81c\uacf5\ud558\uae30 \ub54c\ubb38\uc5d0 \uc720\uc6a9\ud569\ub2c8\ub2e4.\\n\\n\ub355\ubd84\uc5d0 \ub85c\ubd07 \uc804\uccb4\ub97c \uad00\uc808 \uc6b4\ub3d9\uc758 \uc5f0\uc1c4\ub85c \ubaa8\ub378\ub9c1\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n$$\\nT_{sb}(\\\\theta) = e^{\\\\hat{\\\\mathcal{S}}_1 \\\\theta_1} e^{\\\\hat{\\\\mathcal{S}}_2 \\\\theta_2} \\\\cdots e^{\\\\hat{\\\\mathcal{S}}_n \\\\theta_n} T_{sb}(0).\\n$$\\n\\n\uc774\uac83\uc774 Product of Exponentials \uacf5\uc2dd\uc785\ub2c8\ub2e4. \uac01 \uad00\uc808 \uc6b4\ub3d9\uc740 \ub098\uc120\ucd95\uc774 \uc0dd\uc131\ud558\ub294 \ubcc0\ud658\uc774\uace0, \ucd5c\uc885 \ub9d0\ub2e8 \uc7a5\uce58 pose\ub294 \uadf8 \ubcc0\ud658\ub4e4\uc758 \uacf1\uc785\ub2c8\ub2e4.\\n\\n\uc774 \uc815\uc2dd\ud654\ub294 \uad00\uc810\uc744 \ubc14\uafc9\ub2c8\ub2e4.\\n\\n- \ubcc0\ud658 \ud589\ub82c\uc744 \uc190\uc73c\ub85c \ud558\ub098\uc529 \uc870\ub9bd\ud558\ub294 \ub300\uc2e0,\\n- \uac01 \uad00\uc808\uc758 \uc6b4\ub3d9 \uc0dd\uc131\uc790\ub85c \ub85c\ubd07\uc744 \uad6c\uc131\ud569\ub2c8\ub2e4.\\n\\n\uc774\uac83\uc774 \uc774 \uc815\uc2dd\ud654\uc758 \uac1c\ub150\uc801 \ud798\uc785\ub2c8\ub2e4.\\n\\n## 8. \uacf5\uac04 \uc88c\ud45c\uacc4\uc640 \ubb3c\uccb4 \uc88c\ud45c\uacc4\uc758 \uc5ed\ud560\\n\\n\uac15\uccb4 \uae30\uad6c\ud559\uc5d0\uc11c \ubbf8\ubb18\ud558\uc9c0\ub9cc \uc911\uc694\ud55c \ubb38\uc81c\ub294 \uae30\uc900 \uc88c\ud45c\uacc4\ub97c \uc120\ud0dd\ud558\ub294 \uac83\uc785\ub2c8\ub2e4. \ub098\uc120\ucd95\uacfc twist\ub294 \ub2e4\uc74c \uc5b4\ub290 \ucabd\uc73c\ub85c\ub3c4 \ud45c\ud604\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n- \uacf5\uac04 \uc88c\ud45c\uacc4\\n- \ubb3c\uccb4 \uc88c\ud45c\uacc4\\n\\n\uc774\uc5d0 \ub530\ub77c spatial twist\uc640 body twist\ub97c \uad6c\ubd84\ud569\ub2c8\ub2e4.\\n\\nTwist\ub97c \uacf5\uac04 \uc88c\ud45c\uacc4\uc5d0\uc11c \uc4f0\uba74 \uace0\uc815\ub41c \uc6d4\ub4dc \uc88c\ud45c\uacc4\ub97c \uae30\uc900\uc73c\ub85c \uac15\uccb4\uac00 \uc5b4\ub5bb\uac8c \uc6c0\uc9c1\uc774\ub294\uc9c0\ub97c \ub098\ud0c0\ub0c5\ub2c8\ub2e4. \ubb3c\uccb4 \uc88c\ud45c\uacc4\uc5d0\uc11c \uc4f0\uba74 \uac15\uccb4 \uc790\uc2e0\uc758 \ub85c\uceec \uc88c\ud45c\ub97c \uae30\uc900\uc73c\ub85c \ud55c \uc6b4\ub3d9\uc744 \ub098\ud0c0\ub0c5\ub2c8\ub2e4.\\n\\n\ub450 \ud45c\ud604\uc740 adjoint \ubcc0\ud658\uc73c\ub85c \uc5f0\uacb0\ub429\ub2c8\ub2e4.\\n\\n$$\\n\\\\xi_s = Ad_{T} \\\\xi_b,\\n$$\\n\\n\ub610\ub294 \ub3d9\ub4f1\ud558\uac8c\\n\\n$$\\n\\\\xi_b = Ad_{T^{-1}} \\\\xi_s.\\n$$\\n\\n\uac19\uc740 \ubb3c\ub9ac\uc801 \uc6b4\ub3d9\ub3c4 \uc11c\ub85c \ub2e4\ub978 \uc88c\ud45c\uacc4\uc5d0\uc11c \ud45c\ud604\ud560 \uc218 \uc788\uc73c\ubbc0\ub85c \uc774 \ubcc0\ud658\uc740 \uc911\uc694\ud569\ub2c8\ub2e4. \uc5b4\ub5a4 \ud45c\ud604\uc744 \uc120\ud0dd\ud558\ub290\ub0d0\uc5d0 \ub530\ub77c Jacobian\uacfc \uc81c\uc5b4 \ubc29\uc815\uc2dd\uc758 \ud615\ud0dc\ub3c4 \ub2ec\ub77c\uc9d1\ub2c8\ub2e4.\\n\\nModern Robotics\uac00 \ud2b9\ud788 \uc6b0\uc544\ud55c \uc774\uc720 \uc911 \ud558\ub098\ub294 \uc6b4\ub3d9\uc758 \uae30\ud558\uc640 \uc88c\ud45c \ud45c\ud604\uc744 \uae54\ub054\ud558\uac8c \ubd84\ub9ac\ud558\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.\\n\\n## 9. Jacobian\uacfc\uc758 \uc5f0\uacb0\\n\\nTwist \uc815\uc2dd\ud654\ub294 \uc790\uc5f0\uc2a4\ub7fd\uac8c Jacobian\uc73c\ub85c \uc774\uc5b4\uc9d1\ub2c8\ub2e4. \uad00\uc808 \ubcc0\uc218\ub97c $\\\\theta_1, \\\\dots, \\\\theta_n$\uc774\ub77c \ud558\uba74 \ub9d0\ub2e8 \uc7a5\uce58 twist\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.\\n\\n$$\\n\\\\nu = J(\\\\theta) \\\\dot{\\\\theta}.\\n$$\\n\\nJacobian\uc740 \uad00\uc808 \uc18d\ub3c4\uc5d0\uc11c \ub9d0\ub2e8 \uc7a5\uce58 twist\ub85c \uac00\ub294 \uc0ac\uc0c1\uc785\ub2c8\ub2e4. \ub85c\ubd07\uc758 \ub098\uc120\ucd95\uc744 \uc774\uc6a9\ud558\uba74 \ub2e4\uc74c\uacfc \uac19\uc774 \uacc4\uc0b0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n$$\\nJ(\\\\theta) = \\\\begin{bmatrix}\\n\\\\mathcal{S}_1 & \\\\mathcal{S}_2 & \\\\cdots & \\\\mathcal{S}_n\\n\\\\end{bmatrix},\\n$$\\n\\n\uc120\ud0dd\ud55c \uc815\uc2dd\ud654\uc5d0 \ub530\ub77c \ucd95\uc744 \uc62c\ubc14\ub978 \uc88c\ud45c\uacc4\ub85c \ubcc0\ud658\ud574\uc57c \ud569\ub2c8\ub2e4.\\n\\n\uc989, Jacobian\uc740 \uc784\uc758\ub85c \uc815\ud55c \ud589\ub82c\uc774 \uc544\ub2c8\ub77c \uad00\uc808 \uc6b4\ub3d9 \ubc29\ud5a5\uc73c\ub85c \uad6c\uc131\ub429\ub2c8\ub2e4. \uc774\uac83\uc774 Modern Robotics\uc5d0\uc11c \uac00\uc7a5 \ud1b5\ucc30\ub825 \uc788\ub294 \uac1c\ub150 \uc911 \ud558\ub098\uc785\ub2c8\ub2e4.\\n\\n\ub098\uc120\ucd95\uc744 \uc54c\uba74 \ub85c\ubd07\uc758 \ubbf8\ubd84 \uc6b4\ub3d9\uc740 \uc774\ubbf8 \uacb0\uc815\ub429\ub2c8\ub2e4. Jacobian\uc740 \uc774 \uc815\ubcf4\ub97c \ud3b8\ub9ac\ud55c \uc120\ud615 \ud615\uc2dd\uc73c\ub85c \uc815\ub9ac\ud55c \uac83\uc785\ub2c8\ub2e4.\\n\\n## 10. \uc815\uc2dd\ud654\uc5d0 \ub300\ud55c \uc9c1\uad00\\n\\n\ub2e4\uc74c\uacfc \uac19\uc774 \uc0dd\uac01\ud558\uba74 \uc774\ud574\ud558\uae30 \uc27d\uc2b5\ub2c8\ub2e4.\\n\\n- \uad00\uc808\uc740 \uc6b4\ub3d9\uc774 \uc5bc\ub9c8\ub098 \uc77c\uc5b4\ub098\ub294\uc9c0\ub97c \uc815\ud569\ub2c8\ub2e4.\\n- \ub098\uc120\ucd95\uc740 \uadf8 \uc6b4\ub3d9\uc774 \ub530\ub974\ub294 \uae30\ud558\ud559\uc801 \ubc29\ud5a5\uc744 \uc815\ud569\ub2c8\ub2e4.\\n- \uc9c0\uc218 \uc0ac\uc0c1\uc740 \ubbf8\uc18c \uc6b4\ub3d9\uc744 \uc720\ud55c\ud55c \uac15\uccb4 \ubcc0\ud658\uc73c\ub85c \ubc14\uafc9\ub2c8\ub2e4.\\n- Product of Exponentials\ub294 \uad00\uc808 \uc804\uccb4\uc758 \uc6b4\ub3d9\uc744 \ucd5c\uc885 \ub85c\ubd07 pose\ub85c \uc870\ud569\ud569\ub2c8\ub2e4.\\n\\nModern Robotics\uc758 \uccb4\uacc4\uac00 \ub85c\ubd07\uacf5\ud559\uc5d0 \uc790\uc5f0\uc2a4\ub7ec\uc6b4 \uc774\uc720\uac00 \uc5ec\uae30\uc5d0 \uc788\uc2b5\ub2c8\ub2e4. \uc11c\ub85c \uc5f0\uacb0\ub418\uc9c0 \uc54a\uc740 \uc88c\ud45c\uc2dd\ub4e4\uc744 \uc5b5\uc9c0\ub85c \ub2e4\ub8e8\ub294 \ub300\uc2e0, \uc2e4\uc81c \uc6b4\ub3d9\uc758 \uae30\ud558\ub97c \uadf8\ub300\ub85c \ubc18\uc601\ud558\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.\\n\\n## 11. \ube0c\ub77c\uc6b0\uc800 \ub370\ubaa8\uc640\uc758 \uc5f0\uacb0\\n\\n[modern-robotics-wasm](https://cmaybe.github.io/modern-robotics-wasm/) \ud504\ub85c\uc81d\ud2b8\ub294 \uc774\ub7ec\ud55c \uac1c\ub150\uc744 \uc2dc\uac01\uc801\uc73c\ub85c \uad6c\ud604\ud55c \uacb0\uacfc\uc785\ub2c8\ub2e4. \uad00\uc808 \uac01\ub3c4\uac00 \ub85c\ubd07 configuration\uc744 \ubc14\uafb8\uace0, \ubcc0\ud658 \ud589\ub82c\uc774 \ub2e4\uc2dc \uacc4\uc0b0\ub418\uba70, \ubdf0\uc5b4\uac00 \ub9d0\ub2e8 \uc7a5\uce58 pose\ub97c \uc2e4\uc2dc\uac04\uc73c\ub85c \uac31\uc2e0\ud569\ub2c8\ub2e4.\\n\\n\uc218\ud559\uc740 \uc778\ud130\ud398\uc774\uc2a4 \ub4a4\uc5d0 \uc228\uaca8\uc838 \uc788\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \ub2e4\uc74c \uad6c\uc870\ub97c \uc9c1\uc811 \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n$$\\n\\\\theta \\\\rightarrow T(\\\\theta) \\\\rightarrow \\\\nu \\\\rightarrow J(\\\\theta) \\\\dot{\\\\theta}.\\n$$\\n\\n\uad50\uacfc\uc11c\uc5d0\uc11c \ubcf4\ub358 \uac1c\ub150\uc774 \ube0c\ub77c\uc6b0\uc800\uc758 \uc778\ud130\ub799\ud2f0\ube0c \ub85c\ubd07 \ubaa8\ub378\uc744 \uc2e4\uc81c\ub85c \uc6c0\uc9c1\uc785\ub2c8\ub2e4.\\n\\n## 12. \uc815\ub9ac\\n\\n\uc774\ubc88 \uae00\uc5d0\uc11c\ub294 Modern Robotics\ub97c \uc774\ub8e8\ub294 \ub450 \uac00\uc9c0 \ud575\uc2ec \uad6c\uc870\ub97c \uc18c\uac1c\ud588\uc2b5\ub2c8\ub2e4.\\n\\n1. \uac15\uccb4\uc758 \uc21c\uac04 \uc6b4\ub3d9\uc740 twist\ub85c \ud45c\ud604\ud569\ub2c8\ub2e4.\\n2. \uc720\ud55c\ud55c \uac15\uccb4 \uc6b4\ub3d9\uc740 \ub098\uc120\ucd95 \uc6b4\ub3d9\uc744 \uc9c0\uc218\ud654\ud574 \uc0dd\uc131\ud569\ub2c8\ub2e4.\\n\\n\uc774 \ub450 \uac1c\ub150\uc73c\ub85c\ubd80\ud130 \ub098\uba38\uc9c0 \ub85c\ubd07 \uae30\uad6c\ud559\uc774 \uc774\uc5b4\uc9d1\ub2c8\ub2e4.\\n\\n- \ub9d0\ub2e8 \uc7a5\uce58 pose\ub97c \uc704\ud55c Product of Exponentials\\n- \uc6b4\ub3d9 mapping\uc744 \uc704\ud55c Jacobian\\n- \uc2e4\uc81c \ub85c\ubd07\uc744 \uc704\ud55c \uada4\uc801 \uc0dd\uc131\uacfc \uc81c\uc5b4\\n\\n\uc774\ub4e4\uc740 \uc11c\ub85c \ub5a8\uc5b4\uc9c4 \uc8fc\uc81c\uac00 \uc544\ub2d9\ub2c8\ub2e4. \ubaa8\ub450 \ub098\uc120\ucd95\uc744 \ub530\ub978 \uad6c\uc870\ud654\ub41c \uac15\uccb4 \uc6b4\ub3d9\uc73c\ub85c \ub85c\ubd07 \uc6b4\ub3d9\uc744 \uc0dd\uc131\ud55c\ub2e4\ub294 \ud558\ub098\uc758 \uae30\ud558\ud559\uc801 \uc6d0\ub9ac\ub97c \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \ub4dc\ub7ec\ub0b8 \uac83\uc785\ub2c8\ub2e4.\\n\\n\ub2e4\uc74c \uae00\uc5d0\uc11c\ub294 \uc774 \uae30\ubc18 \uc704\uc5d0\uc11c Jacobian\uc744 \uba85\uc2dc\uc801\uc73c\ub85c \uc720\ub3c4\ud558\uace0, \ub098\uc120\ucd95\uc744 \ub9d0\ub2e8 \uc7a5\uce58 \uc18d\ub3c4 \ubc0f \ub9e4\ub2c8\ud4f0\ub808\uc774\ud130\uc758 \ubbf8\ubd84 \uae30\uad6c\ud559\uacfc \uc5f0\uacb0\ud558\uaca0\uc2b5\ub2c8\ub2e4."},{"id":"modern-robotics-part-2b","metadata":{"permalink":"/ko/blog/modern-robotics-part-2b","editUrl":"https://github.com/CMaybe/cmaybe.github.io/tree/main/blog/2026-09-07-modern-robotics-part-2b.md","source":"@site/i18n/ko/docusaurus-plugin-content-blog/2026-09-07-modern-robotics-part-2b.md","title":"Modern Robotics, Part 2B \u2014 \uc88c\ud45c\uacc4, Lie group, \uadf8\ub9ac\uace0 Jacobian\uc758 \uc5f0\uacb0","description":"\ub098\uc120\ucd95 \uc774\ub860\uc758 \ub3c4\uc785\uc744 \uc774\uc5b4\uc11c spatial frame\uacfc body frame, Lie group/Lie algebra\uc758 \uc9c1\uad00, \uadf8\ub9ac\uace0 Jacobian \uad6c\uc131\uacfc\uc758 \uc5f0\uacb0\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.","date":"2026-09-07T00:00:00.000Z","tags":[{"inline":false,"label":"Robotics","permalink":"/ko/blog/tags/robotics","description":"Robot software, systems, and experiments."},{"inline":false,"label":"Modern Robotics","permalink":"/ko/blog/tags/modern-robotics","description":"Concepts, methods, and intuition behind rigid-body motion and robot kinematics."},{"inline":false,"label":"Kinematics","permalink":"/ko/blog/tags/kinematics","description":"Forward and inverse kinematics for robots."},{"inline":false,"label":"Screw Theory","permalink":"/ko/blog/tags/screw-theory","description":"Twists, screw axes, and the geometry of rigid-body motion."}],"readingTime":4.92,"hasTruncateMarker":true,"authors":[{"name":"Jaegyeom Kim","title":"Robotics Software Engineer","url":"https://github.com/CMaybe","page":{"permalink":"/ko/blog/authors/endi"},"socials":{"github":"https://github.com/CMaybe","linkedin":"https://www.linkedin.com/in/Jaegyeom-kim-185b8a2a4/"},"imageURL":"https://github.com/CMaybe.png","key":"endi"}],"frontMatter":{"slug":"modern-robotics-part-2b","title":"Modern Robotics, Part 2B \u2014 \uc88c\ud45c\uacc4, Lie group, \uadf8\ub9ac\uace0 Jacobian\uc758 \uc5f0\uacb0","authors":["endi"],"tags":["robotics","modern-robotics","kinematics","screw-theory"],"description":"\ub098\uc120\ucd95 \uc774\ub860\uc758 \ub3c4\uc785\uc744 \uc774\uc5b4\uc11c spatial frame\uacfc body frame, Lie group/Lie algebra\uc758 \uc9c1\uad00, \uadf8\ub9ac\uace0 Jacobian \uad6c\uc131\uacfc\uc758 \uc5f0\uacb0\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4."},"unlisted":false,"prevItem":{"title":"Modern Robotics, Part 2A - \ub098\uc120\ucd95, Twist, \uadf8\ub9ac\uace0 \uc9c0\uc218 \uc0ac\uc0c1","permalink":"/ko/blog/modern-robotics-part-2"},"nextItem":{"title":"Modern Robotics, Part 3 \u2014 Jacobian\uacfc \ub9d0\ub2e8 \uc7a5\uce58 \uc18d\ub3c4","permalink":"/ko/blog/modern-robotics-part-3"}},"content":"\uc774 \uae00\uc758 \uc804\ubc18\ubd80\uc5d0\uc11c\ub294 twist, screw axis, exponential map\uc744 \uc18c\uac1c\ud588\uc2b5\ub2c8\ub2e4. \ud575\uc2ec \uba54\uc2dc\uc9c0\ub294 \uac15\uccb4 \uc6b4\ub3d9\uc774 \ubbf8\uc18c \uc6b4\ub3d9 \uc0dd\uc131\uc790\uc5d0 \uc758\ud574 \ub9cc\ub4e4\uc5b4\uc9c0\uba70, \uadf8 \uc0dd\uc131\uc790\ub97c \uc9c0\uc218\ud654\ud558\uba74 \uc720\ud55c\ud55c \uc6b4\ub3d9\uc744 \uc5bb\uc744 \uc218 \uc788\ub2e4\ub294 \uac83\uc774\uc5c8\uc2b5\ub2c8\ub2e4.\\n\\n\ud6c4\ubc18\ubd80\uc5d0\uc11c\ub294 \uc2e4\uc81c\ub85c \uac00\uc7a5 \uc911\uc694\ud55c \ub2e4\uc74c \uc138 \uac00\uc9c0 \ubbf8\ubb18\ud55c \ucc28\uc774\ub97c \ub2e4\ub8f9\ub2c8\ub2e4.\\n\\n- \uac19\uc740 \uc6b4\ub3d9\uc774 \uc11c\ub85c \ub2e4\ub978 \uc88c\ud45c\uacc4\uc5d0\uc11c \uc5b4\ub5bb\uac8c \ud45c\ud604\ub418\ub294\uc9c0,\\n- Lie group / Lie algebra \uad00\uc810\uc774 \uc65c \uc790\uc5f0\uc2a4\ub7ec\uc6b4\uc9c0,\\n- screw axis \ub2e4\uc74c\uc5d0 Jacobian\uc774 \uc65c \uc790\uc5f0\uc2a4\ub7fd\uac8c \ub4f1\uc7a5\ud558\ub294\uc9c0\uc785\ub2c8\ub2e4.\\n\\n\x3c!-- truncate --\x3e\\n\\n## 1. \uac19\uc740 \uc6b4\ub3d9, \ub2e4\ub978 \uc88c\ud45c\\n\\n\uac15\uccb4 \uc6b4\ub3d9\uc740 \uc11c\ub85c \ub2e4\ub978 \uc88c\ud45c\uacc4\ub85c \ud45c\ud604\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub294 \ub85c\ubd07\uacf5\ud559\uc5d0\uc11c \uac00\uc7a5 \ud754\ud55c \ud63c\ub3d9\uc758 \uc6d0\uc778 \uc911 \ud558\ub098\uc785\ub2c8\ub2e4.\\n\\ntwist\uac00 spatial frame\uc5d0\uc11c \ud45c\ud604\ub418\uba74 \ub2e4\uc74c\uacfc \uac19\uc774 \uc501\ub2c8\ub2e4.\\n\\n$$\\n\\\\xi_s.\\n$$\\n\\nbody frame\uc5d0\uc11c \ud45c\ud604\ub418\uba74 \ub2e4\uc74c\uacfc \uac19\uc774 \uc501\ub2c8\ub2e4.\\n\\n$$\\n\\\\xi_b.\\n$$\\n\\n\uc774 \ub458\uc740 \uc11c\ub85c \ub2e4\ub978 \uc6b4\ub3d9\uc774 \uc544\ub2d9\ub2c8\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uae30\uc900 \uc88c\ud45c\uacc4\uc5d0\uc11c \uc124\uba85\ud55c \uac19\uc740 \ubb3c\ub9ac\uc801 \uc6b4\ub3d9\uc785\ub2c8\ub2e4.\\n\\n\ub450 \ud45c\ud604\uc758 \uad00\uacc4\ub294 adjoint transformation\uc73c\ub85c \uc8fc\uc5b4\uc9d1\ub2c8\ub2e4.\\n\\n$$\\n\\\\xi_s = Ad_T(\\\\xi_b),\\n$$\\n\\n\ub610\ub294 \ub3d9\uce58\ub85c\\n\\n$$\\n\\\\xi_b = Ad_{T^{-1}}(\\\\xi_s).\\n$$\\n\\n\uc774\ub294 \uc911\uc694\ud55c \uc0ac\uc2e4\uc744 \uc77c\uae68\uc6cc \uc90d\ub2c8\ub2e4. \uc6b4\ub3d9\uc740 \ubd88\ubcc0\uc774\uc9c0\ub9cc \uc88c\ud45c\ub294 \ubd88\ubcc0\uc774 \uc544\ub2d9\ub2c8\ub2e4.\\n\\n\ub2e4\uc2dc \ub9d0\ud574 twist\ub294 \ub2e8\uc21c\ud55c \ubca1\ud130\uac00 \uc544\ub2d9\ub2c8\ub2e4. \uac15\uccb4 \uc6b4\ub3d9 \ub300\uc218\uc758 \ud2b9\uc815 \ud45c\ud604\uc5d0 \uc18d\ud55c \ubca1\ud130\uc774\uba70, \uadf8 \ud45c\ud604\uc740 \uc88c\ud45c\uacc4\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9d1\ub2c8\ub2e4.\\n\\n## 2. \uc88c\ud45c\uacc4 \uc120\ud0dd\uc774 \uc911\uc694\ud55c \uc774\uc720\\n\\n\uc88c\ud45c\uacc4\ub97c \uc120\ud0dd\ud558\ub294 \uc77c\uc774 \uc911\uc694\ud55c \uc774\uc720\ub294 \uc138\uacc4\uc5d0 \uace0\uc815\ub41c \uc88c\ud45c\uacc4\uc5d0\uc11c \ud45c\ud604\ud560 \ub54c\uc640 \uc6c0\uc9c1\uc774\ub294 \ubb3c\uccb4\uc5d0 \ubd99\uc740 \uc88c\ud45c\uacc4\uc5d0\uc11c \ud45c\ud604\ud560 \ub54c \uac19\uc740 \ubb3c\ub9ac\uc801 \uc6b4\ub3d9\uc774 \ub2e4\ub974\uac8c \ubcf4\uc77c \uc218 \uc788\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.\\n\\n\uc608\ub97c \ub4e4\uc5b4 \ub9d0\ub2e8 \uc7a5\uce58\uac00 \ub85c\ubd07 \ubca0\uc774\uc2a4\uc5d0 \ub300\ud574 \uc6c0\uc9c1\uc778\ub2e4\uace0 \ud569\uc2dc\ub2e4. \uacf5\uac04 \uc88c\ud45c\uacc4 \ud45c\ud604\uc740 \ud658\uacbd \uc548\uc5d0\uc11c\uc758 \uc6b4\ub3d9\uc744 \uc124\uba85\ud560 \ub54c \uc720\uc6a9\ud569\ub2c8\ub2e4. body frame \ud45c\ud604\uc740 \ub3c4\uad6c \uc790\uccb4\ub97c \uae30\uc900\uc73c\ub85c \ud55c \uc0c1\ub300 \uc6b4\ub3d9\uc744 \uc124\uba85\ud560 \ub54c \uc720\uc6a9\ud569\ub2c8\ub2e4.\\n\\n\uc774 \uad6c\ubd84\uc740 Jacobian\uc744 \uad6c\uc131\ud560 \ub54c \ubc14\ub85c \ub098\ud0c0\ub0a9\ub2c8\ub2e4.\\n\\n- spatial Jacobian\uc740 spatial frame\uc5d0\uc11c \ud45c\ud604\ud55c \uc591\uc744 \uc0ac\uc6a9\ud569\ub2c8\ub2e4.\\n- body Jacobian\uc740 body frame\uc5d0\uc11c \ud45c\ud604\ud55c \uc591\uc744 \uc0ac\uc6a9\ud569\ub2c8\ub2e4.\\n\\n\ub450 \uc815\uc2dd\ud654\ub294 \uc218\ud559\uc801\uc73c\ub85c \ub3d9\ub4f1\ud558\uc9c0\ub9cc \uc11c\ub85c \ub2e4\ub978 \ud589\ub82c\uacfc \uacc4\uc0b0 convention\uc744 \ub9cc\ub4ed\ub2c8\ub2e4.\\n\\n\uadf8\ub798\uc11c \uae30\ud558\ud559\uc740 \uac19\uace0 \ud45c\ud604\ub9cc \ub2ec\ub77c\uc9c4\ub2e4\uace0 \ub9d0\ud569\ub2c8\ub2e4.\\n\\n## 3. \uc26c\uc6b4 \ub9d0\ub85c \ubcf4\ub294 Lie group\uacfc Lie algebra\\n\\n\uac15\uccb4 \ubcc0\ud658 group\uc740\\n\\n$$\\nSE(3)\\n$$\\n\\n\uc785\ub2c8\ub2e4.\\n\\n\uc774\uc5d0 \ub300\uc751\ud558\ub294 \ubbf8\uc18c \uc6b4\ub3d9 algebra\ub294\\n\\n$$\\nse(3)\\n$$\\n\\n\uc785\ub2c8\ub2e4.\\n\\nGroup\uc740 \ubaa8\ub4e0 \uc720\ud55c \uac15\uccb4 \ubcc0\ud658\uc758 \uc9d1\ud569\uc785\ub2c8\ub2e4. Algebra\ub294 twist\ub85c \ud45c\ud604\ub418\ub294 \ubaa8\ub4e0 \ubbf8\uc18c \uc6b4\ub3d9\uc758 \uc9d1\ud569\uc785\ub2c8\ub2e4.\\n\\nExponential map\uc740 \uc774 \ub450 \ub300\uc0c1\uc744 \uc5f0\uacb0\ud569\ub2c8\ub2e4.\\n\\n$$\\nT = e^{\\\\hat{\\\\xi}}.\\n$$\\n\\n\uc774\uac83\uc774 \uc21c\uac04 \uc6b4\ub3d9\uc5d0\uc11c \uc720\ud55c \uc6b4\ub3d9\uc73c\ub85c\uc758 \uc774\ub3d9\uc774 \uae54\ub054\ud558\uac8c \uc774\ub8e8\uc5b4\uc9c0\ub294 \uc218\ud559\uc801 \uc774\uc720\uc785\ub2c8\ub2e4.\\n\\nLie algebra\ub294 \ucd94\uc0c1\uc801\uc778 \ub300\uc0c1\uc5d0 \uadf8\uce58\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uc815\ud655\ud788 \uc6b4\ub3d9 \uc0dd\uc131\uc790\uc758 \uc9d1\ud569\uc785\ub2c8\ub2e4. twist\ub294 algebra\uc758 \uc6d0\uc18c\uc774\uace0, exponential map\uc740 \uadf8 algebra \uc6d0\uc18c\ub97c group\uc758 \uc720\ud55c \ubcc0\ud658\uc73c\ub85c \ubc14\uafc9\ub2c8\ub2e4.\\n\\n\ub85c\ubd07 \uae30\uad6c\ud559\uc774 \uc544\ub984\ub2e4\uc6b4 \uad6c\uc870\ub97c \uac16\ub294 \uc774\uc720\ub3c4 \uc5ec\uae30\uc5d0 \uc788\uc2b5\ub2c8\ub2e4. \uc720\ud55c \uc6b4\ub3d9\uc758 \uae30\ud558\ud559\uc774 \ubbf8\uc18c \uc6b4\ub3d9\uc758 algebra\uc5d0 \ub2f4\uaca8 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n## 4. \uc5ed\uad00\uacc4\ub85c\uc11c\uc758 matrix logarithm\\n\\nMatrix logarithm\uc740 \ubc18\ub300 \ubc29\ud5a5\uc744 \uc81c\uacf5\ud569\ub2c8\ub2e4.\\n\\n$$\\n\\\\hat{\\\\xi} = \\\\log(T).\\n$$\\n\\n\uc774\ub294 \uc54c\ub824\uc9c4 \uac15\uccb4 \ubcc0\ud658\uc5d0\uc11c \uadf8\uc5d0 \ub300\uc751\ud558\ub294 \ubbf8\uc18c \uc6b4\ub3d9 \uc0dd\uc131\uc790\ub97c \ubcf5\uc6d0\ud560 \ub54c \uc720\uc6a9\ud569\ub2c8\ub2e4.\\n\\n\uc5b4\ub5a4 \ub85c\ubd07\uacf5\ud559 \ubb38\uc81c\uc5d0\uc11c\ub294 \uce21\uc815\ud588\uac70\ub098 \uba85\ub839\ud55c pose\uac00 \uc8fc\uc5b4\uc9c0\uace0, \uadf8 pose\ub97c \ub9cc\ub4e4\uc5b4 \ub0b8 \uad6d\uc18c twist\ub97c \uc774\ud574\ud558\uace0 \uc2f6\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4. Logarithm\uc740 \ubc14\ub85c \uadf8 \uad6d\uc18c\uc801\uc778 \uc124\uba85\uc744 \uc81c\uacf5\ud569\ub2c8\ub2e4.\\n\\n\uc774\ub294 estimation\uacfc control\uc5d0\uc11c \ud2b9\ud788 \uc911\uc694\ud569\ub2c8\ub2e4. \uac15\uccb4 \ubcc0\ud658\uc758 \uc804\uccb4 \uc774\ub825\uc744 \uc54c \ud544\uc694 \uc5c6\uc774, \ud604\uc7ac \ubcc0\ud654\ub7c9\uc744 \uac00\uc7a5 \uc798 \uc124\uba85\ud558\ub294 \uad6d\uc18c \uc18d\ub3c4 \uc0dd\uc131\uc790\ub9cc \ud544\uc694\ud560 \ub54c\uac00 \ub9ce\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.\\n\\n## 5. \uad00\uc808\uc5d0 exponential map\uc774 \uc801\ud569\ud55c \uc774\uc720\\n\\n\ub85c\ubd07 \uad00\uc808\uc740 \uc784\uc758\uc758 \uc6b4\ub3d9\uc744 \ub9cc\ub4e4\uc5b4 \ub0b4\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \ud2b9\uc815 screw axis\ub97c \ub530\ub77c \uc6b4\ub3d9\uc744 \ub9cc\ub4e4\uc5b4 \ub0c5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uac01 \uad00\uc808\uc740 \ub2e4\uc74c \ud615\ud0dc\uc758 \uc0dd\uc131\uc790\ub97c \uc81c\uacf5\ud569\ub2c8\ub2e4.\\n\\n$$\\n\\\\hat{\\\\mathcal{S}}_i \\\\theta_i.\\n$$\\n\\n\uadf8\ub7ec\uba74 \ub9d0\ub2e8 \uc7a5\uce58\uc758 \uc804\uccb4 \uc6b4\ub3d9\uc740 \ub2e4\uc74c\uacfc \uac19\uc774 \uacb0\ud569\ub429\ub2c8\ub2e4.\\n\\n$$\\nT_{sb}(\\\\theta) = e^{\\\\hat{\\\\mathcal{S}}_1 \\\\theta_1} e^{\\\\hat{\\\\mathcal{S}}_2 \\\\theta_2} \\\\cdots e^{\\\\hat{\\\\mathcal{S}}_n \\\\theta_n} T_{sb}(0).\\n$$\\n\\n\uc774\uac83\uc774 Product of Exponentials \uacf5\uc2dd\uc774\uba70, \ub85c\ubd07\uacf5\ud559\uc5d0\uc11c \uac00\uc7a5 \uc6b0\uc544\ud55c \uc815\uc2dd\ud654 \uc911 \ud558\ub098\ub85c \uc5ec\uaca8\uc9d1\ub2c8\ub2e4.\\n\\n\ud575\uc2ec\uc740 \ub300\uc218\uc2dd \uc790\uccb4\uc5d0\ub9cc \uc788\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uac1c\ub150\uc801\uc73c\ub85c \uc911\uc694\ud55c \uc810\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.\\n\\n- \uac01 \uad00\uc808\uc774 \uae30\ud558\ud559\uc801 \uc6b4\ub3d9 \uc0dd\uc131\uc790\ub97c \uc81c\uacf5\ud569\ub2c8\ub2e4.\\n- \ub85c\ubd07\uc758 \uc804\uccb4 \uc6b4\ub3d9\uc740 \uc774 \uc0dd\uc131\uc790\ub4e4\uc758 \uacf1\uc785\ub2c8\ub2e4.\\n- \uadf8 \uad6c\uc870\ub294 \uac15\uccb4 \uc6b4\ub3d9 \uc790\uccb4\uc758 \uae30\ud558\ud559\uc5d0\uc11c \ube44\ub86f\ub429\ub2c8\ub2e4.\\n\\n\uc774 \ub54c\ubb38\uc5d0 Modern Robotics\ub294 \uc77c\uad00\ub41c \ub290\ub08c\uc744 \uc90d\ub2c8\ub2e4. \uae30\uad6c\ud559 \ubaa8\ub378\uc774 \uc6b4\ub3d9\uc758 \uae30\ud558\ud559\uacfc \uac19\uc740 \uc5b8\uc5b4\ub85c \uc791\uc131\ub418\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.\\n\\n## 6. Screw axis\uc5d0\uc11c Jacobian\uc73c\ub85c\\n\\nScrew axis\ub97c \uc54c\uac8c \ub418\uba74 \ub2e4\uc74c \ub300\uc0c1\uc774 \uc790\uc5f0\uc2a4\ub7fd\uac8c \ub4f1\uc7a5\ud569\ub2c8\ub2e4. \ubc14\ub85c Jacobian\uc785\ub2c8\ub2e4.\\n\\nJacobian\uc740 \ud544\uc694\ud55c \uc88c\ud45c\uacc4\uc5d0\uc11c \ud45c\ud604\ud55c \uad00\uc808 screw axis\ub97c \uc5f4\ubca1\ud130\ub85c \uac16\ub294 \ud589\ub82c\uc785\ub2c8\ub2e4.\\n\\n$$\\nJ(\\\\theta) = \\\\begin{bmatrix}\\n\\\\mathcal{S}_1 & \\\\mathcal{S}_2 & \\\\cdots & \\\\mathcal{S}_n\\n\\\\end{bmatrix}.\\n$$\\n\\n\uadf8\ub7ec\uba74 \ub9d0\ub2e8 \uc7a5\uce58 twist\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.\\n\\n$$\\n\\\\nu = J(\\\\theta)\\\\dot{\\\\theta}.\\n$$\\n\\n\uc774\ub294 screw theory \uc704\uc5d0 \ubcc4\ub3c4\ub85c \ucd94\uac00\ub41c \uac1c\ub150\uc774 \uc544\ub2d9\ub2c8\ub2e4. \uac01 \uad00\uc808\uc758 \uc6b4\ub3d9 \uc0dd\uc131\uc790\ub97c \ud558\ub098\uc758 \uc120\ud615 \uc0ac\uc0c1\uc73c\ub85c \ubaa8\uc740 \uc9c1\uc811\uc801\uc778 \uacb0\uacfc\uc785\ub2c8\ub2e4.\\n\\nJacobian\uc740 \uad00\uc808 \uc18d\ub3c4\uac00 \uc791\uc5c5 \uacf5\uac04 \uc6b4\ub3d9\uc744 \uc5b4\ub5bb\uac8c \ub9cc\ub4e4\uc5b4 \ub0b4\ub294\uc9c0 \uc815\ud655\ud788 \uc54c\ub824 \uc8fc\ub294 \ub300\uc0c1\uc785\ub2c8\ub2e4.\\n\\n\uadf8\ub798\uc11c \ub85c\ubd07\uacf5\ud559\uc5d0\uc11c \uc911\uc2ec\uc801\uc778 \uc5ed\ud560\uc744 \ud569\ub2c8\ub2e4. \uae30\ud558\ud559\uc801 \uc6b4\ub3d9 \uc124\uba85\uc5d0\uc11c \ub85c\ubd07 \uc81c\uc5b4\ub85c \ub118\uc5b4\uac00\ub294 \uccab \ub2e8\uacc4\uc774\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.\\n\\n## 7. Jacobian\uc758 \uae30\ud558\ud559\uc801 \uc9c1\uad00\\n\\nJacobian\uc740 \uc218\uce58 \ud589\ub82c\ub85c \ub2e4\ub904\uc9c0\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc9c0\ub9cc, \uae30\ud558\ud559\uc801\uc73c\ub85c\ub294 \uadf8\ubcf4\ub2e4 \ud48d\ubd80\ud55c \uc758\ubbf8\ub97c \uac16\uc2b5\ub2c8\ub2e4.\\n\\n\uac01 \uc5f4\uc740 \ud55c \uad00\uc808\uc774 \uc21c\uac04\uc801\uc778 \uc791\uc5c5 \uacf5\uac04\uc5d0\uc11c \ub9d0\ub2e8 \uc7a5\uce58\ub97c \uc5b4\ub5bb\uac8c \uc6c0\uc9c1\uc774\ub294\uc9c0 \ub098\ud0c0\ub0c5\ub2c8\ub2e4. \uc5f4\ub4e4\uc774 \uc11c\ub85c \ub098\ub780\ud788 \ub193\uc774\uac70\ub098 \uac70\uc758 \uc885\uc18d\ub418\uba74, \ub9e4\ub2c8\ud4f0\ub808\uc774\ud130\ub294 \ubaa8\ub4e0 \ubc29\ud5a5\uc73c\ub85c \ub3c5\ub9bd\uc801\uc73c\ub85c \uc6c0\uc9c1\uc77c \uc218 \uc5c6\uc2b5\ub2c8\ub2e4. \uc774\uac83\uc774 singularity\uc758 \uae30\ud558\ud559\uc785\ub2c8\ub2e4.\\n\\n\uc774\uac83\uc774 \ub2e4\uc74c rank \uc870\uac74\uc758 \uc9c1\uad00\uc785\ub2c8\ub2e4.\\n\\n$$\\n\\\\operatorname{rank}(J) < n.\\n$$\\n\\nRank\uac00 \ubd80\uc871\ud558\uba74 \uc77c\ubd80 \uad00\uc808 \uc6b4\ub3d9\uc774 \ub3c5\ub9bd\uc801\uc778 \uc791\uc5c5 \uacf5\uac04 \uc6b4\ub3d9\uc744 \ub9cc\ub4e4\uc5b4 \ub0b4\uc9c0 \ubabb\ud569\ub2c8\ub2e4.\\n\\n\ub530\ub77c\uc11c Jacobian\uc740 \ub2e4\uc74c \uc138 \uc218\uc900\uc744 \ub3d9\uc2dc\uc5d0 \uc5f0\uacb0\ud569\ub2c8\ub2e4.\\n\\n- \uae30\ud558\ud559\uc801 \uc6b4\ub3d9 \ubc29\ud5a5,\\n- \uc21c\uac04\uc801\uc778 \uc791\uc5c5 \uacf5\uac04 \uc18d\ub3c4,\\n- \ub9e4\ub2c8\ud4f0\ub808\uc774\ud130\uc758 \uad6d\uc18c conditioning.\\n\\nScrew-theory \uad00\uc810\uc774 \uac15\ub825\ud55c \uc774\uc720 \uc911 \ud558\ub098\ub294 \ud589\ub82c\uc744 \ubb3c\ub9ac\uc801 \uc124\uba85\uc73c\ub85c \ubc14\uafb8\uc5b4 \uc8fc\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.\\n\\n## 8. \uac1c\ub150 \uc694\uc57d\\n\\n\uc774 \uc2dc\ub9ac\uc988\uc758 \uc804\uccb4 \ud750\ub984\uc740 \ub2e4\uc74c\uacfc \uac19\uc774 \uac04\uacb0\ud558\uac8c \uc815\ub9ac\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n1. \uac15\uccb4 \uc6b4\ub3d9\uc740 $T \\\\in SE(3)$\uc778 \ubcc0\ud658\uc73c\ub85c \ud45c\ud604\ud569\ub2c8\ub2e4.\\n2. \uc21c\uac04 \uc6b4\ub3d9\uc740 $\\\\xi \\\\in se(3)$\uc778 twist\ub85c \ud45c\ud604\ud569\ub2c8\ub2e4.\\n3. \uad00\uc808\uc740 screw axis $\\\\mathcal{S}$\ub97c \ub530\ub77c \uc6b4\ub3d9\uc744 \ub9cc\ub4ed\ub2c8\ub2e4.\\n4. \uc720\ud55c \uc6b4\ub3d9\uc740 exponential map $e^{\\\\hat{\\\\mathcal{S}}\\\\theta}$\uc5d0\uc11c \uc5bb\uc2b5\ub2c8\ub2e4.\\n5. Jacobian\uc740 \ubaa8\ub4e0 \uad00\uc808\uc758 \uae30\uc5ec\ub97c \ud558\ub098\uc758 \uc0ac\uc0c1 $\\\\nu = J\\\\dot{\\\\theta}$\ub85c \ubaa8\uc74d\ub2c8\ub2e4.\\n6. \uc774 \uc120\ud615\ud654\ub41c \uc0ac\uc0c1\uc740 control, optimization, planning\uc758 \uae30\ubc18\uc774 \ub429\ub2c8\ub2e4.\\n\\n\uc774\uac83\uc774 Modern Robotics\uc758 \uac1c\ub150\uc801 \ubf08\ub300\uc785\ub2c8\ub2e4.\\n\\n## 9. \uc774\ub860\uc744 \ub118\uc5b4 \uc911\uc694\ud55c \uc774\uc720\\n\\n\uc774\ub7ec\ud55c \uac1c\ub150\uc744 \ub2e8\uc9c0 \uc218\ud559\uc801 \uc6b0\uc544\ud568\uc73c\ub85c\ub9cc \uc0dd\uac01\ud558\uae30 \uc27d\uc2b5\ub2c8\ub2e4. \uadf8\ub7ec\ub098 \uc2e4\uc81c\ub85c trajectory tracking\ubd80\ud130 inverse kinematics, force control\uae4c\uc9c0 \ubaa8\ub4e0 \uac83\uc774 \uc774 \uad6c\uc870\uc5d0 \uc758\uc874\ud569\ub2c8\ub2e4.\\n\\n\uc774\uc720\ub294 \uac04\ub2e8\ud569\ub2c8\ub2e4.\\n\\n- \ub85c\ubd07\uc758 \uc6b4\ub3d9\uc740 \uac15\uccb4 \uc6b4\ub3d9\uc785\ub2c8\ub2e4.\\n- \uc21c\uac04 \uc6b4\ub3d9\uc740 twist\uc785\ub2c8\ub2e4.\\n- \uc720\ud55c \uc6b4\ub3d9\uc740 exponential\uc785\ub2c8\ub2e4.\\n- \uc791\uc5c5 \uacf5\uac04 \uc18d\ub3c4\ub294 \uad00\uc808 \uc18d\ub3c4\uc758 Jacobian \uac00\uc911 \ud569\uc785\ub2c8\ub2e4.\\n\\n\uc774\ub294 \uc120\ud0dd\uc801\uc778 \uad00\uc810\uc774 \uc544\ub2d9\ub2c8\ub2e4. \ud604\ub300 \ub85c\ubd07 \uae30\uad6c\ud559\uc774 \uc791\uc131\ub418\ub294 \uc5b8\uc5b4\uc785\ub2c8\ub2e4.\\n\\n## 10. \ud575\uc2ec \uc815\ub9ac\\n\\n\uc774\ubc88 \uae00\uc5d0\uc11c \uac00\uc7a5 \uc911\uc694\ud55c \uad50\ud6c8\uc740 screw-axis \uc815\uc2dd\ud654\uac00 \uace0\ub9bd\ub41c \ud55c \uc7a5\uc774 \uc544\ub2c8\ub77c\ub294 \uc810\uc785\ub2c8\ub2e4. \uc774\uac83\uc740 \uc804\uccb4 \ub85c\ubd07 \uae30\uad6c\ud559 \ubaa8\ub378\uc758 \ud1a0\ub300\uc785\ub2c8\ub2e4.\\n\\nTwist\ub294 \uc21c\uac04 \uc6b4\ub3d9\uc744 \uc124\uba85\ud558\uace0, screw axis\ub294 \uad00\uc808 \uc6b4\ub3d9\uc758 \uae30\ud558\ub97c \uc124\uba85\ud558\uba70, exponential map\uc740 \uc774\ub7ec\ud55c \ubbf8\uc18c \uc6b4\ub3d9\uc744 \uc720\ud55c \ubcc0\ud658\uacfc \uc5f0\uacb0\ud569\ub2c8\ub2e4.\\n\\n\uc774\ub97c \uc774\ud574\ud558\uba74 Jacobian\uc740 \ub354 \uc774\uc0c1 \uc2e0\ube44\ub86d\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \ubaa8\ub4e0 \uad00\uc808\uc758 \uc6b4\ub3d9 \uc0dd\uc131\uc790\ub97c \ud558\ub098\uc758 \uc18d\ub3c4 \uc0ac\uc0c1\uc73c\ub85c \ubaa8\uc740 \ud589\ub82c\uc77c \ubfd0\uc785\ub2c8\ub2e4.\\n\\n\uc774\uac83\uc774 \uae30\ud558\ud559\uc5d0\uc11c \uc81c\uc5b4\ub85c \uc774\uc5b4\uc9c0\ub294 \uc5f0\uacb0\uc785\ub2c8\ub2e4."},{"id":"modern-robotics-part-3","metadata":{"permalink":"/ko/blog/modern-robotics-part-3","editUrl":"https://github.com/CMaybe/cmaybe.github.io/tree/main/blog/2026-09-07-modern-robotics-part-3.md","source":"@site/i18n/ko/docusaurus-plugin-content-blog/2026-09-07-modern-robotics-part-3.md","title":"Modern Robotics, Part 3 \u2014 Jacobian\uacfc \ub9d0\ub2e8 \uc7a5\uce58 \uc18d\ub3c4","description":"Screw axis\uc640 twist\uc5d0\uc11c Jacobian\uc744 \uc720\ub3c4\ud558\uace0, \uad00\uc808 \uc18d\ub3c4\ub85c \ub9d0\ub2e8 \uc7a5\uce58 \uc18d\ub3c4\ub97c \uacc4\uc0b0\ud558\ub294 \ubc29\ubc95\uacfc singularity\uac00 \ubc1c\uc0dd\ud558\ub294 \uc774\uc720\ub97c \uc790\uc138\ud788 \uc124\uba85\ud569\ub2c8\ub2e4.","date":"2026-09-07T00:00:00.000Z","tags":[{"inline":false,"label":"Robotics","permalink":"/ko/blog/tags/robotics","description":"Robot software, systems, and experiments."},{"inline":false,"label":"Modern Robotics","permalink":"/ko/blog/tags/modern-robotics","description":"Concepts, methods, and intuition behind rigid-body motion and robot kinematics."},{"inline":false,"label":"Kinematics","permalink":"/ko/blog/tags/kinematics","description":"Forward and inverse kinematics for robots."},{"inline":false,"label":"Screw Theory","permalink":"/ko/blog/tags/screw-theory","description":"Twists, screw axes, and the geometry of rigid-body motion."}],"readingTime":6.2,"hasTruncateMarker":true,"authors":[{"name":"Jaegyeom Kim","title":"Robotics Software Engineer","url":"https://github.com/CMaybe","page":{"permalink":"/ko/blog/authors/endi"},"socials":{"github":"https://github.com/CMaybe","linkedin":"https://www.linkedin.com/in/Jaegyeom-kim-185b8a2a4/"},"imageURL":"https://github.com/CMaybe.png","key":"endi"}],"frontMatter":{"slug":"modern-robotics-part-3","title":"Modern Robotics, Part 3 \u2014 Jacobian\uacfc \ub9d0\ub2e8 \uc7a5\uce58 \uc18d\ub3c4","authors":["endi"],"tags":["robotics","modern-robotics","kinematics","screw-theory"],"description":"Screw axis\uc640 twist\uc5d0\uc11c Jacobian\uc744 \uc720\ub3c4\ud558\uace0, \uad00\uc808 \uc18d\ub3c4\ub85c \ub9d0\ub2e8 \uc7a5\uce58 \uc18d\ub3c4\ub97c \uacc4\uc0b0\ud558\ub294 \ubc29\ubc95\uacfc singularity\uac00 \ubc1c\uc0dd\ud558\ub294 \uc774\uc720\ub97c \uc790\uc138\ud788 \uc124\uba85\ud569\ub2c8\ub2e4."},"unlisted":false,"prevItem":{"title":"Modern Robotics, Part 2B \u2014 \uc88c\ud45c\uacc4, Lie group, \uadf8\ub9ac\uace0 Jacobian\uc758 \uc5f0\uacb0","permalink":"/ko/blog/modern-robotics-part-2b"},"nextItem":{"title":"Modern Robotics, Part 4 \u2014 Manipulability\uc640 \uc18d\ub3c4 \uc81c\uc5b4","permalink":"/ko/blog/modern-robotics-part-4"}},"content":"\uc55e\uc120 \uae00\uc5d0\uc11c\ub294 twist\uc640 screw axis\ub97c \uc0ac\uc6a9\ud574 \uac15\uccb4 \uc6b4\ub3d9\uc744 \uae30\ud558\ud559\uc801\uc73c\ub85c \ubc14\ub77c\ubcf4\ub294 \uad00\uc810\uc744 \ubc1c\uc804\uc2dc\ucf30\uc2b5\ub2c8\ub2e4. \uad00\uc808\uc740 \ub2e8\uc21c\ud788 \\"\uac01\ub3c4\ub97c \uc6c0\uc9c1\uc774\ub294\\" \uac83\uc774 \uc544\ub2c8\ub77c screw axis\ub97c \ud1b5\ud574 \uac15\uccb4 \uc6b4\ub3d9\uc744 \ub9cc\ub4e4\uba70, \uc720\ud55c\ud55c \ub85c\ubd07 pose\ub294 \uadf8 \uc6b4\ub3d9 \uc0dd\uc131\uc790\ub97c \uc9c0\uc218\ud654\ud574 \uc5bb\ub294\ub2e4\ub294 \uc810\uc744 \uc0b4\ud3b4\ubd24\uc2b5\ub2c8\ub2e4.\\n\\n\uc774\uc81c \uc2e4\uc6a9\uc801\uc778 \uc9c8\ubb38\uc774 \ubc14\ub85c \uc774\uc5b4\uc9d1\ub2c8\ub2e4.\\n\\n> \uad00\uc808 \ubcc0\uc218\uac00 $\\\\dot{\\\\theta}$\uc758 \uc18d\ub3c4\ub85c \uc6c0\uc9c1\uc77c \ub54c \ub9d0\ub2e8 \uc7a5\uce58\uc758 \uc18d\ub3c4\ub294 \uc5bc\ub9c8\uc778\uac00?\\n\\n\ub2f5\uc740 Jacobian\uc785\ub2c8\ub2e4.\\n\\nJacobian\uc740 \uad00\uc808 \uc18d\ub3c4\ub97c spatial \ub610\ub294 body \ub9d0\ub2e8 \uc7a5\uce58 \uc6b4\ub3d9\uc73c\ub85c \ubc14\uafb8\ub294 \uc120\ud615 \uc0ac\uc0c1\uc785\ub2c8\ub2e4. Configuration space\uc640 task space\ub97c \uc5f0\uacb0\ud558\uae30 \ub54c\ubb38\uc5d0 \ub85c\ubd07\uacf5\ud559\uc5d0\uc11c \uac00\uc7a5 \uc911\uc694\ud55c \ub300\uc0c1 \uc911 \ud558\ub098\uc785\ub2c8\ub2e4.\\n\\n\x3c!-- truncate --\x3e\\n\\n## 1. \uad00\uc808 \uc6b4\ub3d9\uc5d0\uc11c \ub9d0\ub2e8 \uc7a5\uce58 twist\ub85c\\n\\n\ub85c\ubd07 configuration\uc744 \uad00\uc808 \ubcc0\uc218\ub85c \ub098\ud0c0\ub0b4\uba74\\n\\n$$\\n\\\\theta = \\\\begin{bmatrix}\\n\\\\theta_1 \\\\\\\\\\\\ \\\\theta_2 \\\\\\\\\\\\ \\\\vdots \\\\\\\\\\\\ \\\\theta_n\\n\\\\end{bmatrix}.\\n$$\\n\\n\ub9d0\ub2e8 \uc7a5\uce58 pose\ub294 \uac15\uccb4 \ubcc0\ud658\uc785\ub2c8\ub2e4.\\n\\n$$\\nT_{se}(\\\\theta) \\\\in SE(3).\\n$$\\n\\n\uad00\uc808\uc774 \ub2e4\uc74c\uacfc \uac19\uc774 \uc6c0\uc9c1\uc778\ub2e4\uace0 \ud569\uc2dc\ub2e4.\\n\\n$$\\n\\\\dot{\\\\theta} = \\\\begin{bmatrix}\\n\\\\dot{\\\\theta}_1 \\\\\\\\\\\\ \\\\dot{\\\\theta}_2 \\\\\\\\\\\\ \\\\vdots \\\\\\\\\\\\ \\\\dot{\\\\theta}_n\\n\\\\end{bmatrix},\\n$$\\n\\n\ub9d0\ub2e8 \uc7a5\uce58\uc758 \uc21c\uac04 twist\ub294 \ubb34\uc5c7\uc77c\uae4c\uc694?\\n\\n\ub2f5\uc740 \ub2e4\uc74c Jacobian \uad00\uacc4\uc785\ub2c8\ub2e4.\\n\\n$$\\n\\\\nu = J(\\\\theta)\\\\,\\\\dot{\\\\theta},\\n$$\\n\\n\uc5ec\uae30\uc11c $\\\\nu$\ub294 \ub9d0\ub2e8 \uc7a5\uce58 twist\uc774\uace0 $J(\\\\theta)$\ub294 Jacobian \ud589\ub82c\uc785\ub2c8\ub2e4.\\n\\n\uc774 \uc2dd\uc740 \ub85c\ubd07 \uc6b4\ub3d9\uc758 \ubbf8\uc18c \ud45c\ud604\uc785\ub2c8\ub2e4. \ub9d0\ub2e8 \uc7a5\uce58 \uc18d\ub3c4\uac00 \uad00\uc808 \uc18d\ub3c4\uc758 \uc120\ud615 \uacb0\ud569\uc774\uba70, \uadf8 \uacc4\uc218\ub294 \uae30\uad6c\uc758 \uae30\ud558\uc5d0 \uc758\ud574 \uacb0\uc815\ub41c\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4.\\n\\n\uc774\ub294 \uc5ed\ud559 \uc804\ubc18\uc5d0\uc11c \ubcf4\uc774\ub294 \ud328\ud134\uacfc \uac19\uc2b5\ub2c8\ub2e4.\\n\\n- \uc791\uc740 \ubcc0\uc704\ub294 \uc120\ud615\ud654\ud569\ub2c8\ub2e4.\\n- Configuration \uc758\uc874\uc131\uc740 \uc120\ud615 \uc0ac\uc0c1\uc744 \ub9cc\ub4ed\ub2c8\ub2e4.\\n- \uadf8 \uc0ac\uc0c1\uc774 Jacobian\uc785\ub2c8\ub2e4.\\n\\n## 2. Screw-axis Jacobian\\n\\nJacobian\uc744 \uc720\ub3c4\ud558\ub294 \uac00\uc7a5 \uc774\ud574\ud558\uae30 \uc26c\uc6b4 \ubc29\ubc95\uc740 screw-axis \uad00\uc810\uc5d0\uc11c \ucd9c\ubc1c\ud558\ub294 \uac83\uc785\ub2c8\ub2e4.\\n\\n\uac01 \uad00\uc808 $i$\uc5d0\ub294 \uc801\uc808\ud55c \uc88c\ud45c\uacc4\uc5d0\uc11c screw axis $\\\\mathcal{S}_i$\ub97c \ub300\uc751\uc2dc\ud0ac \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uadf8\ub7ec\uba74 \uad00\uc808 $i$\uac00 \ub9d0\ub2e8 \uc7a5\uce58 twist\uc5d0 \uae30\uc5ec\ud558\ub294 \uc21c\uac04 \uc131\ubd84\uc740\\n\\n$$\\n\\\\nu_i = \\\\mathcal{S}_i \\\\dot{\\\\theta}_i.\\n$$\\n\\n\uc804\uccb4 \ub9d0\ub2e8 \uc7a5\uce58 twist\ub294 \ubaa8\ub4e0 \uad00\uc808 \uae30\uc5ec\uc758 \ud569\uc785\ub2c8\ub2e4.\\n\\n$$\\n\\\\nu = \\\\sum_{i=1}^n \\\\mathcal{S}_i \\\\dot{\\\\theta}_i.\\n$$\\n\\n\uc774\ub97c \ud589\ub82c\ub85c \ubaa8\uc73c\uba74\\n\\n$$\\n\\\\nu = \\\\begin{bmatrix}\\n\\\\mathcal{S}_1 & \\\\mathcal{S}_2 & \\\\cdots & \\\\mathcal{S}_n\\n\\\\end{bmatrix}\\n\\\\begin{bmatrix}\\n\\\\dot{\\\\theta}_1 \\\\\\\\\\\\ \\\\dot{\\\\theta}_2 \\\\\\\\\\\\ \\\\vdots \\\\\\\\\\\\ \\\\dot{\\\\theta}_n\\n\\\\end{bmatrix}.\\n$$\\n\\n\uc774 \ud589\ub82c\uc774 Jacobian\uc785\ub2c8\ub2e4.\\n\\n$$\\nJ(\\\\theta) = \\\\begin{bmatrix}\\n\\\\mathcal{S}_1 & \\\\mathcal{S}_2 & \\\\cdots & \\\\mathcal{S}_n\\n\\\\end{bmatrix}.\\n$$\\n\\n\uc5f4\ubca1\ud130\ub294 \uad00\uc808 \uc6b4\ub3d9 \uc0dd\uc131\uc790\uc785\ub2c8\ub2e4. \ub530\ub77c\uc11c Jacobian\uc740 \ucd94\uc0c1\uc801\uc778 \uac83\uc774 \uc544\ub2c8\ub77c screw axis\ub97c \ud589\ub82c\ub85c \ubc30\uc5f4\ud55c \uac83\uc785\ub2c8\ub2e4.\\n\\n\uc774\uac83\uc774 Modern Robotics\uc758 \ud575\uc2ec \ud1b5\ucc30 \uc911 \ud558\ub098\uc785\ub2c8\ub2e4. Jacobian\uc740 \uc784\uc758\ub85c \ub9cc\ub4e0 \ub300\uc218\uac00 \uc544\ub2c8\ub77c \uae30\ud558\ud559\uc801 \ub300\uc0c1\uc785\ub2c8\ub2e4.\\n\\n## 3. Spatial Jacobian\uacfc body Jacobian\\n\\n\uc5ec\uae30\uc11c twist\ub97c \uc5b4\ub290 \uc88c\ud45c\uacc4\uc5d0\uc11c \ud45c\ud604\ud558\ub294\uc9c0\uac00 \uc911\uc694\ud569\ub2c8\ub2e4.\\n\\n### 3.1 Spatial Jacobian\\n\\n\ub9d0\ub2e8 \uc7a5\uce58 twist\ub97c space frame\uc5d0\uc11c \ud45c\ud604\ud558\uba74 Jacobian\uc744 spatial Jacobian $J_s$\ub77c\uace0 \ud569\ub2c8\ub2e4.\\n\\n$$\\n\\\\nu_s = J_s(\\\\theta)\\\\,\\\\dot{\\\\theta}.\\n$$\\n\\n$J_s$\uc758 \uc5f4\uc740 space frame\uc5d0\uc11c \ud45c\ud604\ud55c screw axis\uc785\ub2c8\ub2e4.\\n\\n### 3.2 Body Jacobian\\n\\n\ub9d0\ub2e8 \uc7a5\uce58 twist\ub97c body frame\uc5d0\uc11c \ud45c\ud604\ud558\uba74 body Jacobian $J_b$\uac00 \ub429\ub2c8\ub2e4.\\n\\n$$\\n\\\\nu_b = J_b(\\\\theta)\\\\,\\\\dot{\\\\theta}.\\n$$\\n\\n\ub458\uc758 \uad00\uacc4\ub294 adjoint transformation\uc73c\ub85c \uc8fc\uc5b4\uc9d1\ub2c8\ub2e4.\\n\\n$$\\n\\\\nu_s = Ad_{T_{sb}}\\\\,\\\\nu_b,\\n$$\\n\\n\ub530\ub77c\uc11c\\n\\n$$\\nJ_s = Ad_{T_{sb}} J_b.\\n$$\\n\\n\uc774 \uad00\uacc4\ub294 \ub2e8\uc21c\ud55c \ud45c\uae30\uc0c1\uc758 \ucc28\uc774\uac00 \uc544\ub2d9\ub2c8\ub2e4. \uac19\uc740 \ubb3c\ub9ac\uc801 \uc6b4\ub3d9\uc774 \uc11c\ub85c \ub2e4\ub978 \uc88c\ud45c\uacc4\ub85c \ud45c\ud604\ub420 \uc218 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ubc18\uc601\ud569\ub2c8\ub2e4. Jacobian\uc758 \ud615\uc2dd\uc740 \uc120\ud0dd\ud55c \uc88c\ud45c\uacc4\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c0\uc9c0\ub9cc underlying motion\uc740 \ubd88\ubcc0\uc785\ub2c8\ub2e4.\\n\\n## 4. Jacobian\uc774 configuration\uc5d0 \uc758\uc874\ud558\ub294 \uc774\uc720\\n\\nJacobian\uc774 configuration\uc5d0 \uc758\uc874\ud558\ub294 \uc774\uc720\ub294 screw axis \uc790\uccb4\uac00 \ub85c\ubd07\uacfc \ud568\uaed8 \uc6c0\uc9c1\uc774\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.\\n\\n\uace0\uc815\ub41c world frame\uc5d0\uc11c \ubcf8 \ud68c\uc804 \uad00\uc808\uc758 \ucd95\uc740 \ub85c\ubd07\uc758 \ud604\uc7ac pose\uc5d0 \uc758\uc874\ud569\ub2c8\ub2e4. \ub530\ub77c\uc11c \uae30\uad6c\uc758 \uad6c\uc870\uac00 \uac19\ub354\ub77c\ub3c4 \ub9e4\ub2c8\ud4f0\ub808\uc774\ud130\uac00 \uc6c0\uc9c1\uc774\uba74 Jacobian\uc758 \uc5f4\ub3c4 \ubc14\ub01d\ub2c8\ub2e4.\\n\\n\uc774 \ub54c\ubb38\uc5d0 \uac00\uc7a5 \ub2e8\uc21c\ud55c \uacbd\uc6b0\ub97c \uc81c\uc678\ud558\uba74 Jacobian\uc740 \uc0c1\uc218\uac00 \uc544\ub2d9\ub2c8\ub2e4.\\n\\nSerial manipulator\uc5d0\uc11c\ub294\\n\\n$$\\nJ(\\\\theta) = \\\\begin{bmatrix}\\n\\\\mathcal{S}_1(\\\\theta) & \\\\mathcal{S}_2(\\\\theta) & \\\\cdots & \\\\mathcal{S}_n(\\\\theta)\\n\\\\end{bmatrix},\\n$$\\n\\n\uc774\uba70 \uac01 $\\\\mathcal{S}_i(\\\\theta)$\ub294 \ud604\uc7ac \uad00\uc808 $i$\uc758 screw axis\ub97c \uc801\uc808\ud55c \uc88c\ud45c\uacc4\uc5d0\uc11c \ud45c\ud604\ud55c \uac83\uc785\ub2c8\ub2e4.\\n\\n\uc790\uc138\uc5d0 \ub530\ub978 \uc774 \uc758\uc874\uc131\uc774 \ub85c\ubd07 \uae30\uad6c\ud559\uc744 \ud48d\ubd80\ud558\uba74\uc11c\ub3c4 \uc5b4\ub835\uac8c \ub9cc\ub4ed\ub2c8\ub2e4.\\n\\n## 5. \ubbf8\ubd84 \uc0ac\uc0c1\uc73c\ub85c\uc11c\uc758 Jacobian\\n\\nJacobian\uc740 forward kinematics map\uc758 \ubbf8\ubd84\uc785\ub2c8\ub2e4.\\n\\n$$\\nT_{se}: \\\\mathbb{R}^n \\\\to SE(3).\\n$$\\n\\nConfiguration $\\\\theta$ \uadfc\ucc98\uc5d0\uc11c \uae30\uad6c\ud559\uc744 \uc120\ud615\ud654\ud558\uba74 \uad00\uc808 \ubcc0\uc218\uc758 \uc791\uc740 \ubcc0\ud654\uac00 \uc791\uc5c5 \uacf5\uac04\uc758 \uc791\uc740 \uc6b4\ub3d9\uc744 \ub9cc\ub4ed\ub2c8\ub2e4.\\n\\n$$\\n\\\\delta T \\\\approx \\\\hat{\\\\nu} T,\\n$$\\n\\n\uadf8\ub9ac\uace0\\n\\n$$\\n\\\\nu \\\\approx J(\\\\theta)\\\\delta\\\\theta.\\n$$\\n\\n\uc774\ub294 \ub2e4\uc74c\uacfc \uac19\uc740 \uc911\uc694\ud55c \ud574\uc11d\uc744 \uc81c\uacf5\ud569\ub2c8\ub2e4.\\n\\n- Forward kinematics\ub294 \uad00\uc808 \uc88c\ud45c\ub97c pose\ub85c \ubcf4\ub0c5\ub2c8\ub2e4.\\n- Jacobian\uc740 \ubbf8\uc18c \uad00\uc808 \ubcc0\ud654\ub97c \ubbf8\uc18c \ub3c4\uad6c \uc6b4\ub3d9\uc73c\ub85c \ubcf4\ub0c5\ub2c8\ub2e4.\\n\\n\ub530\ub77c\uc11c Jacobian\uc740 \ube44\uc120\ud615 \ub85c\ubd07 \uae30\ud558\uc758 \uad6d\uc18c \uc120\ud615 \uadfc\uc0ac\uc785\ub2c8\ub2e4.\\n\\n## 6. Singularity\uc640 \uc774\ub3d9\uc131\uc758 \uc0c1\uc2e4\\n\\nJacobian\uc774 \uc911\uc694\ud55c \ud070 \uc774\uc720\ub294 singularity\ub97c \ub4dc\ub7ec\ub0b4\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.\\n\\nJacobian\uc758 rank\uac00 \ub0ae\uc544\uc9c0\uba74 \ub9d0\ub2e8 \uc7a5\uce58 twist\ub294 0\uc774\uc9c0\ub9cc \uad00\uc808 \uc18d\ub3c4\ub294 0\uc774 \uc544\ub2cc \uacbd\uc6b0\uac00 \uc874\uc7ac\ud569\ub2c8\ub2e4.\\n\\n$$\\nJ(\\\\theta)\\\\dot{\\\\theta} = 0, \\\\quad \\\\dot{\\\\theta} \\\\neq 0.\\n$$\\n\\n\uc774\ub294 \ub85c\ubd07\uc774 task space\uc758 \uc6b4\ub3d9\uc744 \ub9cc\ub4e4\uc9c0 \uc54a\uace0 configuration space\uc5d0\uc11c \uc6c0\uc9c1\uc77c \uc218 \uc788\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4.\\n\\n\uc815\uc0ac\uac01 Jacobian\uc758 \uacbd\uc6b0 \uc870\uac74\uc740\\n\\n$$\\n\\\\det J(\\\\theta) = 0\\n$$\\n\\n\uc785\ub2c8\ub2e4.\\n\\n\ub300\ud45c\uc801\uc778 singularity\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.\\n\\n- \uad00\uc808 \ucd95\uc774 \uc11c\ub85c \uc815\ub82c\ub418\ub294 \uacbd\uc6b0,\\n- \ub9d0\ub2e8 \uc7a5\uce58\uac00 \uc644\uc804\ud788 \ubed7\uc740 \uc790\uc138\uc5d0 \ub3c4\ub2ec\ud558\ub294 \uacbd\uc6b0,\\n- \uc190\ubaa9 \ub610\ub294 \ud314\uafc8\uce58 configuration\uc774 \ud1f4\ud654\ud55c \uc0ac\uc0c1\uc744 \ub9cc\ub4dc\ub294 \uacbd\uc6b0\uc785\ub2c8\ub2e4.\\n\\nSingularity\uc5d0\uc11c\ub294 \ub85c\ubd07\uc774 \uc5b4\ub5a4 \ubc29\ud5a5\uc73c\ub85c \uad6d\uc18c \uc81c\uc5b4\ub825\uc744 \uc783\uae30 \ub54c\ubb38\uc5d0 inverse kinematics\uc640 motion planning \ubb38\uc81c\uac00 ill-conditioned\ud574\uc9d1\ub2c8\ub2e4.\\n\\n\uadf8\ub798\uc11c Jacobian\uc740 \ub2e8\uc21c\ud55c \ud3b8\uc758 \ub3c4\uad6c\uac00 \uc544\ub2c8\ub77c \uae30\uacc4\uc801 \uac00\ub2a5\uc131\uc744 \uc9c4\ub2e8\ud558\ub294 \ub3c4\uad6c\uc774\uae30\ub3c4 \ud569\ub2c8\ub2e4.\\n\\n## 7. \uc608: \ud3c9\uba74 2R \ub9e4\ub2c8\ud4f0\ub808\uc774\ud130\\n\\n\ub9c1\ud06c \uae38\uc774\uac00 $L_1$, $L_2$\uc778 \ud3c9\uba74 2R \ub85c\ubd07\uc744 \uc0dd\uac01\ud574 \ubd05\uc2dc\ub2e4. \uad00\uc808 \ubcc0\uc218\ub294 $\\\\theta_1$, $\\\\theta_2$\uc785\ub2c8\ub2e4.\\n\\n\ub9d0\ub2e8 \uc7a5\uce58 \uc704\uce58\ub294\\n\\n$$\\nx = L_1\\\\cos\\\\theta_1 + L_2\\\\cos(\\\\theta_1 + \\\\theta_2),\\n$$\\n\\n$$\\ny = L_1\\\\sin\\\\theta_1 + L_2\\\\sin(\\\\theta_1 + \\\\theta_2).\\n$$\\n\\n\uc2dc\uac04\uc5d0 \ub300\ud574 \ubbf8\ubd84\ud558\uba74\\n\\n$$\\n\\\\dot{x} = -L_1\\\\sin\\\\theta_1\\\\dot{\\\\theta}_1 - L_2\\\\sin(\\\\theta_1 + \\\\theta_2)(\\\\dot{\\\\theta}_1 + \\\\dot{\\\\theta}_2),\\n$$\\n\\n$$\\n\\\\dot{y} = L_1\\\\cos\\\\theta_1\\\\dot{\\\\theta}_1 + L_2\\\\cos(\\\\theta_1 + \\\\theta_2)(\\\\dot{\\\\theta}_1 + \\\\dot{\\\\theta}_2).\\n$$\\n\\n\ub2e4\uc74c\uacfc \uac19\uc774 \uc4f8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n$$\\n\\\\begin{bmatrix}\\n\\\\dot{x} \\\\\\\\\\\\ \\\\dot{y}\\n\\\\end{bmatrix}\\n=\\n\\\\begin{bmatrix}\\n- L_1\\\\sin\\\\theta_1 - L_2\\\\sin(\\\\theta_1+\\\\theta_2) & -L_2\\\\sin(\\\\theta_1+\\\\theta_2) \\\\\\\\\\\\nL_1\\\\cos\\\\theta_1 + L_2\\\\cos(\\\\theta_1+\\\\theta_2) & L_2\\\\cos(\\\\theta_1+\\\\theta_2)\\n\\\\end{bmatrix}\\n\\\\begin{bmatrix}\\n\\\\dot{\\\\theta}_1 \\\\\\\\\\\\ \\\\dot{\\\\theta}_2\\n\\\\end{bmatrix}.\\n$$\\n\\n\uc774 \ud589\ub82c\uc774 \ud3c9\uba74 Jacobian\uc785\ub2c8\ub2e4. \ud589\ub82c\uc2dd\uc740\\n\\n$$\\n\\\\det J = L_1L_2\\\\sin\\\\theta_2.\\n$$\\n\\n\ub530\ub77c\uc11c \ub2e4\uc74c\uc77c \ub54c rank\ub97c \uc783\uc2b5\ub2c8\ub2e4.\\n\\n$$\\n\\\\sin\\\\theta_2 = 0,\\n$$\\n\\n\uc989,\\n\\n$$\\n\\\\theta_2 = 0 \\\\quad \\\\text{\ub610\ub294} \\\\quad \\\\theta_2 = \\\\pi.\\n$$\\n\\n\uc774 configuration\uc5d0\uc11c\ub294 \ud314\uafc8\uce58\uac00 \uc644\uc804\ud788 \uc811\ud788\uac70\ub098 \uc644\uc804\ud788 \ud3b4\uc838 \ub9d0\ub2e8 \uc7a5\uce58\uac00 \ubaa8\ub4e0 \ubc29\ud5a5\uc73c\ub85c \ub3c5\ub9bd\uc801\uc73c\ub85c \uc6c0\uc9c1\uc77c \uc218 \uc5c6\uc2b5\ub2c8\ub2e4.\\n\\n\uc774 \uc608\ub294 singularity\uc758 \uc9c1\uad00\uc744 \uc81c\uacf5\ud569\ub2c8\ub2e4. singularity\ub294 \uc2e0\ube44\ud55c \ud604\uc0c1\uc774 \uc544\ub2c8\ub77c \uad00\uc808 \uc6b4\ub3d9\uc5d0\uc11c task-space \uc6b4\ub3d9\uc73c\ub85c \uac00\ub294 \uae30\ud558\ud559\uc801 \uc0ac\uc0c1\uc774 \ud1f4\ud654\ud560 \ub54c \uc815\ud655\ud788 \ubc1c\uc0dd\ud569\ub2c8\ub2e4.\\n\\n## 8. Jacobian \uc5f4\uc758 \uae30\ud558\ud559\uc801 \uc758\ubbf8\\n\\nJacobian\uc758 \uac01 \uc5f4\uc740 \ud55c \uad00\uc808\uc774 \ub9cc\ub4dc\ub294 \uc21c\uac04 \uc6b4\ub3d9\uc5d0 \ub300\uc751\ud569\ub2c8\ub2e4.\\n\\n\ud68c\uc804 \uad00\uc808\uc5d0\uc11c\ub294\\n\\n$$\\n\\\\mathcal{S}_i =\\n\\\\begin{bmatrix}\\n\\\\omega_i \\\\\\\\\\\\n-\\\\omega_i \\\\times q_i\\n\\\\end{bmatrix},\\n$$\\n\\n\uc774\uba70 $q_i$\ub294 \uad00\uc808 \ucd95 \uc704\uc758 \uc810\uc785\ub2c8\ub2e4.\\n\\n\uc9c1\ub3d9 \uad00\uc808\uc5d0\uc11c\ub294\\n\\n$$\\n\\\\mathcal{S}_i =\\n\\\\begin{bmatrix}\\n0 \\\\\\\\\\\\n v_i\\n\\\\end{bmatrix},\\n$$\\n\\n\uc774\uace0 $v_i$\ub294 \ubcd1\uc9c4 \ubc29\ud5a5\uc785\ub2c8\ub2e4.\\n\\n\ub530\ub77c\uc11c Jacobian\uc740 \ub9d0\ub2e8 \uc7a5\uce58\uac00 \uc774\uc6a9\ud560 \uc218 \uc788\ub294 \ubaa8\ub4e0 \uc21c\uac04 \uc6b4\ub3d9 \ubc29\ud5a5\uc744 \uae30\ud558\ud559\uc801\uc73c\ub85c \uc694\uc57d\ud569\ub2c8\ub2e4.\\n\\nScrew theory\uc640 Jacobian\uc774 \uc790\uc5f0\uc2a4\ub7fd\uac8c \uc5f0\uacb0\ub418\ub294 \uc774\uc720\ub3c4 \uc5ec\uae30\uc5d0 \uc788\uc2b5\ub2c8\ub2e4. Jacobian\uc740 \ub85c\ubd07\uc758 \uae30\ud558\uac00 \uc815\uc758\ud55c \uc6b4\ub3d9 \uc0dd\uc131\uc790\ub97c \ubaa8\uc740 \ud615\ud0dc\uc785\ub2c8\ub2e4.\\n\\n## 9. Jacobian\uc774 \ub85c\ubd07\uacf5\ud559\uc758 \uc911\uc2ec\uc778 \uc774\uc720\\n\\nJacobian\uc740 \uae30\ud558\ud559\uacfc \uc81c\uc5b4\ub97c \uc5f0\uacb0\ud558\ub294 \ud575\uc2ec \ub300\uc0c1\uc785\ub2c8\ub2e4.\\n\\n\ub2e4\uc74c\uacfc \uac19\uc740 \uacf3\uc5d0 \ub4f1\uc7a5\ud569\ub2c8\ub2e4.\\n\\n- velocity control\\n- inverse kinematics\\n- motion planning\\n- manipulability analysis\\n- trajectory optimization\\n- dynamic modeling\\n\\n\uc608\ub97c \ub4e4\uc5b4 \ub9d0\ub2e8 \uc7a5\uce58\uac00 \uc6d0\ud558\ub294 twist $\\\\nu_d$\ub97c \ub530\ub974\ub3c4\ub85d \ud558\ub824\uba74\\n\\n$$\\nJ(\\\\theta)\\\\dot{\\\\theta} = \\\\nu_d\\n$$\\n\\n\ub97c \ud489\ub2c8\ub2e4.\\n\\n$J$\uac00 \uc815\uc0ac\uac01\uc774\uace0 \uac00\uc5ed\uc774\uba74\\n\\n$$\\n\\\\dot{\\\\theta} = J(\\\\theta)^{-1}\\\\nu_d.\\n$$\\n\\n\uc774\uac83\uc774 velocity control\uc758 \uac00\uc7a5 \ub2e8\uc21c\ud55c \ud615\ud0dc\uc785\ub2c8\ub2e4. \ud589\ub82c\uc774 \uc815\uc0ac\uac01\uc774 \uc544\ub2c8\uac70\ub098 \uac00\uc5ed\uc774 \uc544\ub2c8\uba74 pseudoinverse \ub610\ub294 constrained optimization \ubc29\ubc95\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.\\n\\n\uc774 \uc2e4\uc6a9\uc801\uc778 \uc81c\uc5b4 \uc815\uc2dd\ud654\ub294 \uc55e\uc120 \uae00\uc758 \uae30\ud558\ud559\uc801 \uc815\uc2dd\ud654\uc5d0\uc11c \ubc14\ub85c \ub530\ub77c\uc635\ub2c8\ub2e4.\\n\\n## 10. \uac1c\ub150 \uc694\uc57d\\n\\n\uc9c0\uae08\uae4c\uc9c0\uc758 \uc774\uc57c\uae30\ub294 \uc77c\uad00\ub418\uace0 \uac04\uacb0\ud569\ub2c8\ub2e4.\\n\\n1. \uac15\uccb4\uc758 \uc6b4\ub3d9\uc740 twist\ub85c \ud45c\ud604\ud569\ub2c8\ub2e4.\\n2. \uad00\uc808\uc740 screw axis\ub97c \uc815\uc758\ud569\ub2c8\ub2e4.\\n3. \uc720\ud55c \uc6b4\ub3d9\uc740 exponential map\uc73c\ub85c \uc0dd\uc131\ud569\ub2c8\ub2e4.\\n4. \ub9d0\ub2e8 \uc7a5\uce58 twist\ub294 \uad00\uc808 \uae30\uc5ec\uc758 \ud569\uc785\ub2c8\ub2e4.\\n5. Jacobian\uc740 \uc774 \uae30\uc5ec\ub97c \ud589\ub82c\ub85c \ubaa8\uc74d\ub2c8\ub2e4.\\n6. Jacobian\uc774 rank\ub97c \uc783\uc73c\uba74 singularity\uac00 \ub098\ud0c0\ub0a9\ub2c8\ub2e4.\\n\\n\uc774 \ud750\ub984\uc774 Modern Robotics\ub97c \uac15\ub825\ud558\uac8c \ub9cc\ub4ed\ub2c8\ub2e4. \ubcf5\uc7a1\ud55c \ub85c\ubd07 \uc6b4\ub3d9\uc744 \uae30\ud558, \ub300\uc218, \uc120\ud615\ud654\ub85c \uc774\ub8e8\uc5b4\uc9c4 \uc815\ubc00\ud55c \uad6c\uc870\ub85c \ubc14\uafb8\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.\\n\\n\ub530\ub77c\uc11c Jacobian\uc774 \uc911\uc694\ud558\ub2e4\uace0 \ub9d0\ud560 \ub54c \uc758\ubbf8\ud558\ub294 \ubc14\ub294 \uad6c\uccb4\uc801\uc785\ub2c8\ub2e4.\\n\\n$$\\n\\\\boxed{\\\\nu = J(\\\\theta)\\\\dot{\\\\theta}}\\n$$\\n\\n\uc774 \uc2dd\uc740 configuration-space \uc6b4\ub3d9\uacfc task-space \uc6b4\ub3d9\uc744 \uc5f0\uacb0\ud558\ub294 \uae30\ubcf8 \uad00\uacc4\uc785\ub2c8\ub2e4.\\n\\n\uc774 \uac04\uacb0\ud55c \uacf5\uc2dd\uc774 \uae30\uad6c\ud559\uacfc \uc81c\uc5b4\ub97c \uc787\ub294 \ub2e4\ub9ac\uc785\ub2c8\ub2e4."},{"id":"modern-robotics-part-4","metadata":{"permalink":"/ko/blog/modern-robotics-part-4","editUrl":"https://github.com/CMaybe/cmaybe.github.io/tree/main/blog/2026-09-07-modern-robotics-part-4.md","source":"@site/i18n/ko/docusaurus-plugin-content-blog/2026-09-07-modern-robotics-part-4.md","title":"Modern Robotics, Part 4 \u2014 Manipulability\uc640 \uc18d\ub3c4 \uc81c\uc5b4","description":"Jacobian \uae30\ubc18 \uc18d\ub3c4 \uc81c\uc5b4, manipulability \uce21\uc815, \uc81c\uc57d\uc774 \uc788\ub294 task-space \uc6b4\ub3d9\uc744 \ub2ec\uc131\ud558\uae30 \uc704\ud55c pseudoinverse \ubc29\ubc95\uc744 \uc790\uc138\ud788 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.","date":"2026-09-07T00:00:00.000Z","tags":[{"inline":false,"label":"Robotics","permalink":"/ko/blog/tags/robotics","description":"Robot software, systems, and experiments."},{"inline":false,"label":"Modern Robotics","permalink":"/ko/blog/tags/modern-robotics","description":"Concepts, methods, and intuition behind rigid-body motion and robot kinematics."},{"inline":false,"label":"Kinematics","permalink":"/ko/blog/tags/kinematics","description":"Forward and inverse kinematics for robots."},{"inline":false,"label":"Screw Theory","permalink":"/ko/blog/tags/screw-theory","description":"Twists, screw axes, and the geometry of rigid-body motion."}],"readingTime":5.44,"hasTruncateMarker":true,"authors":[{"name":"Jaegyeom Kim","title":"Robotics Software Engineer","url":"https://github.com/CMaybe","page":{"permalink":"/ko/blog/authors/endi"},"socials":{"github":"https://github.com/CMaybe","linkedin":"https://www.linkedin.com/in/Jaegyeom-kim-185b8a2a4/"},"imageURL":"https://github.com/CMaybe.png","key":"endi"}],"frontMatter":{"slug":"modern-robotics-part-4","title":"Modern Robotics, Part 4 \u2014 Manipulability\uc640 \uc18d\ub3c4 \uc81c\uc5b4","authors":["endi"],"tags":["robotics","modern-robotics","kinematics","screw-theory"],"description":"Jacobian \uae30\ubc18 \uc18d\ub3c4 \uc81c\uc5b4, manipulability \uce21\uc815, \uc81c\uc57d\uc774 \uc788\ub294 task-space \uc6b4\ub3d9\uc744 \ub2ec\uc131\ud558\uae30 \uc704\ud55c pseudoinverse \ubc29\ubc95\uc744 \uc790\uc138\ud788 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4."},"unlisted":false,"prevItem":{"title":"Modern Robotics, Part 3 \u2014 Jacobian\uacfc \ub9d0\ub2e8 \uc7a5\uce58 \uc18d\ub3c4","permalink":"/ko/blog/modern-robotics-part-3"},"nextItem":{"title":"Modern Robotics, Part 5 \u2014 \uc5ed\uae30\uad6c\ud559\uacfc \uc218\uce58 \ud574\ubc95","permalink":"/ko/blog/modern-robotics-part-5"}},"content":"Jacobian\uc740 \ub2e8\uc21c\ud55c \uc218\ud559\uc801 \ub300\uc0c1\uc774 \uc544\ub2c8\ub77c \uc2e4\uc81c \ub85c\ubd07 \uc6b4\ub3d9 \uc81c\uc5b4\ub97c \uac00\ub2a5\ud558\uac8c \ud558\ub294 \uc5d4\uc9c4\uc785\ub2c8\ub2e4. \ub2e4\uc74c\uc744 \uc54c\uace0 \ub098\uba74\\n\\n$$\\n\\\\nu = J(\\\\theta)\\\\dot{\\\\theta},\\n$$\\n\\n\ub2e4\uc74c\uacfc \uac19\uc740 \uc2e4\uc6a9\uc801\uc778 \uc9c8\ubb38\uc744 \ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n> \uc6d0\ud558\ub294 \ub9d0\ub2e8 \uc7a5\uce58 twist $\\\\nu_d$\uac00 \uc8fc\uc5b4\uc84c\uc744 \ub54c \uad00\uc808 \uc18d\ub3c4\ub294 \uc5b4\ub5bb\uac8c \uc815\ud574\uc57c \ud558\ub294\uac00?\\n\\n\uc774\uac83\uc774 \uc18d\ub3c4 \uc81c\uc5b4\uc758 \ud575\uc2ec\uc785\ub2c8\ub2e4.\\n\\n\ub2f5\uc740 Jacobian\uc774 \uc815\uc0ac\uac01\uc778\uc9c0, \uc138\ub85c\ub85c \uae34\uc9c0, \ub610\ub294 rank\uac00 \ubd80\uc871\ud55c\uc9c0\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9d1\ub2c8\ub2e4. \uc5ec\uae30\uc11c pseudoinverse \uc81c\uc5b4, manipulability, task-space conditioning\uc774\ub77c\ub294 \uac1c\ub150\uc774 \uc790\uc5f0\uc2a4\ub7fd\uac8c \ub098\uc635\ub2c8\ub2e4.\\n\\n\x3c!-- truncate --\x3e\\n\\n## 1. \uae30\ubcf8 \uc18d\ub3c4 \uc81c\uc5b4 \ubb38\uc81c\\n\\n\ub9d0\ub2e8 \uc7a5\uce58\ub97c \ub2e4\uc74c desired twist\ub85c \uc6c0\uc9c1\uc774\uace0 \uc2f6\ub2e4\uace0 \ud569\uc2dc\ub2e4.\\n\\n$$\\n\\\\nu_d = \\\\begin{bmatrix}\\n\\\\omega_d \\\\\\\\\\\\ v_d\\n\\\\end{bmatrix}.\\n$$\\n\\n\uadf8\ub7ec\uba74 \ub2e4\uc74c\uc744 \ub9cc\uc871\ud558\ub294 \uad00\uc808 \uc18d\ub3c4\ub97c \uad6c\ud574\uc57c \ud569\ub2c8\ub2e4.\\n\\n$$\\nJ(\\\\theta)\\\\dot{\\\\theta} = \\\\nu_d.\\n$$\\n\\n$J$\uac00 \uc815\uc0ac\uac01\uc774\uace0 nonsingular\uc774\uba74 \ud574\ub294 \ubc14\ub85c \uad6c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n$$\\n\\\\dot{\\\\theta} = J(\\\\theta)^{-1}\\\\nu_d.\\n$$\\n\\n\uc774\uac83\uc774 Jacobian \uae30\ubc18 \uc81c\uc5b4\uc758 \uac00\uc7a5 \uc9c1\uc811\uc801\uc778 \ud615\ud0dc\uc785\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \ub85c\ubd07\uc774 $J$\uac00 \uac00\uc5ed\uc778 configuration\uc5d0 \uc788\uc744 \ub54c\ub9cc \uc791\ub3d9\ud569\ub2c8\ub2e4.\\n\\n\uc2e4\uc81c \ub9e4\ub2c8\ud4f0\ub808\uc774\ud130\ub294 redundant\ud558\uac70\ub098 underactuated\uc778 \uacbd\uc6b0\uac00 \ub9ce\uace0 singularity \uadfc\ucc98\uc5d0 \uc788\uc744 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub54c \ud558\ub098\uc758 \uc815\ud655\ud55c \uc5ed\ud589\ub82c\uc774 \uc874\uc7ac\ud558\uc9c0 \uc54a\uac70\ub098 \uc218\uce58\uc801\uc73c\ub85c \ubd88\uc548\uc815\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n## 2. Redundancy\uc640 pseudoinverse\\n\\nJacobian\uc774 \uc815\uc0ac\uac01\uc774 \uc544\ub2c8\uba74 \uc5ed\ud589\ub82c \ub300\uc2e0 Moore\u2013Penrose pseudoinverse\ub97c \uc0ac\uc6a9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n$$\\n\\\\dot{\\\\theta} = J^{\\\\dagger}(\\\\theta)\\\\nu_d.\\n$$\\n\\n\uc774\ub294 \ub2e4\uc74c least-squares \ubb38\uc81c\uc758 minimum-norm \ud574\ub97c \uc81c\uacf5\ud569\ub2c8\ub2e4.\\n\\n$$\\n\\\\min_{\\\\dot{\\\\theta}} \\\\|\\\\dot{\\\\theta}\\\\|^2\\n\\\\quad \\\\text{subject to} \\\\quad\\nJ\\\\dot{\\\\theta} \\\\approx \\\\nu_d.\\n$$\\n\\n\uc774\ub294 \ub85c\ubd07\uacf5\ud559\uc5d0\uc11c \uac00\uc7a5 \uc911\uc694\ud55c \uc2e4\uc6a9 \ub3c4\uad6c \uc911 \ud558\ub098\uc785\ub2c8\ub2e4. Task-space \uc81c\uc57d\ubcf4\ub2e4 \uad00\uc808\uc774 \ub9ce\uc740 \uacbd\uc6b0\uc5d0\ub3c4 \uad00\uc808 \uc18d\ub3c4 \uba85\ub839\uc744 \uacc4\uc0b0\ud560 \uc218 \uc788\uac8c \ud574 \uc90d\ub2c8\ub2e4.\\n\\nPseudoinverse\ub294 redundant manipulator\uc5d0\uc11c \ud2b9\ud788 \uc720\uc6a9\ud569\ub2c8\ub2e4. \uc5ec\ubd84\uc758 \uc790\uc720\ub3c4\ub97c secondary objective\uc5d0 \uc0ac\uc6a9\ud560 \uc218 \uc788\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.\\n\\n\uc608\ub97c \ub4e4\uc5b4 $n>6$\uc778 \ub85c\ubd07\uc740 \uc6d0\ud558\ub294 \ub9d0\ub2e8 \uc7a5\uce58 twist\ub97c \ucd94\uc801\ud558\uba74\uc11c \uad00\uc808 \uc81c\ud55c\uc744 \ud53c\ud558\uac70\ub098, \ud314\uafc8\uce58\ub97c \uc7a5\uc560\ubb3c\uc5d0\uc11c \ub5a8\uc5b4\ub728\ub9ac\uac70\ub098, dexterity\ub97c \ucd5c\ub300\ud654\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n## 3. Secondary objective\ub97c \ud3ec\ud568\ud55c generalized inverse\\n\\nRedundant robot\uc5d0\uc11c\ub294 pseudoinverse \ud574\ub9cc\uc73c\ub85c\ub294 \uc720\uc77c\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \ub2e4\uc74c \ud56d\uc744 \ub354\ud574 \uc6d0\ud558\ub294 \ubaa9\uc801\uc744 \ubc18\uc601\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n$$\\n\\\\dot{\\\\theta} = J^{\\\\dagger}\\\\nu_d + \\\\left(I - J^{\\\\dagger}J\\\\right)\\\\dot{\\\\theta}_0.\\n$$\\n\\n\uc5ec\uae30\uc11c $\\\\dot{\\\\theta}_0$\ub294 \uc120\ud638\ud558\ub294 \uad00\uc808 \uc18d\ub3c4 \ubc29\ud5a5\uc774\uace0, projection \ud56d\\n\\n$$\\nI - J^{\\\\dagger}J\\n$$\\n\\n\uc740 \uc120\ud638 \uc6b4\ub3d9\uc744 Jacobian\uc758 nullspace\ub85c \ud22c\uc601\ud569\ub2c8\ub2e4.\\n\\n\uc774\ub294 \ub9d0\ub2e8 \uc7a5\uce58 \uc6b4\ub3d9\uc744 \uadf8\ub300\ub85c \ub9cc\uc871\ud558\uba74\uc11c \ub0b4\ubd80 \uad00\uc808 \uc6b4\ub3d9\uc744 \uc81c\uc5b4\ub41c \ubc29\uc2dd\uc73c\ub85c \ubc14\uafc0 \uc218 \uc788\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4.\\n\\n\ud574\uc11d\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.\\n\\n- Task-space \uba85\ub839\uc740 $J^{\\\\dagger}\\\\nu_d$\ub85c \uac15\uc81c\ud569\ub2c8\ub2e4.\\n- Nullspace \ud56d\uc740 \ub9d0\ub2e8 \uc7a5\uce58 task\ub97c \ubc29\ud574\ud558\uc9c0 \uc54a\uace0 \ub0b4\ubd80 \uc6b4\ub3d9\uc758 \ud615\ud0dc\ub97c \uc870\uc815\ud569\ub2c8\ub2e4.\\n\\n\uc774\ub294 redundant manipulation\uc758 \ud575\uc2ec \uac1c\ub150\uc774\uba70 \uc2e4\uc81c \ub85c\ubd07 \uc2dc\uc2a4\ud15c\uc5d0\uc11c \ub110\ub9ac \uc0ac\uc6a9\ub429\ub2c8\ub2e4.\\n\\n## 4. Manipulability: \ub85c\ubd07\uc740 \uc5bc\ub9c8\ub098 \uc798 \uc6c0\uc9c1\uc774\ub294\uac00?\\n\\nJacobian\uc740 \uc6b4\ub3d9 \ubc29\ud5a5\ubfd0 \uc544\ub2c8\ub77c \uc11c\ub85c \ub2e4\ub978 \ubc29\ud5a5\uc73c\ub85c \uc6b4\ub3d9\uc744 \ub9cc\ub4e4\uae30 \uc5bc\ub9c8\ub098 \uc26c\uc6b4\uc9c0\ub3c4 \uc54c\ub824 \uc90d\ub2c8\ub2e4. \uc774\ub97c \uc815\ub7c9\ud654\ud560 \ub54c manipulability\ub97c \uc0ac\uc6a9\ud569\ub2c8\ub2e4.\\n\\nConfiguration $\\\\theta$\uc5d0\uc11c singular value\ub97c\\n\\n$$\\n\\\\sigma_1, \\\\sigma_2, \\\\ldots, \\\\sigma_m\\n$$\\n\\n\uc774\ub77c\uace0 \ud569\uc2dc\ub2e4.\\n\\n\ud754\ud788 \uc0ac\uc6a9\ud558\ub294 scalar measure\ub294 \uc815\uc0ac\uac01 Jacobian\uc5d0\uc11c\\n\\n$$\\n\\\\mu = \\\\sqrt{\\\\det(JJ^T)}\\n$$\\n\\n\uc774\uba70, \ub354 \uc77c\ubc18\uc801\uc73c\ub85c full row rank\uc778 \uacbd\uc6b0\uc5d0\ub3c4\\n\\n$$\\n\\\\mu = \\\\sqrt{\\\\det(JJ^T)}\\n$$\\n\\n\ub85c \uc815\uc758\ud569\ub2c8\ub2e4.\\n\\n\uc774 \uac12\uc740 \ub85c\ubd07\uc758 conditioning\uc774 \uc88b\uc744 \ub54c \ud06c\uace0 singularity\uc5d0 \uac00\uae4c\uc6b8 \ub54c \uc791\uc2b5\ub2c8\ub2e4.\\n\\n\ub610 \ub2e4\ub978 \uc720\uc6a9\ud55c \uc9c0\ud45c\ub294 condition number\uc785\ub2c8\ub2e4.\\n\\n$$\\n\\\\kappa(J) = \\\\frac{\\\\sigma_{\\\\max}}{\\\\sigma_{\\\\min}}.\\n$$\\n\\n$\\\\sigma_{\\\\min}$\uc774 \ub9e4\uc6b0 \uc791\uc73c\uba74 \ub85c\ubd07\uc740 singular configuration\uc5d0 \uac00\uae4c\uc6b0\uba70 \uc77c\ubd80 \uc6b4\ub3d9 \ubc29\ud5a5\uc744 \uad6c\ud604\ud558\uae30\uac00 \ub9e4\uc6b0 \uc5b4\ub824\uc6cc\uc9d1\ub2c8\ub2e4.\\n\\n\uc774 \ub54c\ubb38\uc5d0 manipulability\uac00 \uac00\uce58 \uc788\uc2b5\ub2c8\ub2e4. \ub2e8\uc21c\ud788 \uc6c0\uc9c1\uc77c \uc218 \uc788\ub294\uc9c0\ubfd0 \uc544\ub2c8\ub77c \uc6b4\ub3d9\uc758 \ud488\uc9c8\uc744 \uc815\ub7c9\ud654\ud558\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.\\n\\n## 5. Singularity\uc640 \uc218\uce58 \ubd88\uc548\uc815\uc131\\n\\nSingularity \uadfc\ucc98\uc5d0\uc11c\ub294 Jacobian\uc758 conditioning\uc774 \ub098\ube60\uc9d1\ub2c8\ub2e4. \uadf8\ub7ec\uba74 \uc791\uc740 \ub9d0\ub2e8 \uc7a5\uce58 \uc18d\ub3c4\uc5d0\ub3c4 \ud070 \uad00\uc808 \uc18d\ub3c4\uac00 \ud544\uc694\ud569\ub2c8\ub2e4.\\n\\n$$\\n\\\\dot{\\\\theta} \\\\approx J^{-1}\\\\nu_d.\\n$$\\n\\n$J$\uc5d0 \ub9e4\uc6b0 \uc791\uc740 singular value\uac00 \uc788\uc73c\uba74 \uc791\uc740 task-space \uba85\ub839\uc774 \ud070 \uad00\uc808 \uc18d\ub3c4 \uc751\ub2f5\uc744 \ub9cc\ub4ed\ub2c8\ub2e4.\\n\\n\ub530\ub77c\uc11c \uc81c\uc5b4 \uc2dc\uc2a4\ud15c\uc740 singular configuration \uadfc\ucc98\uc5d0\uc11c damping\uc774\ub098 regularization\uc744 \ud3ec\ud568\ud574\uc57c \ud569\ub2c8\ub2e4.\\n\\nDamped least-squares \ud574\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.\\n\\n$$\\n\\\\dot{\\\\theta} = J^T(JJ^T + \\\\lambda^2 I)^{-1}\\\\nu_d,\\n$$\\n\\n\uc5ec\uae30\uc11c $\\\\lambda > 0$\ub294 damping factor\uc785\ub2c8\ub2e4.\\n\\n\uc774\ub294 \uad00\uc808 \uc18d\ub3c4\uac00 \ud3ed\ubc1c\ud558\ub294 \uac83\uc744 \ub9c9\uace0 Jacobian\uc758 conditioning\uc774 \uc88b\uc9c0 \uc54a\uc744 \ub54c\ub3c4 \ub354 \uc548\uc815\uc801\uc778 \uba85\ub839\uc744 \uc81c\uacf5\ud569\ub2c8\ub2e4.\\n\\n\uc774\uac83\uc740 \uc774\ub860\uc801\uc73c\ub85c \uc6b0\uc544\ud55c \uacf5\uc2dd\uc744 \uc2e4\uc81c \uacf5\ud559\uc5d0 \ub9de\uac8c \ubcf4\uc815\ud55c \uac83\uc785\ub2c8\ub2e4. \ud604\uc2e4\uc5d0\uc11c\ub294 singularity\ub97c \ubb34\uc2dc\ud560 \ub9cc\ud07c \ub4dc\ubb3c\uc9c0 \uc54a\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.\\n\\n## 6. Manipulability\uc758 \uae30\ud558\ud559 \uc774\ud574\\n\\nJacobian\uc758 singular value\ub294 \ub85c\ubd07\uc774 \uad00\uc808 \uc18d\ub3c4\ub97c task-space \uc18d\ub3c4\ub85c \ubc14\uafb8\ub294 \ubc29\uc2dd\uc744 \uc124\uba85\ud569\ub2c8\ub2e4. \uae30\ud558\ud559\uc801\uc73c\ub85c\ub294 \uac01 \ubc29\ud5a5\uc73c\ub85c \uac00\ub2a5\ud55c \ub9d0\ub2e8 \uc7a5\uce58 \uc6b4\ub3d9\uc758 \ud06c\uae30\ub97c \ub73b\ud569\ub2c8\ub2e4.\\n\\nSingular value\uac00 \ubaa8\ub450 \ud06c\uace0 \uc11c\ub85c \ube44\uc2b7\ud558\uba74 \ub85c\ubd07\uc740 conditioning\uc774 \uc88b\uace0 task space\uc5d0\uc11c \ub4f1\ubc29\uc801\uc73c\ub85c \uc6c0\uc9c1\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\ud55c singular value\uac00 \uc791\uc73c\uba74 \ub85c\ubd07\uc740 \ub192\uc740 \uc774\ub3d9\uc131\uc744 \uac16\ub294 \ubc29\ud5a5\uacfc \ub098\uc05c \uc6b4\ub3d9 \ubc29\ud5a5\uc744 \uac16\uc2b5\ub2c8\ub2e4. \uc989 \uc5b4\ub5a4 \ubc29\ud5a5\uc73c\ub85c\ub294 \uc27d\uac8c \uc6c0\uc9c1\uc774\uc9c0\ub9cc \ub2e4\ub978 \ubc29\ud5a5\uc73c\ub85c\ub294 \uc798 \uc6c0\uc9c1\uc774\uc9c0 \ubabb\ud569\ub2c8\ub2e4.\\n\\n\uc774\ub294 \ub9e4\ub2c8\ud4f0\ub808\uc774\ud130\uc758 \uae30\ud558\uc640 \uc9c1\uc811 \uc5f0\uacb0\ub429\ub2c8\ub2e4.\\n\\n- \uc815\ub82c\ub41c \uad00\uc808 \ucd95\uc740 \uc774\ub3d9\uc131\uc744 \uc904\uc785\ub2c8\ub2e4.\\n- \ud2b9\uc815 \uc790\uc138\uc5d0 \ub193\uc778 \ub9c1\ud06c\ub294 \ube44\ub4f1\ubc29\uc131 \uc6b4\ub3d9\uc744 \ub9cc\ub4ed\ub2c8\ub2e4.\\n- Singularity\uc5d0 \uac00\uae4c\uc6b4 \uc790\uc138\ub294 \uad6d\uc18c \uc81c\uc5b4\ub825\uc744 \uc5c6\uc571\ub2c8\ub2e4.\\n\\n\uc774\ub294 \ub9e4\uc6b0 \uae30\ud558\ud559\uc801\uc778 \uad00\uc810\uc785\ub2c8\ub2e4. Jacobian\uc740 \ub300\uc218\ub9cc \ub2f4\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uae30\uad6c\uac00 \uc2e4\uc81c\ub85c \uc5b4\ub290 \ubc29\ud5a5\uc73c\ub85c \uc5bc\ub9c8\ub098 \uc6c0\uc9c1\uc77c \uc218 \uc788\ub294\uc9c0\ub97c \ub2f4\uc2b5\ub2c8\ub2e4.\\n\\n## 7. Screw geometry\uc640\uc758 \uad00\uacc4\\n\\nJacobian\uc758 \uc5f4\uc740 screw axis\uc774\uba70, \uac01 singular value\ub294 \ub300\uc751\ud558\ub294 \uad00\uc808 \uc6b4\ub3d9\uc774 task-space \uc6b4\ub3d9\uc5d0 \uc5bc\ub9c8\ub098 \uac15\ud558\uac8c \uae30\uc5ec\ud558\ub294\uc9c0\ub97c \ub098\ud0c0\ub0b4\ub294 \ucc99\ub3c4\uc785\ub2c8\ub2e4.\\n\\n\uc774\ub7f0 \uc758\ubbf8\uc5d0\uc11c manipulability\ub294 screw-axis \uc815\uc2dd\ud654\uc640 \ub5a8\uc5b4\uc838 \uc788\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. Screw-axis \ud589\ub82c\uc758 \uad6c\uc870\ub97c \uc694\uc57d\ud558\ub294 \ubc29\ubc95\uc77c \ubfd0\uc785\ub2c8\ub2e4.\\n\\nScrew axis\uac00 task space\uc5d0 \uc798 \ubd84\uc0b0\ub418\uc5b4 \uc788\uc73c\uba74 \ub85c\ubd07\uc740 \ub192\uc740 dexterity\ub97c \uac16\uc2b5\ub2c8\ub2e4. \uc11c\ub85c \uc120\ud615 \uc885\uc18d\uc5d0 \uac00\uae4c\uc6cc\uc9c0\uba74 \ubc29\ud5a5\uc131\uc774 \uc0ac\ub77c\uc9c0\uace0 singularity\uc5d0 \ub3c4\ub2ec\ud569\ub2c8\ub2e4.\\n\\n\ub530\ub77c\uc11c \uae30\ud558\ud559\uc801 \uad00\uc810\uacfc \ub300\uc218\uc801 \uad00\uc810\uc740 \uc11c\ub85c \ub2e4\ub978 \uc5b8\uc5b4\ub85c \ud45c\ud604\ud55c \uac19\uc740 \ub0b4\uc6a9\uc785\ub2c8\ub2e4.\\n\\n- Screw axis\ub294 \uc6b4\ub3d9 \ubc29\ud5a5\uc744 \uc124\uba85\ud569\ub2c8\ub2e4.\\n- Jacobian rank\uc640 singular value\ub294 \uadf8 \ubc29\ud5a5\ub4e4\uc774 \uc5bc\ub9c8\ub098 \ub3c5\ub9bd\uc801\uc778\uc9c0 \uc124\uba85\ud569\ub2c8\ub2e4.\\n\\n## 8. Closed-loop task-space control\\n\\n\uc2e4\uc81c \ub85c\ubd07 \uc81c\uc5b4\ub294 \ud754\ud788 closed-loop system\uc73c\ub85c \uad6c\ud604\ub429\ub2c8\ub2e4. \ubaa9\ud45c\ub294 desired pose \ub610\ub294 trajectory $T_d(t)$\ub97c \ucd94\uc801\ud558\ub294 \uac83\uc785\ub2c8\ub2e4.\\n\\n\uac01 \uc21c\uac04\uc5d0 task-space error\ub97c \uacc4\uc0b0\ud558\uba70, \ud754\ud788 twist error\ub85c \ub098\ud0c0\ub0c5\ub2c8\ub2e4.\\n\\n$$\\n\\\\nu_e = \\\\nu_d - \\\\nu.\\n$$\\n\\n\uadf8\ub2e4\uc74c \ub2e4\uc74c \uc2dd\uc73c\ub85c \uad00\uc808 \uba85\ub839\uc744 \uac31\uc2e0\ud569\ub2c8\ub2e4.\\n\\n$$\\n\\\\dot{\\\\theta} = J^{\\\\dagger}(\\\\theta)\\\\nu_e + \\\\left(I - J^{\\\\dagger}J\\\\right)\\\\dot{\\\\theta}_0.\\n$$\\n\\n\uc774\ub294 feedback law\ucc98\ub7fc \ub3d9\uc791\ud569\ub2c8\ub2e4. \ub9d0\ub2e8 \uc7a5\uce58\uac00 \uc6d0\ud558\ub294 \ub300\ub85c \uc6c0\uc9c1\uc774\uc9c0 \uc54a\uc73c\uba74 control law\uac00 \uc774\ub97c \ubcf4\uc815\ud569\ub2c8\ub2e4.\\n\\n\ub2e4\uc74c\uacfc \uac19\uc740 \ub2e8\uc21c\ud55c \ube44\ub840 \ud615\ud0dc\ub3c4 \uc790\uc8fc \uc0ac\uc6a9\ud569\ub2c8\ub2e4.\\n\\n$$\\n\\\\nu_e = K_p e,\\n$$\\n\\n\uc5ec\uae30\uc11c $e$\ub294 pose error\uc774\uace0 $K_p$\ub294 gain matrix\uc785\ub2c8\ub2e4. \uad00\uc808 \uc18d\ub3c4 \uba85\ub839\uc740 Jacobian\uc73c\ub85c\ubd80\ud130 \uc5bb\uc2b5\ub2c8\ub2e4.\\n\\n\uc774\uac83\uc774 \ud604\ub300 \ub85c\ubd07\uacf5\ud559\uc758 operational-space control\uacfc task-space controller\uac00 \uc791\ub3d9\ud558\ub294 \uae30\ubcf8 \ub17c\ub9ac\uc785\ub2c8\ub2e4.\\n\\n## 9. Jacobian\uc774 \uacc4\uc18d \uc911\uc2ec\uc5d0 \uc788\ub294 \uc774\uc720\\n\\n\uc774\uc81c Jacobian\uc774 \ub85c\ubd07 \uae30\uad6c\ud559\uacfc \uc81c\uc5b4\uc758 \uc911\uc2ec \ub300\uc0c1\uc774\ub77c\ub294 \uc810\uc774 \ubd84\uba85\ud574\uc84c\uc2b5\ub2c8\ub2e4.\\n\\nJacobian\uc740 \ub2e4\uc74c\uc744 \uc54c\ub824 \uc90d\ub2c8\ub2e4.\\n\\n- \uc791\uc740 \uad00\uc808 \uc6b4\ub3d9\uc774 \ub9d0\ub2e8 \uc7a5\uce58 \uc6b4\ub3d9\uc744 \ub9cc\ub4dc\ub294 \ubc29\uc2dd,\\n- \uc6d0\ud558\ub294 \uad00\uc808 \uc18d\ub3c4\ub97c \uacc4\uc0b0\ud558\ub294 \ubc29\ubc95,\\n- dexterity\ub97c \uce21\uc815\ud558\ub294 \ubc29\ubc95,\\n- system\uc774 singular\ud574\uc9c0\ub294 \uc2dc\uc810,\\n- task space\uc5d0\uc11c \uc791\ub3d9\ud558\ub294 controller\ub97c \uad6c\uc131\ud558\ub294 \ubc29\ubc95\uc785\ub2c8\ub2e4.\\n\\n\uadf8\ub798\uc11c Jacobian\uc740 \ud604\ub300 \ub85c\ubd07 \uae30\uad6c\ud559\uc758 \ud575\uc2ec\uc774\ub77c\uace0 \ud569\ub2c8\ub2e4. \uae30\ud558\ud559\uacfc \uc81c\uc5b4\ub97c \uac00\uc7a5 \uc9c1\uc811\uc801\uc73c\ub85c \uc5f0\uacb0\ud558\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.\\n\\n\uc55e\uc120 \uae00\uc5d0\uc11c twist\uc640 screw axis\ub97c \ud1b5\ud574 \uc774\ub860\uc801 \uae30\ubc18\uc744 \uc138\uc6e0\ub2e4\uba74, \uc5ec\uae30\uc11c\ub294 \uadf8 \uae30\ubc18\uc774 \uc2e4\uc81c controller\uc5d0\uc11c \uc5b4\ub5bb\uac8c \uc791\ub3d9\ud558\ub294\uc9c0 \ubd05\ub2c8\ub2e4.\\n\\n## 10. \uac1c\ub150 \uc694\uc57d\\n\\n\uc774\ubc88 \uae00\uc758 \uc911\uc2ec \uacf5\uc2dd\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.\\n\\n$$\\n\\\\nu = J(\\\\theta)\\\\dot{\\\\theta},\\n$$\\n\\n$$\\n\\\\dot{\\\\theta} = J^{\\\\dagger}\\\\nu_d,\\n$$\\n\\n\uadf8\ub9ac\uace0 redundancy\uac00 \uc788\uc744 \ub54c\ub294\\n\\n$$\\n\\\\dot{\\\\theta} = J^{\\\\dagger}\\\\nu_d + (I - J^{\\\\dagger}J)\\\\dot{\\\\theta}_0.\\n$$\\n\\n\uc774 \uc2dd\ub4e4\uc740 \ub85c\ubd07\uc758 \uae30\ud558\ud559\uc801 \uad6c\uc870\uac00 \uc5b4\ub5bb\uac8c \uc81c\uc5b4 \uc54c\uace0\ub9ac\uc998\uc73c\ub85c \ubc14\ub00c\ub294\uc9c0 \ubcf4\uc5ec \uc90d\ub2c8\ub2e4.\\n\\n\ub530\ub77c\uc11c Jacobian\uc740 \ub2e8\uc21c\ud788 \uc124\uba85\uc744 \uc704\ud55c \ub300\uc0c1\uc774 \uc544\ub2d9\ub2c8\ub2e4. \uc2e4\uc81c\ub85c \uc791\ub3d9\ud558\ub294 \ub3c4\uad6c\uc785\ub2c8\ub2e4.\\n\\n\uc774\uac83\uc774 Modern Robotics\uc758 \uc2e4\uc6a9\uc801\uc778 \ud798\uc785\ub2c8\ub2e4."},{"id":"modern-robotics-part-5","metadata":{"permalink":"/ko/blog/modern-robotics-part-5","editUrl":"https://github.com/CMaybe/cmaybe.github.io/tree/main/blog/2026-09-07-modern-robotics-part-5.md","source":"@site/i18n/ko/docusaurus-plugin-content-blog/2026-09-07-modern-robotics-part-5.md","title":"Modern Robotics, Part 5 \u2014 \uc5ed\uae30\uad6c\ud559\uacfc \uc218\uce58 \ud574\ubc95","description":"Jacobian \uae30\ubc18 \ubc29\ubc95, \ud574\uc11d\uc801 \ud574\ubc95, \ubc18\ubcf5 \uc218\uce58 \uc804\ub7b5\uc744 \uc0ac\uc6a9\ud574 \ub85c\ubd07 pose\ub97c \uad6c\ud558\ub294 \uc5ed\uae30\uad6c\ud559\uc744 \uc790\uc138\ud788 \uc124\uba85\ud569\ub2c8\ub2e4.","date":"2026-09-07T00:00:00.000Z","tags":[{"inline":false,"label":"Robotics","permalink":"/ko/blog/tags/robotics","description":"Robot software, systems, and experiments."},{"inline":false,"label":"Modern Robotics","permalink":"/ko/blog/tags/modern-robotics","description":"Concepts, methods, and intuition behind rigid-body motion and robot kinematics."},{"inline":false,"label":"Kinematics","permalink":"/ko/blog/tags/kinematics","description":"Forward and inverse kinematics for robots."},{"inline":false,"label":"Screw Theory","permalink":"/ko/blog/tags/screw-theory","description":"Twists, screw axes, and the geometry of rigid-body motion."}],"readingTime":5.72,"hasTruncateMarker":true,"authors":[{"name":"Jaegyeom Kim","title":"Robotics Software Engineer","url":"https://github.com/CMaybe","page":{"permalink":"/ko/blog/authors/endi"},"socials":{"github":"https://github.com/CMaybe","linkedin":"https://www.linkedin.com/in/Jaegyeom-kim-185b8a2a4/"},"imageURL":"https://github.com/CMaybe.png","key":"endi"}],"frontMatter":{"slug":"modern-robotics-part-5","title":"Modern Robotics, Part 5 \u2014 \uc5ed\uae30\uad6c\ud559\uacfc \uc218\uce58 \ud574\ubc95","authors":["endi"],"tags":["robotics","modern-robotics","kinematics","screw-theory"],"description":"Jacobian \uae30\ubc18 \ubc29\ubc95, \ud574\uc11d\uc801 \ud574\ubc95, \ubc18\ubcf5 \uc218\uce58 \uc804\ub7b5\uc744 \uc0ac\uc6a9\ud574 \ub85c\ubd07 pose\ub97c \uad6c\ud558\ub294 \uc5ed\uae30\uad6c\ud559\uc744 \uc790\uc138\ud788 \uc124\uba85\ud569\ub2c8\ub2e4."},"unlisted":false,"prevItem":{"title":"Modern Robotics, Part 4 \u2014 Manipulability\uc640 \uc18d\ub3c4 \uc81c\uc5b4","permalink":"/ko/blog/modern-robotics-part-4"},"nextItem":{"title":"Modern Robotics, Part 6A \u2014 \ub3d9\uc5ed\ud559, \uc81c\uc5b4, \uadf8\ub9ac\uace0 \uc6b4\ub3d9 \uc0dd\uc131","permalink":"/ko/blog/modern-robotics-part-6"}},"content":"Forward kinematics\uc640 Jacobian\uc744 \uc774\ud574\ud588\ub2e4\uba74 \ub2e4\uc74c \uc790\uc5f0\uc2a4\ub7ec\uc6b4 \uc9c8\ubb38\uc740 \uc5ed\ubb38\uc81c\uc785\ub2c8\ub2e4.\\n\\n> \uc6d0\ud558\ub294 \ub9d0\ub2e8 \uc7a5\uce58 pose\uac00 \uc8fc\uc5b4\uc84c\uc744 \ub54c \uc774\ub97c \uc2e4\ud604\ud558\ub294 \uad00\uc808 \ubcc0\uc218\ub294 \ubb34\uc5c7\uc778\uac00?\\n\\n\uc774\uac83\uc774 \uc5ed\uae30\uad6c\ud559 \ubb38\uc81c\uc785\ub2c8\ub2e4.\\n\\n\ub300\ubd80\ubd84\uc758 \ub85c\ubd07\uc5d0\uc11c \uc5ed\uae30\uad6c\ud559\uc740 \ube44\uc120\ud615\uc774\uba70 \ud574\uc11d\uc801\uc73c\ub85c \ud480\uae30 \uc5b4\ub824\uc6b4 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4. \ub9e4\ub2c8\ud4f0\ub808\uc774\ud130\uc758 \uae30\ud558\uac00 \uc911\uc694\ud558\uace0, \ub85c\ubd07\uc774 \ub2e8\uc21c\ud55c\uc9c0 redundant\ud55c\uc9c0 \ub610\ub294 \uc81c\uc57d\uc774 \ub9ce\uc740\uc9c0\uc5d0 \ub530\ub77c \ud574\ubc95\uc744 \ud06c\uac8c \ub2ec\ub9ac \uc120\ud0dd\ud574\uc57c \ud569\ub2c8\ub2e4.\\n\\n\x3c!-- truncate --\x3e\\n\\n## 1. Forward kinematics\uc640 inverse kinematics\\n\\nForward kinematics\ub294\\n\\n$$\\nT_{se}(\\\\theta) = T_{se}(\\\\theta_1, \\\\ldots, \\\\theta_n).\\n$$\\n\\n\uc744 \uc81c\uacf5\ud569\ub2c8\ub2e4. Inverse kinematics\ub294 \ub2e4\uc74c\uc744 \ub9cc\uc871\ud558\ub294 \uad00\uc808 \ubca1\ud130 $\\\\theta$\ub97c \uad6c\ud569\ub2c8\ub2e4.\\n\\n$$\\nT_{se}(\\\\theta) = T_d,\\n$$\\n\\n\uc5ec\uae30\uc11c $T_d$\ub294 \ubaa9\ud45c \uac15\uccb4 \ubcc0\ud658\uc785\ub2c8\ub2e4.\\n\\n\uc774\ub294 $\\\\theta$\uc5d0\uc11c $T$\ub85c \uac00\ub294 \uc0ac\uc0c1\uc774 \ube44\uc120\ud615\uc774\uace0 \uc5ec\ub7ec \uac12\uc744 \uac00\uc9c8 \uc218 \uc788\uae30 \ub54c\ubb38\uc5d0 forward kinematics\ubcf4\ub2e4 \ud6e8\uc52c \uc5b4\ub835\uc2b5\ub2c8\ub2e4. \ub85c\ubd07\uc5d0\ub294 \ub2e4\uc74c\uacfc \uac19\uc740 \uacbd\uc6b0\uac00 \uc788\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n- \uc815\ud655\ud55c \ud574\uac00 \uc5c6\ub294 \uacbd\uc6b0,\\n- \uc720\ud55c \uac1c\uc758 \uc815\ud655\ud55c \ud574\uac00 \uc788\ub294 \uacbd\uc6b0,\\n- redundant\ud558\uba74 \ubb34\ud55c\ud788 \ub9ce\uc740 \ud574\uac00 \uc788\ub294 \uacbd\uc6b0,\\n- \uadfc\uc0ac \uc218\uce58 \ud574\ub9cc \uc874\uc7ac\ud558\ub294 \uacbd\uc6b0\uc785\ub2c8\ub2e4.\\n\\n\uc774\uac83\uc774 \uc5ed\uae30\uad6c\ud559\uc774 \ub85c\ubd07\uacf5\ud559\uc758 \ud575\uc2ec \uc8fc\uc81c\uc778 \uc774\uc720 \uc911 \ud558\ub098\uc785\ub2c8\ub2e4.\\n\\n## 2. IK\uc758 \uae30\ud558\\n\\n\ub9ce\uc740 \ub9e4\ub2c8\ud4f0\ub808\uc774\ud130\uc5d0\uc11c\ub294 \uae30\ud558\uac00 \ub354 \ub2e8\uc21c\ud55c \ubd80\ubd84 \ubb38\uc81c\ub85c \ubd84\ud574\ub420 \ub54c \uc5ed\uae30\uad6c\ud559\uc744 \uc27d\uac8c \ud480 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4 6-DOF \ub9e4\ub2c8\ud4f0\ub808\uc774\ud130\ub294 \ub2e4\uc74c\uacfc \uac19\uc774 \ub098\ub20c \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n- \uc704\uce58 \ud574,\\n- \ubc29\ud5a5 \ud574,\\n- \uc190\ubaa9 \ubc29\ud5a5 \uc815\ub82c\uc785\ub2c8\ub2e4.\\n\\n\uae30\uad6c\uc758 \uad6c\uc870\uac00 \uc911\uc694\ud569\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4 spherical wrist\ub97c \uac00\uc9c4 \ub85c\ubd07\uc740 \uc784\uc758\uc758 \uad00\uc808 \ucd95\uc744 \uac00\uc9c4 \ub85c\ubd07\ubcf4\ub2e4 \ud574\uc11d\uc801 \ud574\ub97c \uae54\ub054\ud558\uac8c \uad6c\ud560 \uc218 \uc788\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.\\n\\n\ud575\uc2ec\uc740 \uc804\uccb4 \ubb38\uc81c\ub97c black box\ub85c \ucde8\uae09\ud558\uc9c0 \uc54a\uace0 \ub85c\ubd07\uc758 \uae30\ud558\ub97c \uc774\uc6a9\ud574 \ub9d0\ub2e8 \uc7a5\uce58\ub97c \uc6d0\ud558\ub294 \uc704\uce58\uc640 \ubc29\ud5a5\uc5d0 \ub193\ub294 \uad00\uc808 \ubcc0\uc218\ub97c \uad6c\ud558\ub294 \uac83\uc785\ub2c8\ub2e4.\\n\\n## 3. \ub2e8\uc21c\ud55c \ud3c9\uba74 \ud314\uc758 \ud574\uc11d\uc801 IK\\n\\n\ub9c1\ud06c \uae38\uc774\uac00 $L_1$, $L_2$\uc778 \ud3c9\uba74 2-link arm\uc744 \uc0dd\uac01\ud574 \ubd05\uc2dc\ub2e4. \uc6d0\ud558\ub294 \ub9d0\ub2e8 \uc7a5\uce58 \uc704\uce58\ub294 $(x, y)$\uc785\ub2c8\ub2e4.\\n\\n\ud45c\uc900 \uae30\ud558 \uad00\uacc4\ub294\\n\\n$$\\n x = L_1\\\\cos\\\\theta_1 + L_2\\\\cos(\\\\theta_1 + \\\\theta_2),\\n$$\\n\\n$$\\n y = L_1\\\\sin\\\\theta_1 + L_2\\\\sin(\\\\theta_1 + \\\\theta_2).\\n$$\\n\\n\ubaa9\ud45c \ubc18\uc9c0\ub984\uc744\\n\\n$$\\n r = \\\\sqrt{x^2 + y^2}\\n$$\\n\\n\ub85c \uc815\uc758\ud569\ub2c8\ub2e4.\\n\\n\uadf8\ub7ec\uba74 cosine law\uc5d0\uc11c \ud314\uafc8\uce58 \uac01\ub3c4 \uad00\uacc4\uac00 \ub098\uc635\ub2c8\ub2e4.\\n\\n$$\\n\\\\cos\\\\theta_2 = \\\\frac{x^2 + y^2 - L_1^2 - L_2^2}{2L_1L_2}.\\n$$\\n\\n\ub530\ub77c\uc11c\\n\\n$$\\n\\\\theta_2 = \\\\operatorname{atan2}\\\\left(\\\\pm\\\\sqrt{1 - c^2},\\\\, c\\\\right).\\n$$\\n\\n\ub450 \uac00\uc9c0 \ud314\uafc8\uce58 configuration\uc774 \uac00\ub2a5\ud569\ub2c8\ub2e4.\\n\\n\uadf8\ub2e4\uc74c base angle $\\\\theta_1$\uc740 \ub2e4\uc74c\uacfc \uac19\uc774 \ubcf5\uc6d0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n$$\\n\\\\theta_1 = \\\\operatorname{atan2}(y, x) - \\\\operatorname{atan2}(L_2\\\\sin\\\\theta_2, L_1 + L_2\\\\cos\\\\theta_2).\\n$$\\n\\n\uc774\ub294 2R \ub9e4\ub2c8\ud4f0\ub808\uc774\ud130\uc758 \uace0\uc804\uc801\uc778 \ud574\uc11d\uc801 \ud574\uc785\ub2c8\ub2e4. \uae30\ud558\uac00 \uc800\ucc28\uc6d0\uc774\uace0 \uae30\uad6c\ud559 \uad6c\uc870\uac00 \uc798 \uc54c\ub824\uc838 \uc788\uae30 \ub54c\ubb38\uc5d0 \uac04\ub2e8\ud569\ub2c8\ub2e4.\\n\\n\ub354 \ub113\uc740 \uad00\uc810\uc5d0\uc11c \ubcf4\uba74 \ud574\uc11d\uc801 \ud574\ub294 \uae30\ud558\ub97c \uc9c1\uc811 \ud65c\uc6a9\ud569\ub2c8\ub2e4. \uac00\ub2a5\ud560 \ub54c \uc77c\ubc18 \uc218\uce58 \ubc29\ubc95\ubcf4\ub2e4 \ube60\ub974\uace0 \uc548\uc815\uc801\uc785\ub2c8\ub2e4.\\n\\n## 4. \ud574\uc11d\uc801 \ud574\uac00 \ud56d\uc0c1 \uac00\ub2a5\ud558\uc9c0 \uc54a\uc740 \uc774\uc720\\n\\n\uc77c\ubc18\uc801\uc778 6-DOF \ub9e4\ub2c8\ud4f0\ub808\uc774\ud130\uc5d0\uc11c\ub294 \ud574\uc11d\uc801 \ud574\ub97c \ub2eb\ud78c \ud615\ud0dc\ub85c \uc720\ub3c4\ud558\uae30\uac00 \ub9e4\uc6b0 \uc5b4\ub835\uac70\ub098 \ubd88\uac00\ub2a5\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\nPose \uc81c\uc57d\uc5d0\uc11c \uc0dd\uae30\ub294 \ube44\uc120\ud615 \uc81c\uc57d\uc740 \ub192\uc740 \ucc28\uc218\uc758 \ub2e4\ud56d\uc2dd\uc73c\ub85c \uc774\uc5b4\uc9d1\ub2c8\ub2e4. \uc2dd\uc744 \uc720\ub3c4\ud560 \uc218 \uc788\ub354\ub77c\ub3c4 \uc18c\ud504\ud2b8\uc6e8\uc5b4\uc5d0\uc11c \uc548\uc815\uc801\uc73c\ub85c \uc0ac\uc6a9\ud558\uae30\uc5d0\ub294 \ub108\ubb34 \ubcf5\uc7a1\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\uc774\ub54c \uc218\uce58 \ubc29\ubc95\uc774 \uc911\uc694\ud574\uc9d1\ub2c8\ub2e4.\\n\\n## 5. Jacobian\uc744 \uc0ac\uc6a9\ud55c \ubc18\ubcf5 IK\\n\\nJacobian\uc740 \ubaa9\ud45c pose\ub97c \ud5a5\ud574 \uad00\uc808 \ubcc0\uc218\ub97c \uc870\uae08\uc529 \uac31\uc2e0\ud558\ub294 \uc9c1\uc811\uc801\uc778 \ubc29\ubc95\uc744 \uc81c\uacf5\ud569\ub2c8\ub2e4.\\n\\n\ud604\uc7ac pose\uac00 $T_{se}(\\\\theta)$\uc774\uace0 \ubaa9\ud45c pose\uac00 $T_d$\ub77c\uace0 \ud569\uc2dc\ub2e4. \ub9d0\ub2e8 \uc7a5\uce58 pose\ub97c $T_d$\uc5d0 \uac00\uae5d\uac8c \uc62e\uae30\ub294 \uc791\uc740 \uad00\uc808 \uac31\uc2e0 $\\\\Delta\\\\theta$\ub97c \uad6c\ud558\ub824\uace0 \ud569\ub2c8\ub2e4.\\n\\n\uc77c\ubc18\uc801\uc778 \uc815\uc2dd\ud654\ub294\\n\\n$$\\nJ(\\\\theta)\\\\Delta\\\\theta = \\\\nu_e,\\n$$\\n\\n\uc774\uba70 $\\\\nu_e$\ub294 \ud604\uc7ac pose\uc640 \ubaa9\ud45c pose \uc0ac\uc774\uc758 twist error\uc785\ub2c8\ub2e4.\\n\\n\uadf8\ub2e4\uc74c configuration\uc744\\n\\n$$\\n\\\\theta \\\\leftarrow \\\\theta + \\\\Delta\\\\theta.\\n$$\\n\\n\ub85c \uac31\uc2e0\ud569\ub2c8\ub2e4.\\n\\n\uc774\uac83\uc774 Jacobian \uae30\ubc18 IK\uc758 \ud575\uc2ec\uc785\ub2c8\ub2e4.\\n\\nError twist\ub294 \ud604\uc7ac transform\uacfc \ubaa9\ud45c transform\uc758 \ucc28\uc774\uc5d0\uc11c \uacc4\uc0b0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ubbf8\ubd84 \ud615\uc2dd\uc5d0\uc11c\ub294 pose error\ub97c \uc904\uc774\ub294 \uc18d\ub3c4 \uba85\ub839\uc73c\ub85c \ubaa9\ud45c \uc6b4\ub3d9\uc744 \ud45c\ud604\ud569\ub2c8\ub2e4.\\n\\n\uc774\ub294 \uc9c1\uc811 \ud574\ub97c \uad6c\ud558\ub294 \ub300\uc2e0 \uad6d\uc18c \uc120\ud615\ud654\ub97c \uc0ac\uc6a9\ud574 error\ub97c \ubc18\ubcf5\ud574\uc11c \uc904\uc774\ub294 differential correction \ubc29\ubc95\uc785\ub2c8\ub2e4.\\n\\n## 6. Pseudoinverse \ubc29\ubc95\\n\\nJacobian\uc774 full rank\uc774\uba74 least-squares \uac31\uc2e0\uc740 \ub2e4\uc74c\uacfc \uac19\uc774 \uc4f8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n$$\\n\\\\Delta\\\\theta = J(\\\\theta)^{\\\\dagger} \\\\nu_e.\\n$$\\n\\n\uc774\ub294 \uac00\uc7a5 \ub2e8\uc21c\ud55c \ubc18\ubcf5 IK \uc804\ub7b5\uc785\ub2c8\ub2e4. Pose error\ub97c \uac00\uc7a5 \uc798 \uc904\uc774\ub294 minimum-norm \uac31\uc2e0\uc744 \uacc4\uc0b0\ud569\ub2c8\ub2e4.\\n\\n\ub85c\ubd07\uc774 redundant\ud558\uba74 nullspace \ud56d\ub3c4 \ud3ec\ud568\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n$$\\n\\\\Delta\\\\theta = J^{\\\\dagger}\\\\nu_e + \\\\left(I - J^{\\\\dagger}J\\\\right)\\\\Delta\\\\theta_0.\\n$$\\n\\n\uc774\ub97c \uc0ac\uc6a9\ud558\uba74 \ubaa9\ud45c pose\ub97c \ub9cc\uc871\ud558\uba74\uc11c solver\ub97c \uc120\ud638\ud558\ub294 \uad00\uc808 configuration\uc73c\ub85c \uc720\ub3c4\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\nIK\uc5d0\ub294 \ud574\uac00 \ubb34\ud55c\ud788 \ub9ce\uc744 \ub54c\uac00 \ub9ce\uc73c\ubbc0\ub85c \uc720\uc6a9\ud569\ub2c8\ub2e4. Solver\ub294 \uad00\uc808 \uc81c\ud55c\uc744 \ud53c\ud558\uac70\ub098 singularity\uc5d0\uc11c \uba40\ub9ac \uc788\ub294 \uac83\ucc98\ub7fc \ubb3c\ub9ac\uc801\uc73c\ub85c \ubc14\ub78c\uc9c1\ud55c \ud574\ub97c \uc120\ud0dd\ud574\uc57c \ud569\ub2c8\ub2e4.\\n\\n## 7. Damped least-squares\uc640 regularization\\n\\nSingularity \uadfc\ucc98\uc5d0\uc11c\ub294 pseudoinverse \ud574\uac00 \ubd88\uc548\uc815\ud574\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ud754\ud55c \ud574\uacb0\ucc45\uc740 damped least-squares \uac31\uc2e0\uc785\ub2c8\ub2e4.\\n\\n$$\\n\\\\Delta\\\\theta = J^T(JJ^T + \\\\lambda^2 I)^{-1}\\\\nu_e,\\n$$\\n\\n\uc5ec\uae30\uc11c $\\\\lambda > 0$\ub294 damping parameter\uc785\ub2c8\ub2e4.\\n\\n\uc774\ub294 regularization\ucc98\ub7fc \uc791\ub3d9\ud569\ub2c8\ub2e4. Jacobian\uc758 conditioning\uc774 \ub098\uc060 \ub54c \uac31\uc2e0\ub7c9\uc774 \ud3ed\ubc1c\ud558\ub294 \uac83\uc744 \ub9c9\uc2b5\ub2c8\ub2e4.\\n\\n\uc774\ub294 \uc218\uce58 IK\uc5d0\uc11c \ud2b9\ud788 \uc911\uc694\ud569\ub2c8\ub2e4. \ubaa9\ud45c\uac00 singular configuration\uc5d0 \uac00\uae4c\uc6cc\uc9c0\uba74 solver\uac00 \ub9e4\uc6b0 \ud070 \uad00\uc808 \uc6b4\ub3d9\uc744 \ub9cc\ub4e4\uac70\ub098 \uc218\ub834\ud558\uc9c0 \ubabb\ud560 \uc218 \uc788\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.\\n\\n## 8. Newton-Raphson \ubc29\uc2dd\uc758 IK\\n\\n\ub610 \ub2e4\ub978 \ubc29\ubc95\uc740 pose \uc790\uccb4\uc758 error\ub97c \ubc18\ubcf5\ud574 \uc5ed\uae30\uad6c\ud559\uc744 \ud478\ub294 \uac83\uc785\ub2c8\ub2e4.\\n\\n$$\\nF(\\\\theta) = T_{se}(\\\\theta)^{-1}T_d.\\n$$\\n\\n$F(\\\\theta)$\ub97c identity transform\uc73c\ub85c \ub9cc\ub4e4\uace0\uc790 \ud569\ub2c8\ub2e4. \uc120\ud615\ud654\ud558\uba74\\n\\n$$\\n\\\\delta\\\\theta \\\\approx J^{-1}(\\\\theta) \\\\xi,\\n$$\\n\\n\uc774\uba70 $\\\\xi$\ub294 residual error\uc5d0 \ub300\uc751\ud558\ub294 twist\uc785\ub2c8\ub2e4.\\n\\n\uadf8\ub2e4\uc74c \uac31\uc2e0\uc740\\n\\n$$\\n\\\\theta_{k+1} = \\\\theta_k + \\\\Delta\\\\theta_k.\\n$$\\n\\n\uc785\ub2c8\ub2e4.\\n\\n\uc774\ub294 rigid motion\uc758 manifold \uc704\uc5d0\uc11c \uc218\ud589\ud558\ub294 Newton \ubc29\uc2dd \uac31\uc2e0\uc785\ub2c8\ub2e4. \uac15\ub825\ud558\uc9c0\ub9cc \ucd08\uae30 \uc870\uac74\uacfc singularity \uadfc\ucc98\uc758 \uc0c1\ud0dc\uc5d0 \ubbfc\uac10\ud569\ub2c8\ub2e4.\\n\\n\uc2e4\uc81c\ub85c\ub294 \uc548\uc815\uc131\uc744 \uc704\ud574 damping, line search \ub610\ub294 trust-region \ubc29\ubc95\uc744 \ud568\uaed8 \uc0ac\uc6a9\ud558\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.\\n\\n## 9. Initial guess\uc758 \uc5ed\ud560\\n\\n\uc218\uce58 IK\ub294 \ucd08\uae30 configuration\uc5d0 \ud06c\uac8c \uc758\uc874\ud569\ub2c8\ub2e4.\\n\\n\ucd08\uae30 \ucd94\uc815\uc774 \ubaa9\ud45c\uc5d0 \uac00\uae4c\uc6b0\uba74 \ube60\ub974\uace0 \uc548\uc815\uc801\uc73c\ub85c \uc218\ub834\ud569\ub2c8\ub2e4. \uba40\ub9ac \uc788\uc73c\uba74 \ub2e4\ub978 branch\ub85c \uc218\ub834\ud558\uac70\ub098 \uc544\uc608 \uc2e4\ud328\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\uc54c\ub824\uc9c4 \ub85c\ubd07 \uc885\ub958\uc5d0\uc11c\ub294 \ud574\uc11d\uc801 \ubc29\ubc95\uc744 \uc120\ud638\ud558\ub294 \uc774\uc720\uac00 \uc5ec\uae30\uc5d0 \uc788\uc2b5\ub2c8\ub2e4. \uc6b4 \uc88b\uc740 \ucd08\uae30 \ucd94\uc815\uc5d0 \uc758\uc874\ud558\uc9c0 \uc54a\uace0 \uc720\ud6a8\ud55c \ud574\ub97c \uc9c1\uc811 \ub9cc\ub4e4\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.\\n\\n\ud558\uc9c0\ub9cc \uc218\uce58 \ubc29\ubc95\uc740 \ub354 \uc77c\ubc18\uc801\uc774\uba70 closed-form \uacf5\uc2dd\uc774 \ubcf5\uc7a1\ud558\uac70\ub098 \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294 \ub85c\ubd07\ub3c4 \ub2e4\ub8f0 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n## 10. Multiple solution\uc758 \uc5b4\ub824\uc6c0\\n\\nInverse kinematics\uc5d0\ub294 \uac19\uc740 \ub9d0\ub2e8 \uc7a5\uce58 pose\uc5d0 \ub300\ud574 \uc720\ud6a8\ud55c \uad00\uc808 configuration\uc774 \uc5ec\ub7ec \uac1c \uc788\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.\\n\\n\uc608\ub97c \ub4e4\uc5b4 \ud3c9\uba74 2R arm\uc5d0\ub294 elbow-up\uacfc elbow-down\uc774\ub77c\ub294 \ub450 \ud574\uac00 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. 6-DOF \ub9e4\ub2c8\ud4f0\ub808\uc774\ud130\uc5d0\ub3c4 \uc11c\ub85c \ub2e4\ub978 wrist \ubc29\ud5a5\uc774\ub098 elbow \uc790\uc138\uc5d0 \ub300\uc751\ud558\ub294 \uc5ec\ub7ec branch\uac00 \uc788\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\uc774\ub294 \uc815\uc2dd\ud654\uc758 \uacb0\ud568\uc774 \uc544\ub2c8\ub77c \uae30\ud558\uc758 \uc131\uc9c8\uc785\ub2c8\ub2e4. \ucd94\uac00 \uae30\uc900\uc774 \uc5c6\uc73c\uba74 pose \uc81c\uc57d\ub9cc\uc73c\ub85c \uc720\uc77c\ud55c configuration\uc744 \uace0\ub97c \uc218 \uc5c6\uc2b5\ub2c8\ub2e4.\\n\\n\uc77c\ubc18\uc801\uc778 \uae30\uc900\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.\\n\\n- \uc774\uc804 configuration\uc5d0\uc11c \uad00\uc808 \ubcc0\uc704\ub97c \ucd5c\uc18c\ud654\ud558\uae30,\\n- \uad00\uc808 \uc81c\ud55c \ud53c\ud558\uae30,\\n- \uc7a5\uc560\ubb3c\uacfc\uc758 \uac70\ub9ac \ucd5c\ub300\ud654\ud558\uae30,\\n- \ud2b9\uc815 elbow \uc790\uc138\ub098 wrist \ubc29\ud5a5 \uc120\ud638\ud558\uae30\uc785\ub2c8\ub2e4.\\n\\n\uadf8\ub798\uc11c \uc5ed\uae30\uad6c\ud559\uc740 optimization \ub610\ub294 task-priority control\uacfc \ud568\uaed8 \uc0ac\uc6a9\ud558\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.\\n\\n## 11. IK\uc5d0\uc11c control\uacfc planning\uc73c\ub85c\\n\\nInverse kinematics\ub294 \uace0\ub9bd\ub41c \uad6c\uc131 \uc694\uc18c\uac00 \uc544\ub2d9\ub2c8\ub2e4. \uae30\ud558\uc640 \uc81c\uc5b4\uac00 \ub9cc\ub098\ub294 \uc9c0\uc810\uc785\ub2c8\ub2e4.\\n\\n\uc2e4\ud604 \uac00\ub2a5\ud55c pose-to-configuration \uc0ac\uc0c1\uc744 \uacc4\uc0b0\ud560 \uc218 \uc788\uc73c\uba74 \ub2e4\uc74c\uc744 \ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n- trajectory \uc0dd\uc131,\\n- \uc6d0\ud558\ub294 tool path \ucd94\uc801,\\n- \uc7a5\uc560\ubb3c \ud68c\ud53c,\\n- \uae30\uad6c\ud559 \uc81c\uc57d\uc744 \uc9c0\ud0a4\ub294 controller \uad6c\uc131\uc785\ub2c8\ub2e4.\\n\\n\uc5ec\uae30\uc11c Jacobian\uc740 \ubc18\ubcf5 \ud574\ubc95\uc5d0 \ud544\uc694\ud55c \uad6d\uc18c \uc120\ud615\ud654\ub97c \uc81c\uacf5\ud558\uace0, \uc804\uccb4 pose map\uc740 \ub3c4\ub2ec\ud574\uc57c \ud560 \ubaa9\ud45c\ub97c \uc815\uc758\ud558\uae30 \ub54c\ubb38\uc5d0 \uc911\uc2ec\uc801\uc778 \uc5ed\ud560\uc744 \ud569\ub2c8\ub2e4.\\n\\nModern Robotics \uad00\uc810\uc774 \ud6a8\uacfc\uc801\uc778 \uc774\uc720\ub3c4 \uc5ec\uae30\uc5d0 \uc788\uc2b5\ub2c8\ub2e4. \uae30\uad6c\ud559, \uc6b4\ub3d9 \uc0dd\uc131, \uc81c\uc5b4 \uc804\ubc18\uc5d0 \uacf5\ud1b5\ub41c \uc218\ud559 \uc5b8\uc5b4\ub97c \uc81c\uacf5\ud558\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.\\n\\n## 12. \uc694\uc57d\\n\\n\uc5ed\uae30\uad6c\ud559 \ubb38\uc81c\ub294 \uadfc\ubcf8\uc801\uc73c\ub85c \ub2e4\uc74c \ube44\uc120\ud615 \uc2dc\uc2a4\ud15c\uc744 \ud478\ub294 \uc77c\uc785\ub2c8\ub2e4.\\n\\n$$\\nT_{se}(\\\\theta) = T_d.\\n$$\\n\\n\ud06c\uac8c \ub450 \uac00\uc9c0 \ubc29\ubc95\uc774 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n1. \uae30\uad6c\uc758 \uad6c\uc870\ub97c \uc0ac\uc6a9\ud558\ub294 \ud574\uc11d\uc801 \ubc29\ubc95,\\n2. Jacobian \uae30\ubc18 \ubc18\ubcf5 \uac31\uc2e0\uc744 \uc0ac\uc6a9\ud558\ub294 \uc218\uce58 \ubc29\ubc95\uc785\ub2c8\ub2e4.\\n\\nJacobian \uae30\ubc18 \uac31\uc2e0\uc740\\n\\n$$\\nJ(\\\\theta)\\\\Delta\\\\theta = \\\\nu_e,\\n$$\\n\\n\uc774\uba70 \uc5ed\ud589\ub82c\uc744 \uc9c1\uc811 \uc0ac\uc6a9\ud560 \uc218 \uc5c6\uc744 \ub54c\ub294\\n\\n$$\\n\\\\Delta\\\\theta = J^{\\\\dagger}\\\\nu_e\\n$$\\n\\n\ub610\ub294 solver\ub97c \uc548\uc815\ud654\ud558\ub294 damping \ubc84\uc804\uc744 \uc0ac\uc6a9\ud569\ub2c8\ub2e4.\\n\\n\uc774\ub294 \uc55e\uc120 \uae00\uc5d0\uc11c \ubc1c\uc804\uc2dc\ud0a8 \uc804\uccb4 \uc774\ub860\uc774 \uc5b4\ub5bb\uac8c \uacb0\ud569\ub418\ub294\uc9c0 \ubcf4\uc5ec \uc90d\ub2c8\ub2e4. \ub9e4\ub2c8\ud4f0\ub808\uc774\ud130\uc758 \uae30\ud558\ub294 screw axis\uc5d0 \ub2f4\uae30\uace0, \uc774\ub97c \ubbf8\ubd84\ud574 Jacobian\uc744 \uc5bb\uc73c\uba70, \uadf8 Jacobian\uc73c\ub85c pose \uc2e4\ud604 \ubb38\uc81c\ub97c \ud489\ub2c8\ub2e4.\\n\\n\uc774\uac83\uc774 Modern Robotics\uc758 \uc9c4\uc815\ud55c \ud6a8\uc6a9\uc785\ub2c8\ub2e4."},{"id":"modern-robotics-part-6","metadata":{"permalink":"/ko/blog/modern-robotics-part-6","editUrl":"https://github.com/CMaybe/cmaybe.github.io/tree/main/blog/2026-09-07-modern-robotics-part-6a.md","source":"@site/i18n/ko/docusaurus-plugin-content-blog/2026-09-07-modern-robotics-part-6a.md","title":"Modern Robotics, Part 6A \u2014 \ub3d9\uc5ed\ud559, \uc81c\uc5b4, \uadf8\ub9ac\uace0 \uc6b4\ub3d9 \uc0dd\uc131","description":"\uae30\uad6c\ud559, twist \uae30\ubc18 \uc6b4\ub3d9 \uc0dd\uc131, \ub3d9\uc5ed\ud559\uc744 task-space control\uacfc \ub85c\ubd07 \uc6b4\ub3d9 \uc0dd\uc131\uc73c\ub85c \uc5f0\uacb0\ud574 \uc790\uc138\ud788 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.","date":"2026-09-07T00:00:00.000Z","tags":[{"inline":false,"label":"Robotics","permalink":"/ko/blog/tags/robotics","description":"Robot software, systems, and experiments."},{"inline":false,"label":"Modern Robotics","permalink":"/ko/blog/tags/modern-robotics","description":"Concepts, methods, and intuition behind rigid-body motion and robot kinematics."},{"inline":false,"label":"Kinematics","permalink":"/ko/blog/tags/kinematics","description":"Forward and inverse kinematics for robots."},{"inline":false,"label":"Motion Planning","permalink":"/ko/blog/tags/motion-planning","description":"Algorithms for finding feasible robot motion."}],"readingTime":6.1,"hasTruncateMarker":true,"authors":[{"name":"Jaegyeom Kim","title":"Robotics Software Engineer","url":"https://github.com/CMaybe","page":{"permalink":"/ko/blog/authors/endi"},"socials":{"github":"https://github.com/CMaybe","linkedin":"https://www.linkedin.com/in/Jaegyeom-kim-185b8a2a4/"},"imageURL":"https://github.com/CMaybe.png","key":"endi"}],"frontMatter":{"slug":"modern-robotics-part-6","title":"Modern Robotics, Part 6A \u2014 \ub3d9\uc5ed\ud559, \uc81c\uc5b4, \uadf8\ub9ac\uace0 \uc6b4\ub3d9 \uc0dd\uc131","authors":["endi"],"tags":["robotics","modern-robotics","kinematics","motion-planning"],"description":"\uae30\uad6c\ud559, twist \uae30\ubc18 \uc6b4\ub3d9 \uc0dd\uc131, \ub3d9\uc5ed\ud559\uc744 task-space control\uacfc \ub85c\ubd07 \uc6b4\ub3d9 \uc0dd\uc131\uc73c\ub85c \uc5f0\uacb0\ud574 \uc790\uc138\ud788 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4."},"unlisted":false,"prevItem":{"title":"Modern Robotics, Part 5 \u2014 \uc5ed\uae30\uad6c\ud559\uacfc \uc218\uce58 \ud574\ubc95","permalink":"/ko/blog/modern-robotics-part-5"},"nextItem":{"title":"Modern Robotics, Part 6B \u2014 Trajectory, \uc81c\uc57d, \uadf8\ub9ac\uace0 Motion Planning","permalink":"/ko/blog/modern-robotics-part-6b"}},"content":"\uc55e\uc120 \uae00\uc5d0\uc11c\ub294 twist, screw axis, Jacobian, inverse kinematics\ub97c \uc0ac\uc6a9\ud574 \ub85c\ubd07\uc744 \uae30\uad6c\ud559\uc801\uc73c\ub85c \ubc14\ub77c\ubcf4\ub294 \uad00\uc810\uc744 \ubc1c\uc804\uc2dc\ucf30\uc2b5\ub2c8\ub2e4. \uc774\uc81c \ub85c\ubd07 \uc6b4\ub3d9\uc774 \uc5b4\ub5bb\uac8c \uc0dd\uc131\ub418\ub294\uc9c0\uc5d0 \ub300\ud55c \uac15\ud55c \uae30\ud558\ud559\uc801 \uc774\ud574\ub97c \uac16\uac8c \ub418\uc5c8\uc2b5\ub2c8\ub2e4.\\n\\n\ub2e4\uc74c \ub2e8\uacc4\ub294 \uc774 \uc774\ud574\ub97c \ub3d9\uc5ed\ud559\uacfc planning\uc758 \ub9e5\ub77d\uc5d0 \ub193\ub294 \uac83\uc785\ub2c8\ub2e4.\\n\\n\ub85c\ubd07\uc740 \ubaa9\ud45c pose\uc5d0 \ub3c4\ub2ec\ud558\uae30\ub9cc \ud558\uba74 \ub418\ub294 \uac83\uc774 \uc544\ub2d9\ub2c8\ub2e4. \ubd80\ub4dc\ub7fd\uac8c \uc6c0\uc9c1\uc774\uace0, trajectory\ub97c \ucd94\uc801\ud558\uace0, \uc81c\uc57d\uc744 \ub9cc\uc871\ud558\uba70, \uc2dc\uc2a4\ud15c\uc758 \ubb3c\ub9ac \ubc95\uce59\uc744 \uc874\uc911\ud558\ub294 control signal\ub85c \uc6c0\uc9c1\uc5ec\uc57c \ud569\ub2c8\ub2e4.\\n\\n\uc774\uac83\uc774 dynamics\uc640 motion planning\uc758 \uc601\uc5ed\uc785\ub2c8\ub2e4.\\n\\n\x3c!-- truncate --\x3e\\n\\n## 1. \uae30\uad6c\ud559\ub9cc\uc73c\ub85c\ub294 \ucda9\ubd84\ud558\uc9c0 \uc54a\ub2e4\\n\\n\uae30\uad6c\ud559\uc740 \uad00\uc808 \ubcc0\uc218\uc5d0 \ub530\ub77c \ub85c\ubd07 pose\uac00 \uc5b4\ub5bb\uac8c \ubcc0\ud558\ub294\uc9c0 \uc54c\ub824 \uc90d\ub2c8\ub2e4. \ud558\uc9c0\ub9cc control\uacfc planning\uc5d0\ub294 \ud798\uacfc \ud1a0\ud06c\uac00 \uc6b4\ub3d9\uc744 \ub9cc\ub4dc\ub294 \ubc29\uc2dd\uc5d0 \ub300\ud55c \uc9c0\uc2dd\ub3c4 \ud544\uc694\ud569\ub2c8\ub2e4.\\n\\n\uc790\uc5f0\uc2a4\ub7ec\uc6b4 \uc21c\uc11c\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.\\n\\n1. \ub9d0\ub2e8 \uc7a5\uce58\uc758 \uc704\uce58\uc640 \ubc29\ud5a5\uc744 transformation\uc73c\ub85c \ud45c\ud604\ud569\ub2c8\ub2e4.\\n2. \uc21c\uac04 \uc6b4\ub3d9\uc744 twist\ub85c \ud45c\ud604\ud569\ub2c8\ub2e4.\\n3. Jacobian\uc740 \uad00\uc808 \uc18d\ub3c4\ub97c task-space \uc18d\ub3c4\ub85c \ubcc0\ud658\ud569\ub2c8\ub2e4.\\n4. \ub3d9\uc5ed\ud559\uc740 \ud798\uacfc \ud1a0\ud06c\uac00 \uad00\uc808 \uac00\uc18d\ub3c4\ub97c \ub9cc\ub4dc\ub294 \ubc29\uc2dd\uc744 \uc124\uba85\ud569\ub2c8\ub2e4.\\n5. Planning\uc740 \uc2e4\ud604 \uac00\ub2a5\ud558\uace0 \ubd80\ub4dc\ub7ec\uc6b0\uba70 collision-free\ud55c trajectory\ub97c \uc0dd\uc131\ud569\ub2c8\ub2e4.\\n\\n\uc774\uac83\uc774 \ud604\ub300 \ub85c\ubd07\uacf5\ud559\uc758 pipeline\uc785\ub2c8\ub2e4.\\n\\n## 2. \ub85c\ubd07\uc740 \uc81c\uc57d\ub41c \uae30\uacc4 \uc2dc\uc2a4\ud15c\uc774\ub2e4\\n\\n\ub9e4\ub2c8\ud4f0\ub808\uc774\ud130 \ub3d9\uc5ed\ud559\uc740 \ud754\ud788 \ub2e4\uc74c \ud45c\uc900 \ud615\ud0dc\ub85c \uc501\ub2c8\ub2e4.\\n\\n$$\\nM(\\\\theta)\\\\ddot{\\\\theta} + C(\\\\theta, \\\\dot{\\\\theta})\\\\dot{\\\\theta} + g(\\\\theta) = \\\\tau,\\n$$\\n\\n\uc5ec\uae30\uc11c\\n\\n- $M(\\\\theta)$\ub294 inertia matrix\uc785\ub2c8\ub2e4.\\n- $C(\\\\theta, \\\\dot{\\\\theta})\\\\dot{\\\\theta}$\ub294 Coriolis\uc640 centrifugal \ud6a8\uacfc\ub97c \ub098\ud0c0\ub0c5\ub2c8\ub2e4.\\n- $g(\\\\theta)$\ub294 gravity \ud56d\uc785\ub2c8\ub2e4.\\n- $\\\\tau$\ub294 joint torque vector\uc785\ub2c8\ub2e4.\\n\\n\uc774 \uc2dd\uc740 \uc778\uac00\ud55c torque\uc758 \ud6a8\uacfc\uac00 inertia, geometry, gravity\uc5d0 \uc758\ud574 \ub9e4\uac1c\ub41c\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4. \uae30\uad6c\ud559 map\uc744 \ubcf4\uc644\ud558\ub294 \ub3d9\uc5ed\ud559\uc801 \ud45c\ud604\uc785\ub2c8\ub2e4.\\n\\nMotion planning \uad00\uc810\uc5d0\uc11c \uc911\uc694\ud55c \uc810\uc740 \ub85c\ubd07\uc774 \uc784\uc758\ub85c \uac00\uc18d\ud560 \uc218 \uc5c6\ub2e4\ub294 \uac83\uc785\ub2c8\ub2e4. Joint-space \ub3d9\uc5ed\ud559\uc740 \ub85c\ubd07\uc774 \uc5bc\ub9c8\ub098 \ube60\ub974\uace0 \uae09\uaca9\ud558\uac8c \uc6c0\uc9c1\uc77c \uc218 \uc788\ub294\uc9c0\uc5d0 \uc81c\uc57d\uc744 \ub461\ub2c8\ub2e4.\\n\\n## 3. Jacobian\uc758 \ub3d9\uc5ed\ud559\uc801 \uc5ed\ud560\\n\\nJacobian\uc740 joint-space \uc6b4\ub3d9\uacfc task-space \uc6b4\ub3d9\uc744 \uc5f0\uacb0\ud558\uba70, \uac19\uc740 \uad6c\uc870\uac00 \ub3d9\uc5ed\ud559\uc5d0\uc11c\ub3c4 \ub098\ud0c0\ub0a9\ub2c8\ub2e4.\\n\\nTask-space force \ub610\ub294 wrench $F$\ub294 transpose Jacobian\uc744 \ud1b5\ud574 joint torque\uc640 \uc5f0\uacb0\ub429\ub2c8\ub2e4.\\n\\n$$\\n\\\\tau = J(\\\\theta)^T F.\\n$$\\n\\n\uc774 \uad00\uacc4\ub294 \uae30\ubcf8\uc801\uc785\ub2c8\ub2e4. \ub9d0\ub2e8 \uc7a5\uce58\uc5d0 \uac00\ud574\uc9c4 wrench\uac00 \ub9e4\ub2c8\ud4f0\ub808\uc774\ud130\uc758 \uae30\ud558\uc5d0 \ub530\ub77c equivalent joint torque\ub85c \ubc14\ub010\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4.\\n\\n\uc774\ub294 \uae30\uad6c\ud559\uacfc \ub3d9\uc5ed\ud559\uc744 \uc787\ub294 \ud575\uc2ec \uc5f0\uacb0\uc785\ub2c8\ub2e4. Jacobian\uc740 task-space force\uac00 joint-space torque\ub85c \ubc14\ub00c\ub294 \ubc29\uc2dd\uacfc \ub85c\ubd07\uc774 \ud658\uacbd\uc758 \uc6b4\ub3d9\uc744 \uc800\ud56d\ud558\uac70\ub098 \ub9cc\ub4e4\uc5b4 \ub0b4\ub294 \ubc29\uc2dd\uc744 \uacb0\uc815\ud569\ub2c8\ub2e4.\\n\\n## 4. Task-space dynamics\\n\\n\uac19\uc740 \ub17c\ub9ac\ub97c task space\uc5d0\uc11c \ud45c\ud604\ud560 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. Kinetic \uad00\uacc4\ub294 \ub2e4\uc74c\uacfc \uac19\uc774 \uc4f8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n$$\\n\\\\Lambda(\\\\theta)\\\\dot{\\\\nu} + \\\\mu(\\\\theta, \\\\dot{\\\\theta}) + p(\\\\theta) = F,\\n$$\\n\\n\uc5ec\uae30\uc11c $\\\\Lambda$\ub294 task-space inertia matrix\uc774\uace0, $\\\\mu$\ub294 \uc18d\ub3c4 \uc758\uc874 \ud56d\uc744 \ubaa8\uc73c\uba70, $p$\ub294 gravity \uad00\ub828 wrench\uc785\ub2c8\ub2e4.\\n\\n\uc774 \uc815\uc2dd\ud654\ub294 \uc6d0\ud558\ub294 \uc6b4\ub3d9\uc774 \uc790\uc5f0\uc2a4\ub7fd\uac8c task space\uc5d0\uc11c \uc9c0\uc815\ub418\ub294 operational-space control\uc5d0 \uc720\uc6a9\ud569\ub2c8\ub2e4.\\n\\n\uae30\ubcf8 \uc544\uc774\ub514\uc5b4\ub294 \uc55e\uacfc \uac19\uc2b5\ub2c8\ub2e4. Task-space \uba85\ub839\uc740 Jacobian\uacfc \ub3d9\uc5ed\ud559 \ubaa8\ub378\uc744 \ud1b5\ud574 joint-space actuation\uc73c\ub85c \ubc14\ub01d\ub2c8\ub2e4.\\n\\n## 5. Trajectory generation: \uc810\uc5d0\uc11c \ubd80\ub4dc\ub7ec\uc6b4 \uc6b4\ub3d9\uc73c\ub85c\\n\\n\ubaa9\ud45c pose\ub97c \uc54c\uac8c \ub418\uba74 \ub85c\ubd07\uc740 \uc2dc\uac04\uc5d0 \ub530\ub978 \uc2e4\ud604 \uac00\ub2a5\ud55c \uc6b4\ub3d9\uc744 \ub530\ub77c\uc57c \ud569\ub2c8\ub2e4. \uc774\uac83\uc774 trajectory generation \ubb38\uc81c\uc785\ub2c8\ub2e4.\\n\\nTrajectory\ub294 pose\uc758 \ubaa9\ub85d\uc774 \uc544\ub2c8\ub77c smoothness, velocity limit, acceleration limit\ub97c \ud3ec\ud568\ud558\ub294 \uc2dc\uac04 \ub9e4\uac1c\ud654 \uacbd\ub85c\uc785\ub2c8\ub2e4.\\n\\n\ud754\ud55c \uc120\ud0dd\uc740 polynomial trajectory\uc785\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4 cubic polynomial\uc740 \uacbd\uacc4 \uc870\uac74\uc744 \ub9cc\uc871\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n$$\\nq(t) = a_0 + a_1 t + a_2 t^2 + a_3 t^3.\\n$$\\n\\n\uacc4\uc218\ub294 \ucd08\uae30\uc640 \ucd5c\uc885 position \ubc0f velocity\ub85c \uc815\ud569\ub2c8\ub2e4.\\n\\n\ub354 \ub192\uc740 smoothness\uac00 \ud544\uc694\ud558\uba74 quintic polynomial\uc744 \uc0ac\uc6a9\ud569\ub2c8\ub2e4.\\n\\n$$\\nq(t) = a_0 + a_1 t + a_2 t^2 + a_3 t^3 + a_4 t^4 + a_5 t^5.\\n$$\\n\\n\uc774\ub97c \uc0ac\uc6a9\ud558\uba74 \uc591 \ub05d\uc810\uc5d0\uc11c position, velocity, acceleration\uc744 \ub9cc\uc871\uc2dc\ud0ac \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\uc774\ub294 \ub85c\ubd07\uc774 pose target \uc0ac\uc774\ub97c \uac11\uc790\uae30 \uc774\ub3d9\ud558\uc9c0 \uc54a\uc544\uc57c \ud558\uae30 \ub54c\ubb38\uc5d0 \uc911\uc694\ud569\ub2c8\ub2e4. \ubd80\ub4dc\ub7ec\uc6b4 \uc6c0\uc9c1\uc784\uc740 \ub9c8\ubaa8, \uc9c4\ub3d9, \ubd88\uc548\uc815\uc131\uc744 \uc904\uc785\ub2c8\ub2e4.\\n\\n## 6. Time parametrization\uacfc \uc6b4\ub3d9 \uc81c\uc57d\\n\\n\uacbd\ub85c\ub9cc\uc73c\ub85c\ub294 \ucda9\ubd84\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \ub85c\ubd07\uc740 \uc2dc\uac04\uc5d0 \ub530\ub978 \uc81c\ud55c\ub3c4 \uc9c0\ucf1c\uc57c \ud569\ub2c8\ub2e4.\\n\\n\uacbd\ub85c\ub97c arc length $s$\ub85c \ub9e4\uac1c\ud654\ud588\ub2e4\uba74 timing law $s(t)$\ub97c \uc815\uc758\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\uacbd\ub85c\ub97c \ub530\ub978 \uc804\uccb4 \uc18d\ub3c4\ub294\\n\\n$$\\n\\\\dot{q}(t) = \\\\frac{dq}{ds}\\\\dot{s}(t).\\n$$\\n\\n\ub9c8\ucc2c\uac00\uc9c0\ub85c\\n\\n$$\\n\\\\ddot{q}(t) = \\\\frac{d^2 q}{ds^2}\\\\dot{s}^2 + \\\\frac{dq}{ds}\\\\ddot{s}.\\n$$\\n\\n\uc785\ub2c8\ub2e4.\\n\\n\uc774\ub294 \uc77c\ubc18\uc801\uc778 planning \uc6d0\ub9ac\ub97c \ubcf4\uc5ec \uc90d\ub2c8\ub2e4. \uacbd\ub85c\uc758 \uae30\ud558\uc640 time scaling\uc740 \uc11c\ub85c \ubd84\ub9ac\ub41c \uc124\uacc4 \uc120\ud0dd\uc774\uba70 \ub458 \ub2e4 \uc2e4\ud604 \uac00\ub2a5\uc131\uc5d0 \uc601\ud5a5\uc744 \uc90d\ub2c8\ub2e4.\\n\\nTrajectory\uac00 \ub108\ubb34 \ube60\ub974\uba74 actuator limit\ub098 dynamic constraint\ub97c \uc704\ubc18\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub108\ubb34 \ub290\ub9ac\uba74 \ube44\ud604\uc2e4\uc801\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4. Planning\uc740 \uc2e4\ud604 \uac00\ub2a5\uc131\uacfc \ud6a8\uc728 \uc0ac\uc774\uc758 \uade0\ud615\uc744 \ucc3e\uc2b5\ub2c8\ub2e4.\\n\\n## 7. Motion planning\uc758 \uc5ed\ud560\\n\\nMotion planning\uc740 \uc81c\uc57d\uc744 \uc9c0\ud0a4\uba74\uc11c \ucd08\uae30 configuration\uc5d0\uc11c \ubaa9\ud45c configuration\uc73c\ub85c \uac00\ub294 \uc2e4\ud604 \uac00\ub2a5\ud55c \uacbd\ub85c\ub97c \ucc3e\ub294 \ubb38\uc81c\uc785\ub2c8\ub2e4.\\n\\n\ubcf4\ud1b5 \ub2e4\uc74c\uc744 \uace0\ub824\ud569\ub2c8\ub2e4.\\n\\n- obstacle avoidance,\\n- joint limit,\\n- velocity\uc640 acceleration limit,\\n- collision constraint,\\n- dynamic feasibility\uc785\ub2c8\ub2e4.\\n\\n\ub113\uc740 \uc758\ubbf8\uc5d0\uc11c motion planning \ubc29\ubc95\uc740 \ub2e4\uc74c \uba87 \uc885\ub958\ub85c \ub098\ub269\ub2c8\ub2e4.\\n\\n- graph-based planning,\\n- sampling-based planning,\\n- optimization-based planning,\\n- reactive control \uc811\uadfc\ubc95\uc785\ub2c8\ub2e4.\\n\\nPRM\uacfc RRT \uac19\uc740 sampling-based \ubc29\ubc95\uc740 \uc815\ud655\ud55c \uae30\ud558\ud559\uc801 planning\uc774 \uc5b4\ub824\uc6b4 \uace0\ucc28\uc6d0 \uacf5\uac04\uc5d0\uc11c \ud2b9\ud788 \uc911\uc694\ud569\ub2c8\ub2e4.\\n\\n\ud575\uc2ec\uc740 \uc5b8\uc81c\ub098 \uac19\uc2b5\ub2c8\ub2e4. Geometry\uc640 constraint\uc5d0 \ub300\ud55c feasibility\ub97c \uc720\uc9c0\ud558\uba74\uc11c configuration space\ub97c \ud0d0\uc0c9\ud569\ub2c8\ub2e4.\\n\\n## 8. Collision avoidance\uc640 configuration space\\n\\nMotion planning\uc758 \uac00\uc7a5 \uae4a\uc740 \uac1c\ub150 \uc911 \ud558\ub098\uac00 configuration space\uc785\ub2c8\ub2e4.\\n\\nConfiguration space\ub294 \ubaa8\ub4e0 \ub85c\ubd07 joint configuration\uc758 \uc9d1\ud569\uc785\ub2c8\ub2e4. Configuration\uc740 \uc7a5\uc560\ubb3c\uacfc \ucda9\ub3cc\ud558\uc9c0 \uc54a\uace0 joint limit\ub97c \ub9cc\uc871\ud558\uba74 \uc720\ud6a8\ud569\ub2c8\ub2e4.\\n\\n\uc774\ub97c \ud1b5\ud574 \uae30\ud558\ud559\uc801 \uc7a5\uc560\ubb3c \ubb38\uc81c\ub97c state-space planning \ubb38\uc81c\ub85c \ubc14\uafc0 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\ub85c\ubd07\uc774 $n$\uac1c\uc758 \uad00\uc808\uc744 \uac00\uc9c0\uba74 configuration space\ub294 \ubcf4\ud1b5 \uace0\ucc28\uc6d0\uc785\ub2c8\ub2e4. \uc774\ub97c \uc9c1\uc811 \ud0d0\uc0c9\ud558\ub294 \uc77c\uc740 \ube44\uc2f8\uae30 \ub54c\ubb38\uc5d0 planning\uc740 sampling, heuristic, \ub610\ub294 task decomposition\uc744 \uc0ac\uc6a9\ud558\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.\\n\\n\uc5ec\uae30\uc11c \uae30\uad6c\ud559\uacfc task-space \uc9c1\uad00\uc774 \uc2e4\uc81c \uc2dc\uc2a4\ud15c\uc758 feasibility\uc640 \ub9cc\ub0a9\ub2c8\ub2e4. \ub85c\ubd07\uc774 task space\uc5d0\uc11c pose\uc5d0 \ub3c4\ub2ec\ud560 \uc218 \uc788\uc5b4\ub3c4 \ud658\uacbd\uacfc \ucda9\ub3cc\ud558\uc9c0 \uc54a\uace0 \ub3c4\ub2ec\ud558\uc9c0 \ubabb\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n## 9. Task space\uc640 joint space\uc5d0\uc11c\uc758 planning\\n\\n\ub450 \uac00\uc9c0 \uc77c\ubc18\uc801\uc778 planning \uad00\uc810\uc774 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n### 9.1 Joint-space planning\\n\\nJoint-space planning\uc740 \ubcc0\uc218 $q$\uc5d0\uc11c \uc9c1\uc811 \uc218\ud589\ud569\ub2c8\ub2e4.\\n\\nJoint limit\uc640 actuator limit \uac19\uc740 \uc81c\uc57d\uc740 joint coordinate\ub85c \uc790\uc5f0\uc2a4\ub7fd\uac8c \ud45c\ud604\ub418\ubbc0\ub85c \uc774 \ubc29\uc2dd\uc774 \ub354 \ub2e8\uc21c\ud55c \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.\\n\\n### 9.2 Task-space planning\\n\\nTask-space planning\uc740 \ub9d0\ub2e8 \uc7a5\uce58 pose \ub610\ub294 twist space\uc5d0\uc11c \uc218\ud589\ud569\ub2c8\ub2e4.\\n\\n\ub85c\ubd07 task\uac00 Cartesian coordinate\ub85c \uc9c0\uc815\ub418\ubbc0\ub85c \ub354 \uc9c1\uad00\uc801\uc778 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \\"orientation\uc744 \uace0\uc815\ud55c \ucc44 tool\uc744 \uc9c1\uc120\uc73c\ub85c \uc6c0\uc9c1\uc778\ub2e4\\"\ub294 task-space \ud45c\ud604\uc785\ub2c8\ub2e4.\\n\\n\ud558\uc9c0\ub9cc task-space path\ub294 singularity\ub098 \ub3c4\ub2ec \ubd88\uac00\ub2a5\ud55c configuration \uac19\uc740 joint-space \ubb38\uc81c\ub97c \ub9cc\ub4e4 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\nJacobian\uc740 joint motion\uc744 task-space motion\uc73c\ub85c, \ub610 \uadf8 \ubc18\ub300\ub85c \ubcc0\ud658\ud558\ubbc0\ub85c \ub450 \uad00\uc810 \uc0ac\uc774\uc758 \ub2e4\ub9ac \uc5ed\ud560\uc744 \ud569\ub2c8\ub2e4.\\n\\n## 10. Force control\uacfc interaction\\n\\n\ubaa8\ub4e0 \ub85c\ubd07 task\uac00 \uc21c\uc218\ud55c \uae30\uad6c\ud559\uc801\uc778 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4. \uc0b0\uc5c5\uacfc \uc5f0\uad6c \ud604\uc7a5\uc5d0\uc11c\ub294 \ub85c\ubd07\uc774 \ud658\uacbd\uacfc \uc0c1\ud638\uc791\uc6a9\ud558\uace0, \ud798\uc744 \uac00\ud558\uac70\ub098, \uc811\ucd09\uc744 \uc720\uc9c0\ud574\uc57c \ud558\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.\\n\\nForce control\uc5d0\uc11c\ub294 pose\ub9cc\uc774 \uc544\ub2c8\ub77c contact wrench\ub97c \uc81c\uc5b4\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub54c\ub3c4 \ub2e4\uc74c \uad00\uacc4\uac00 \uc911\uc2ec\uc785\ub2c8\ub2e4.\\n\\n$$\\n\\\\tau = J^T F\\n$$\\n\\n\uc6d0\ud558\ub294 \ud798\uc73c\ub85c \ubc00\uace0 \uc2f6\ub2e4\uba74 controller\ub294 Jacobian\uc744 \uc774\uc6a9\ud574 \uadf8 \ud798\uc744 joint torque\ub85c \ubc14\uafc9\ub2c8\ub2e4. \uc774\ub294 velocity control\uc758 \ub3d9\uc5ed\ud559\uc801 \ub300\uc751\uc785\ub2c8\ub2e4.\\n\\n\uc774\ucc98\ub7fc \uac19\uc740 \ud589\ub82c $J$\uac00 \uc6b4\ub3d9\uacfc \ud798 \uc804\ub2ec\uc744 \ubaa8\ub450 \uc9c0\ubc30\ud558\ubbc0\ub85c \uae30\ud558\ud559\uc801 \uc815\uc2dd\ud654\uac00 \ub354\uc6b1 \uac15\ub825\ud574\uc9d1\ub2c8\ub2e4.\\n\\n## 11. \uc804\uccb4 \ub85c\ubd07 pipeline\\n\\n\uc804\uccb4 \ub85c\ubd07 workflow\ub294 \ub2e4\uc74c\uacfc \uac19\uc740 \uc77c\uad00\ub41c \uc21c\uc11c\ub85c \ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n1. rigid transform\uc73c\ub85c \ub85c\ubd07 geometry\ub97c \ubaa8\ub378\ub9c1\ud569\ub2c8\ub2e4.\\n2. twist\uc640 screw axis\ub85c \uc6b4\ub3d9\uc744 \ud45c\ud604\ud569\ub2c8\ub2e4.\\n3. Jacobian\uc744 \uacc4\uc0b0\ud569\ub2c8\ub2e4.\\n4. Forward\uc640 inverse kinematics\ub97c \ud489\ub2c8\ub2e4.\\n5. \ubd80\ub4dc\ub7ec\uc6b4 timing\uc73c\ub85c trajectory\ub97c \uc124\uacc4\ud569\ub2c8\ub2e4.\\n6. dynamics\uc640 actuator limit\ub97c \uc801\uc6a9\ud569\ub2c8\ub2e4.\\n7. configuration space\uc5d0\uc11c collision-free path\ub97c planning\ud569\ub2c8\ub2e4.\\n8. motion \ub610\ub294 force tracking\uc5d0 Jacobian \uae30\ubc18 control\uc744 \uc0ac\uc6a9\ud569\ub2c8\ub2e4.\\n\\n\uc774\uac83\uc774 \ud604\ub300 \ub85c\ubd07\uacf5\ud559\uc758 \uc911\uc2ec architecture\uc785\ub2c8\ub2e4.\\n\\n## 12. \ub9c8\ubb34\ub9ac \uc9c1\uad00\\n\\n\uc9c0\uae08\uae4c\uc9c0 \ubaa8\ub4e0 \uae00\uc744 \uad00\ud1b5\ud55c \uc8fc\uc81c\ub294 \uac19\uc2b5\ub2c8\ub2e4.\\n\\n- Geometry\uac00 \uad6c\uc870\ub97c \uc81c\uacf5\ud569\ub2c8\ub2e4.\\n- Algebra\uac00 \uacc4\uc0b0 \uac00\ub2a5\ud558\uac8c \ub9cc\ub4ed\ub2c8\ub2e4.\\n- Dynamics\uac00 \ubb3c\ub9ac\uc801 \uc758\ubbf8\ub97c \ubd80\uc5ec\ud569\ub2c8\ub2e4.\\n- Planning\uc774 \uc2e4\ud604 \uac00\ub2a5\ud55c \uc6b4\ub3d9\uc744 \ub9cc\ub4dc\ub294 \ub370 \uc0ac\uc6a9\ud569\ub2c8\ub2e4.\\n\\n\ub530\ub77c\uc11c screw-axis\uc640 Jacobian \uad00\uc810\uc740 \ub85c\ubd07 \uc6b4\ub3d9\uc744 \uc124\uba85\ud558\ub294 \uc88b\uc740 \ubc29\ubc95\uc5d0 \uadf8\uce58\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \ud604\ub300 \ub85c\ubd07\uacf5\ud559\uc758 \ud1b5\ud569\ub41c \uc218\ud559 \uc5b8\uc5b4\uc785\ub2c8\ub2e4.\\n\\n\uc804\uccb4 \uc774\uc57c\uae30\ub294 \ub2e4\uc74c\ucc98\ub7fc \uac04\uacb0\ud558\uac8c \uc815\ub9ac\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n$$\\nT_{se}(\\\\theta) \\\\in SE(3),\\n$$\\n\\n$$\\n\\\\nu = J(\\\\theta)\\\\dot{\\\\theta},\\n$$\\n\\n$$\\n\\\\tau = J(\\\\theta)^T F,\\n$$\\n\\n\uadf8\ub9ac\uace0 planning\uacfc control\uc740 \uc774 \uad00\uacc4\ub4e4\uc744 \uc0ac\uc6a9\ud574 \uc2e4\ud604 \uac00\ub2a5\ud558\uace0 \ubd80\ub4dc\ub7ec\uc6b0\uba70 task\ub97c \uace0\ub824\ud55c \uc6b4\ub3d9\uc744 \ub9cc\ub4ed\ub2c8\ub2e4.\\n\\n\uc774\uac83\uc774 \ub85c\ubd07 geometry\uc640 \ub85c\ubd07 intelligence \uc0ac\uc774\uc758 \uae4a\uc740 \uac1c\ub150\uc801 \uc5f0\uacb0\uc785\ub2c8\ub2e4."},{"id":"modern-robotics-part-6b","metadata":{"permalink":"/ko/blog/modern-robotics-part-6b","editUrl":"https://github.com/CMaybe/cmaybe.github.io/tree/main/blog/2026-09-07-modern-robotics-part-6b.md","source":"@site/i18n/ko/docusaurus-plugin-content-blog/2026-09-07-modern-robotics-part-6b.md","title":"Modern Robotics, Part 6B \u2014 Trajectory, \uc81c\uc57d, \uadf8\ub9ac\uace0 Motion Planning","description":"\uae30\uad6c\ud559\uc5d0\uc11c planning\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \ud750\ub984\uc744 \uacc4\uc18d \uc0b4\ud3b4\ubcf4\uba70 trajectory \uc0dd\uc131, time scaling, \uc81c\uc57d, \uadf8\ub9ac\uace0 motion planning \ub4a4\uc758 \uae30\ud558\ub97c \ub2e4\ub8f9\ub2c8\ub2e4.","date":"2026-09-07T00:00:00.000Z","tags":[{"inline":false,"label":"Robotics","permalink":"/ko/blog/tags/robotics","description":"Robot software, systems, and experiments."},{"inline":false,"label":"Modern Robotics","permalink":"/ko/blog/tags/modern-robotics","description":"Concepts, methods, and intuition behind rigid-body motion and robot kinematics."},{"inline":false,"label":"Kinematics","permalink":"/ko/blog/tags/kinematics","description":"Forward and inverse kinematics for robots."},{"inline":false,"label":"Motion Planning","permalink":"/ko/blog/tags/motion-planning","description":"Algorithms for finding feasible robot motion."}],"readingTime":5.99,"hasTruncateMarker":true,"authors":[{"name":"Jaegyeom Kim","title":"Robotics Software Engineer","url":"https://github.com/CMaybe","page":{"permalink":"/ko/blog/authors/endi"},"socials":{"github":"https://github.com/CMaybe","linkedin":"https://www.linkedin.com/in/Jaegyeom-kim-185b8a2a4/"},"imageURL":"https://github.com/CMaybe.png","key":"endi"}],"frontMatter":{"slug":"modern-robotics-part-6b","title":"Modern Robotics, Part 6B \u2014 Trajectory, \uc81c\uc57d, \uadf8\ub9ac\uace0 Motion Planning","authors":["endi"],"tags":["robotics","modern-robotics","kinematics","motion-planning"],"description":"\uae30\uad6c\ud559\uc5d0\uc11c planning\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \ud750\ub984\uc744 \uacc4\uc18d \uc0b4\ud3b4\ubcf4\uba70 trajectory \uc0dd\uc131, time scaling, \uc81c\uc57d, \uadf8\ub9ac\uace0 motion planning \ub4a4\uc758 \uae30\ud558\ub97c \ub2e4\ub8f9\ub2c8\ub2e4."},"unlisted":false,"prevItem":{"title":"Modern Robotics, Part 6A \u2014 \ub3d9\uc5ed\ud559, \uc81c\uc5b4, \uadf8\ub9ac\uace0 \uc6b4\ub3d9 \uc0dd\uc131","permalink":"/ko/blog/modern-robotics-part-6"},"nextItem":{"title":"Modern Robotics \uc2dc\ub9ac\uc988 \uc815\ub9ac - Geometry, Control, Planning","permalink":"/ko/blog/modern-robotics-series-summary"}},"content":"\uc55e\uc120 \uae00\uc5d0\uc11c\ub294 \ub3d9\uc5ed\ud559\uacfc \uc81c\uc5b4 \uad00\uc810\uc744 \uc815\ub9bd\ud588\uc2b5\ub2c8\ub2e4. \ub85c\ubd07 \uc6b4\ub3d9\uc740 geometry\ubfd0 \uc544\ub2c8\ub77c inertia, gravity, force transmission, task-space control\uc5d0 \uc758\ud574\uc11c\ub3c4 \uacb0\uc815\ub429\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc2e4\uc81c\ub85c \ub85c\ubd07\uc740 \ud55c configuration\uc5d0\uc11c \ub2e4\ub978 configuration\uc73c\ub85c \ubd80\ub4dc\ub7fd\uace0 \uc2e4\ud604 \uac00\ub2a5\ud558\uba70 \uc548\uc804\ud55c \ubc29\uc2dd\uc73c\ub85c \uc774\ub3d9\ud574\uc57c \ud569\ub2c8\ub2e4.\\n\\n\uc774\uac83\uc774 trajectory\uc640 planning \ubb38\uc81c\uc785\ub2c8\ub2e4.\\n\\n\x3c!-- truncate --\x3e\\n\\n## 1. Path\ub294 trajectory\uc640 \ub2e4\ub974\ub2e4\\n\\nPath\ub294 configuration space \ub610\ub294 task space\uc5d0 \uc788\ub294 \uae30\ud558\ud559\uc801 \uace1\uc120\uc785\ub2c8\ub2e4. Trajectory\ub294 \uc5ec\uae30\uc5d0 timing\uc744 \ub354\ud55c path\uc785\ub2c8\ub2e4.\\n\\n\uc608\ub97c \ub4e4\uc5b4 path\ub294 \\"pose A\uc5d0\uc11c pose B\ub85c \uc9c1\uc120\uc73c\ub85c \uc774\ub3d9\ud55c\ub2e4\\"\uc77c \uc218 \uc788\uc9c0\ub9cc, trajectory\ub294 \ub2e4\uc74c\ub3c4 \uc9c0\uc815\ud574\uc57c \ud569\ub2c8\ub2e4.\\n\\n- \ub85c\ubd07\uc774 \uc5b8\uc81c \uc2dc\uc791\ud558\ub294\uc9c0,\\n- \uc5bc\ub9c8\ub098 \ube60\ub974\uac8c \uc6c0\uc9c1\uc774\ub294\uc9c0,\\n- \uc5b8\uc81c \uac10\uc18d\ud558\ub294\uc9c0,\\n- acceleration\uc774 limit \uc548\uc5d0 \uc788\ub294\uc9c0\uc785\ub2c8\ub2e4.\\n\\n\uc2dc\uac04\uc744 \uace0\ub824\ud558\uc9c0 \uc54a\uace0 path\ub97c \ub530\ub77c\uac08 \uc218\ub294 \uc5c6\uc2b5\ub2c8\ub2e4. \uadf8\ub807\uc9c0 \uc54a\uc73c\uba74 \uae30\ud558\ud559\uc801\uc73c\ub85c\ub294 \ub9de\uc9c0\ub9cc \ub3d9\uc5ed\ud559\uc801\uc73c\ub85c\ub294 \ubd88\uac00\ub2a5\ud55c \uba85\ub839\uc744 \ub9cc\ub4e4 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\uadf8\ub798\uc11c trajectory generation\uc740 \uae30\uad6c\ud559\uacfc \uc2e4\ud589 \uc0ac\uc774\uc758 \ud544\uc218 \ub2e8\uacc4\uc785\ub2c8\ub2e4.\\n\\n## 2. Time scaling\uc758 \uc5ed\ud560\\n\\nPath\ub97c arc length\ub098 path parameter\ub97c \ub098\ud0c0\ub0b4\ub294 scalar $s$\ub85c \ub9e4\uac1c\ud654\ud55c\ub2e4\uace0 \ud569\uc2dc\ub2e4. \uadf8\ub7ec\uba74 \uadf8 \uacbd\ub85c\ub97c \ub530\ub978 \ub85c\ubd07 \uc6b4\ub3d9\uc740 time law\ub85c \uc815\ud574\uc9d1\ub2c8\ub2e4.\\n\\n$$\\ns = s(t).\\n$$\\n\\nJoint trajectory\ub294\\n\\n$$\\nq(t) = q(s(t)).\\n$$\\n\\n\uac00 \ub429\ub2c8\ub2e4. \ubbf8\ubd84\ud558\uba74\\n\\n$$\\n\\\\dot{q}(t) = \\\\frac{dq}{ds}\\\\dot{s},\\n$$\\n\\n\uadf8\ub9ac\uace0\\n\\n$$\\n\\\\ddot{q}(t) = \\\\frac{d^2 q}{ds^2}\\\\dot{s}^2 + \\\\frac{dq}{ds}\\\\ddot{s}.\\n$$\\n\\n\uc785\ub2c8\ub2e4.\\n\\n\uc774 \ubd84\ud574\ub294 \ub2e4\uc74c\uc744 \ub098\ub220 \uc0dd\uac01\ud560 \uc218 \uc788\uac8c \ud558\ubbc0\ub85c \uc720\uc6a9\ud569\ub2c8\ub2e4.\\n\\n- \uae30\ud558\ud559\uc801 path shape $q(s)$,\\n- timing law $s(t)$\uc785\ub2c8\ub2e4.\\n\\nTiming law\ub294 \uc6b4\ub3d9\uc774 velocity\uc640 acceleration bound\ub97c \ub9cc\uc871\ud558\ub294\uc9c0 \uacb0\uc815\ud569\ub2c8\ub2e4. \uc774 \ubd84\ub9ac\ub294 motion planning\uacfc trajectory generation\uc5d0\uc11c \uac00\uc7a5 \uc911\uc694\ud55c \uac1c\ub150 \uc911 \ud558\ub098\uc785\ub2c8\ub2e4.\\n\\n## 3. Polynomial trajectory\\n\\n\ubd80\ub4dc\ub7ec\uc6b4 trajectory\ub97c \ub9cc\ub4dc\ub294 \ud754\ud55c \ubc29\ubc95\uc740 polynomial interpolation\uc785\ub2c8\ub2e4. \uac00\uc7a5 \uac04\ub2e8\ud55c \uc608\ub294 cubic polynomial\uc785\ub2c8\ub2e4.\\n\\n$$\\nq(t) = a_0 + a_1 t + a_2 t^2 + a_3 t^3.\\n$$\\n\\n\uacc4\uc218\ub294 initial position, final position, initial/final velocity \uac19\uc740 boundary condition\uc744 \ub9de\ucd94\ub3c4\ub85d \uc120\ud0dd\ud569\ub2c8\ub2e4.\\n\\n\ub354 \ub192\uc740 smoothness\uac00 \ud544\uc694\ud558\uba74 quintic polynomial\uc744 \uc0ac\uc6a9\ud569\ub2c8\ub2e4.\\n\\n$$\\nq(t) = a_0 + a_1 t + a_2 t^2 + a_3 t^3 + a_4 t^4 + a_5 t^5.\\n$$\\n\\n\uc774\ub97c \uc0ac\uc6a9\ud558\uba74 \ub05d\uc810\uc5d0\uc11c position\uacfc velocity \uc81c\uc57d\uc744 \ub9cc\uc871\ud558\uace0, \uc5b4\ub5a4 \uc815\uc2dd\ud654\uc5d0\uc11c\ub294 acceleration \uc81c\uc57d\ub3c4 \ub9cc\uc871\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\uc774\ub294 \ub85c\ubd07\uc774 \uc6b4\ub3d9\uc744 \uac11\uc790\uae30 \ubc14\uafb8\uc9c0 \uc54a\uc544\uc57c \ud558\uae30 \ub54c\ubb38\uc5d0 \uc911\uc694\ud569\ub2c8\ub2e4. \ubd80\ub4dc\ub7ec\uc6b4 interpolation\uc740 jerk, vibration, wear\ub97c \uc904\uc774\uace0 controller\ub97c \uc548\uc815\ud654\ud558\uae30\ub3c4 \uc27d\uac8c \ud569\ub2c8\ub2e4.\\n\\n## 4. Dynamics\uac00 trajectory \uc120\ud0dd\uc5d0 \uc601\ud5a5\uc744 \uc8fc\ub294 \uc774\uc720\\n\\n\uae30\ud558\ud559\uc801\uc73c\ub85c path\ub97c \ub9cc\ub4e4 \uc218 \uc788\uc5b4\ub3c4 \ub85c\ubd07\uc774 \uc6d0\ud558\ub294 \uc18d\ub3c4\ub85c \uc774\ub97c \uc2e4\ud589\ud560 \uc218 \uc788\ub2e4\ub294 \ub73b\uc740 \uc544\ub2d9\ub2c8\ub2e4.\\n\\n\ub3d9\uc5ed\ud559 \ubc29\uc815\uc2dd\\n\\n$$\\nM(q)\\\\ddot{q} + C(q,\\\\dot{q})\\\\dot{q} + g(q) = \\\\tau\\n$$\\n\\n\uc740 \uc5b4\ub5a4 \uc6b4\ub3d9\uc774 \uc2e4\ud604 \uac00\ub2a5\ud55c\uc9c0 \uc81c\uc57d\ud569\ub2c8\ub2e4.\\n\\n\ub2e4\uc2dc \ub9d0\ud574 path\uac00 \uae30\uad6c\ud559\uc801\uc73c\ub85c \ub3c4\ub2ec \uac00\ub2a5\ud574\ub3c4 actuator limit \uc544\ub798\uc5d0\uc11c\ub294 \ub3d9\uc5ed\ud559\uc801\uc73c\ub85c \ubd88\uac00\ub2a5\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub294 \uace0\uc18d manipulation\uacfc \ubb34\uac70\uc6b4 payload \uc6b4\ubc18\uc5d0\uc11c \ud2b9\ud788 \uc911\uc694\ud569\ub2c8\ub2e4.\\n\\n\uadf8\ub798\uc11c trajectory generation\uc740 \uae30\ud558\ud559\ub9cc\uc758 \ubb38\uc81c\uac00 \uc544\ub2d9\ub2c8\ub2e4. \ub3d9\uc2dc\uc5d0 dynamics\uc640 control\uc758 \ubb38\uc81c\uc785\ub2c8\ub2e4.\\n\\n## 5. Configuration space\uc640 obstacle avoidance\\n\\nMotion planning\uc740 \uadfc\ubcf8\uc801\uc73c\ub85c configuration space\uc5d0\uc11c \uc2e4\ud604 \uac00\ub2a5\ud55c path\ub97c \ucc3e\ub294 \uc77c\uc785\ub2c8\ub2e4.\\n\\nConfiguration space\ub294 \ubaa8\ub4e0 joint configuration\uc758 \uc9d1\ud569\uc785\ub2c8\ub2e4. Configuration\uc740 \ub2e4\uc74c\uc744 \ub9cc\uc871\ud558\uba74 \uc720\ud6a8\ud569\ub2c8\ub2e4.\\n\\n- joint limit\ub97c \ub9cc\uc871\ud558\uace0,\\n- collision\uc744 \ud53c\ud558\uba70,\\n- feasible motion envelope \uc548\uc5d0 \uc788\uc5b4\uc57c \ud569\ub2c8\ub2e4.\\n\\n\uc774 mapping\uc740 \\"\uc138\uacc4\uc758 \uc7a5\uc560\ubb3c\uc744 \ud53c\ud558\ub77c\\"\ub294 \uae30\ud558\ud559\uc801 \ubb38\uc81c\ub97c \uace0\ucc28\uc6d0 state space\uc5d0\uc11c\uc758 search \ubb38\uc81c\ub85c \ubc14\uafc9\ub2c8\ub2e4.\\n\\n\uad00\uc808\uc774 \ub9ce\uc73c\uba74 configuration space\ub294 \ud06c\uace0 \ubcf5\uc7a1\ud574\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc815\ud655\ud55c planning\uc774 \uc5b4\ub824\uc6b4 \uc774\uc720\uc774\uba70 sampling-based method\uac00 \uc720\uc6a9\ud574\uc9c0\ub294 \uc774\uc720\uc785\ub2c8\ub2e4.\\n\\n## 6. Sampling-based planning\\n\\n\ub300\ud45c\uc801\uc778 \ub450 sampling-based planner\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.\\n\\n- PRM (Probabilistic Roadmap)\\n- RRT (Rapidly-exploring Random Tree)\\n\\n\uc774 \ubc29\ubc95\ub4e4\uc740 \uc720\ud6a8\ud55c configuration\uc758 graph \ub610\ub294 tree\ub97c \ub9cc\ub4e4\uace0, feasibility\ub97c \ud655\uc778\ud558\uba74\uc11c \uac00\uae4c\uc6b4 sample\uc744 \uc5f0\uacb0\ud569\ub2c8\ub2e4.\\n\\nConfiguration space\uac00 \uace0\ucc28\uc6d0\uc774\uace0 \uc7a5\uc560\ubb3c\uc774 \ubcf5\uc7a1\ud560 \ub54c \ud2b9\ud788 \uc720\uc6a9\ud569\ub2c8\ub2e4. \uc774\ub7f0 \uc0c1\ud669\uc5d0\uc11c\ub294 analytic planning\uc774 \uc2e4\ud604 \ubd88\uac00\ub2a5\ud55c \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.\\n\\n\uc544\uc774\ub514\uc5b4\ub294 \ub2e8\uc21c\ud558\uc9c0\ub9cc \uac15\ub825\ud569\ub2c8\ub2e4.\\n\\n- \uc784\uc758\uc758 configuration\uc744 sampling\ud569\ub2c8\ub2e4.\\n- \uc720\ud6a8\ud55c sample\ub9cc \ub0a8\uae41\ub2c8\ub2e4.\\n- \uc774\ub4e4\uc744 graph\ub85c \uc5f0\uacb0\ud569\ub2c8\ub2e4.\\n- \ubaa9\ud45c\uae4c\uc9c0\uc758 path\ub97c search\ud569\ub2c8\ub2e4.\\n\\n\uc774\ub294 \ub85c\ubd07\uacf5\ud559\uc758 \ud45c\uc900\uc801\uc778 \uc811\uadfc\ubc95\uc774 \ub418\uc5c8\uc2b5\ub2c8\ub2e4.\\n\\n## 7. Task-space planning\uacfc joint-space planning\\n\\n\ub85c\ubd07 task\ub294 target pose\ub098 Cartesian path\ub97c \ub530\ub77c tool\uc744 \uc6c0\uc9c1\uc774\ub294 \uac83\ucc98\ub7fc task space\uc5d0\uc11c \uc9c0\uc815\ud558\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \ub85c\ubd07 \uc790\uccb4\ub294 joint space\uc5d0\uc11c \uc81c\uc5b4\ub429\ub2c8\ub2e4.\\n\\n\ub530\ub77c\uc11c \ub450 \uac00\uc9c0 \uc790\uc5f0\uc2a4\ub7ec\uc6b4 planning paradigm\uc774 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n### Task-space planning\\n\\nEnd-effector frame\uc774\ub098 world frame\uc5d0\uc11c path\ub97c \uc124\uacc4\ud558\uba70, \uc9c1\uc120, \uace1\uc120, orientation interpolation\uc744 \uc0ac\uc6a9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\uc774\ub294 \ub85c\ubd07\uc774 \uc218\ud589\ud574\uc57c \ud560 \uc791\uc5c5\uacfc \uc9c1\uc811 \ub9de\ub2ff\uc544 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n### Joint-space planning\\n\\nJoint coordinate\uc5d0\uc11c \uc9c1\uc811 path\ub97c \uc124\uacc4\ud569\ub2c8\ub2e4. Joint limit\uc640 actuator constraint\ub97c \uc801\uc6a9\ud558\uae30\uc5d0\ub294 \ub354 \ub2e8\uc21c\ud55c \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.\\n\\nJacobian\uc740 joint-space motion\uc744 task-space twist\ub85c, \ub610 \uadf8 \ubc18\ub300\ub85c mapping\ud558\ubbc0\ub85c \ub450 \uad00\uc810\uc744 \uc5f0\uacb0\ud569\ub2c8\ub2e4.\\n\\n\uc2e4\uc81c\ub85c \ucd5c\uc120\uc758 \uc804\ub7b5\uc740 application\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9d1\ub2c8\ub2e4. Workspace \ubaa9\ud45c\uc5d0\ub294 task-space motion\uc774, actuator feasibility\uc640 safety\uc5d0\ub294 joint-space motion\uc774 \uc801\ud569\ud569\ub2c8\ub2e4.\\n\\n## 8. Collision constraint\ub3c4 \ub3d9\uc801 \uc81c\uc57d\uc774\ub2e4\\n\\nPath\ub294 collision-free\uc5ec\uc57c\ub9cc \uc720\uc6a9\ud569\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc2e4\uc81c\ub85c collision checking\uc740 \uae30\ud558\ud559\ub9cc\uc758 \ubb38\uc81c\uac00 \uc544\ub2d9\ub2c8\ub2e4. \uc6b4\ub3d9\uc740 dynamic behavior\uc640 control margin\ub3c4 \uc9c0\ucf1c\uc57c \ud569\ub2c8\ub2e4.\\n\\n\uc608\ub97c \ub4e4\uc5b4 trajectory\uac00 discrete sample \uc9c0\uc810\uc5d0\uc11c\ub294 collision-free\uc5ec\ub3c4 \uc2dc\uac04\uc0c1 \ub108\ubb34 \uacf5\uaca9\uc801\uc774\uba74 overshoot\ub098 \ud070 control effort\ub97c \ub9cc\ub4e4 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c planner\ub294 safety margin\uacfc smoothness penalty\ub97c \uc790\uc8fc \uc0ac\uc6a9\ud569\ub2c8\ub2e4.\\n\\n\uc774\ub294 planning\uacfc control\uc774 \uae34\ubc00\ud558\uac8c \uc5f0\uacb0\ub418\uc5b4 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub3c4 \ubcf4\uc5ec \uc90d\ub2c8\ub2e4. \uae30\ud558\ud559\uc801\uc73c\ub85c \uc720\ud6a8\ud55c path\uac00 control \uc131\ub2a5 \uba74\uc5d0\uc11c\ub294 \uc88b\uc9c0 \uc54a\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n## 9. Motion planning\uc5d0\uc11c optimization\uc758 \uc5ed\ud560\\n\\n\ud604\ub300\uc758 planning\uc740 sample-based search\ub9cc\uc774 \uc544\ub2c8\ub77c optimization\uc744 \uc790\uc8fc \uc0ac\uc6a9\ud569\ub2c8\ub2e4. \uc774\ub54c \ub2e4\uc74c\uacfc \uac19\uc740 cost function\uc744 \uc815\uc758\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n$$\\nJ = \\\\int_0^T \\\\left(\\\\|\\\\dot{q}(t)\\\\|^2 + \\\\lambda \\\\|\\\\ddot{q}(t)\\\\|^2 + \\\\text{obstacle cost}\\\\right) dt.\\n$$\\n\\n\uc774 \ubaa9\uc801 \ud568\uc218\ub294 \ub2e4\uc74c\uc744 \uade0\ud615 \uc788\uac8c \uace0\ub824\ud569\ub2c8\ub2e4.\\n\\n- smoothness,\\n- effort,\\n- obstacle avoidance,\\n- \uadf8\ub9ac\uace0 \ud544\uc694\ud558\ub2e4\uba74 trackability\uc785\ub2c8\ub2e4.\\n\\nOptimization-based motion generation\uc740 feasibility\ub9cc\ud07c trajectory quality\uac00 \uc911\uc694\ud55c \ub85c\ubd07\uacf5\ud559\uc5d0\uc11c \ub9e4\uc6b0 \ud6a8\uacfc\uc801\uc785\ub2c8\ub2e4.\\n\\n\ubaa9\ud45c\ub294 \uc720\ud6a8\ud55c path\ub97c \uc544\ubb34\uac70\ub098 \uace0\ub974\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \uc2e4\ud604 \uac00\ub2a5\ud558\uba74\uc11c\ub3c4 \uc88b\uc740 path\ub97c \uace0\ub974\ub294 \uac83\uc785\ub2c8\ub2e4.\\n\\n## 10. Planning\uc774 \uae30\uad6c\ud559\uc5d0 \uae4a\uc774 \uc758\uc874\ud558\ub294 \uc774\uc720\\n\\n\ub85c\ubd07\uc774 \uac00\ub2a5\ud55c \uc6b4\ub3d9\uc740 workspace\uc640 configuration \uc81c\uc57d\uc5d0 \uc758\ud574 \uacb0\uc815\ub418\ubbc0\ub85c \uc804\uccb4 planning \uacfc\uc815\uc740 \uae30\uad6c\ud559\uc5d0 \uc758\uc874\ud569\ub2c8\ub2e4.\\n\\nTarget pose\uac00 reachable workspace \ubc16\uc5d0 \uc788\uc73c\uba74 task\ub97c \ubc14\uafb8\uc9c0 \uc54a\ub294 \ud55c \uc5b4\ub5a4 planner\ub3c4 \ud574\uacb0\ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4. Path\uac00 singular configuration \uadfc\ucc98\ub97c \uc9c0\ub098\uba74 planner\uac00 \uc81c\uc5b4\ud558\uae30 \uc5b4\ub824\uc6b4 \uc6b4\ub3d9\uc744 \ub9cc\ub4e4 \uc218 \uc788\uc2b5\ub2c8\ub2e4. Path\uc5d0 \uadf9\ub2e8\uc801\uc778 joint rate\uac00 \ud544\uc694\ud558\uba74 trajectory\uac00 \ub3d9\uc5ed\ud559\uc801\uc73c\ub85c \uc2e4\ud604 \ubd88\uac00\ub2a5\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\uc55e\uc120 \uc774\ub860\uc774 \uc2e4\uc81c\ub85c \uc911\uc694\ud55c \uc774\uc720\uac00 \uc5ec\uae30\uc5d0 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n- Screw axis\ub294 \uc6b4\ub3d9 \ubc29\ud5a5\uc744 \uc815\uc758\ud569\ub2c8\ub2e4.\\n- Jacobian\uc740 \uad6d\uc18c \uc774\ub3d9\uc131\uc744 \uc815\uc758\ud569\ub2c8\ub2e4.\\n- Inverse kinematics\ub294 \ub3c4\ub2ec \uac00\ub2a5\ud55c configuration\uc744 \uc815\uc758\ud569\ub2c8\ub2e4.\\n- Dynamic constraint\ub294 \uc2e4\ud604 \uac00\ub2a5\ud55c timing\uc744 \uacb0\uc815\ud569\ub2c8\ub2e4.\\n- Planning\uc740 \uc774 \ubaa8\ub4e0 \uac83\uc744 \ub9cc\uc871\ud558\ub294 path\ub97c \uc81c\uacf5\ud569\ub2c8\ub2e4.\\n\\n## 11. Path\uc5d0\uc11c \uc2e4\ud589\uc73c\ub85c\\n\\n\uc2e4\ud604 \uac00\ub2a5\ud55c trajectory\ub97c planning\ud558\uba74 controller\uac00 tracking law\ub97c \uc0ac\uc6a9\ud574 \uc2e4\ud589\ud569\ub2c8\ub2e4. \ubaa9\ud45c\ub294 \uc2e4\uc81c disturbance\uc640 actuator limit\ub97c \uace0\ub824\ud558\uba74\uc11c \ub85c\ubd07\uc774 \uacc4\ud68d\ub41c \uc6b4\ub3d9\uc744 \ub530\ub974\uac8c \ud558\ub294 \uac83\uc785\ub2c8\ub2e4.\\n\\n\uc5ec\uae30\uc11c\ub294 task-space control, inverse kinematics, dynamic compensation\uc774 \ud568\uaed8 \uc791\ub3d9\ud569\ub2c8\ub2e4.\\n\\n- Planner\uac00 reference trajectory\ub97c \uacc4\uc0b0\ud569\ub2c8\ub2e4.\\n- Controller\uac00 \uc774\ub97c \ucd94\uc801\ud569\ub2c8\ub2e4.\\n- \ub85c\ubd07\uc740 \uc801\uc808\ud55c joint torque \ub610\ub294 rate\ub85c \ubc18\uc751\ud569\ub2c8\ub2e4.\\n\\n\uc774\ub85c\uc368 geometry\uc5d0\uc11c motion generation\uc744 \uac70\uccd0 actuation\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 loop\uac00 \uc644\uc131\ub429\ub2c8\ub2e4.\\n\\n## 12. \ucd5c\uc885 \ud574\uc11d\\n\\nTrajectory\uc640 planning \ubb38\uc81c\ub294 \uc6b4\ub3d9 \uc774\ub860\uc774 \uc2e4\uc81c \ud589\ub3d9\uc774 \ub418\ub294 \uc9c0\uc810\uc785\ub2c8\ub2e4.\\n\\n\uac15\uccb4\uc758 \uae30\ud558\ud559\uc801 \uc124\uba85\uc5d0\uc11c \uc2dc\uc791\ud55c \ub0b4\uc6a9\uc740 \ubd80\ub4dc\ub7fd\uace0 \uc2e4\ud604 \uac00\ub2a5\ud558\uba70 \uc548\uc804\ud55c \ub85c\ubd07 \uc6b4\ub3d9\uc744 \uc124\uacc4\ud558\uace0 \uc2e4\ud589\ud558\ub294 \ub2a5\ub825\uc73c\ub85c \ub05d\ub0a9\ub2c8\ub2e4. \uac1c\ub150\uc758 \uc5f0\uacb0\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.\\n\\n$$\\n\\\\text{rigid-body geometry} \\\\rightarrow \\\\text{twists} \\\\rightarrow \\\\text{Jacobian} \\\\rightarrow \\\\text{IK} \\\\rightarrow \\\\text{dynamics} \\\\rightarrow \\\\text{trajectory} \\\\rightarrow \\\\text{planning}.\\n$$\\n\\n\uc774\uac83\uc774 \ud604\ub300 \ub85c\ubd07\uacf5\ud559\uc758 \uc804\uccb4 architecture\uc785\ub2c8\ub2e4.\\n\\n\ud575\uc2ec \ud1b5\ucc30\uc740 \uac01 \uce35\uc774 \uc11c\ub85c \ubd84\ub9ac\ub418\uc5b4 \uc788\uc9c0 \uc54a\ub2e4\ub294 \uc810\uc785\ub2c8\ub2e4. \uac01 \uce35\uc740 \uc55e\uc120 \uce35\uc5d0 \uc758\uc874\ud569\ub2c8\ub2e4. Geometry\uac00 motion model\uc744 \ub9cc\ub4e4\uace0, dynamics\uac00 \uc2e4\ud589\uc744 \uc81c\ud55c\ud558\uba70, planning\uc774 \uac00\ub2a5\ud55c \uc6b4\ub3d9 \uc911 \uc81c\uc57d\uc744 \ub9cc\uc871\ud558\ub294 \ubc29\uc2dd\uc744 \uc120\ud0dd\ud569\ub2c8\ub2e4.\\n\\nModern Robotics \uc815\uc2dd\ud654\uac00 \uac15\ub825\ud55c \uc774\uc720\ub3c4 \uc5ec\uae30\uc5d0 \uc788\uc2b5\ub2c8\ub2e4. \uac00\uc7a5 \uc791\uc740 \ubbf8\uc18c \uc6b4\ub3d9\ubd80\ud130 \uac00\uc7a5 \ub113\uc740 motion-planning \ubb38\uc81c\uae4c\uc9c0 \ub85c\ubd07 \uc6b4\ub3d9\uc744 \ud558\ub098\uc758 \uad00\uc810\uc73c\ub85c \ubcfc \uc218 \uc788\uac8c \ud569\ub2c8\ub2e4."},{"id":"modern-robotics-series-summary","metadata":{"permalink":"/ko/blog/modern-robotics-series-summary","editUrl":"https://github.com/CMaybe/cmaybe.github.io/tree/main/blog/2026-09-07-modern-robotics-series-summary.md","source":"@site/i18n/ko/docusaurus-plugin-content-blog/2026-09-07-modern-robotics-series-summary.md","title":"Modern Robotics \uc2dc\ub9ac\uc988 \uc815\ub9ac - Geometry, Control, Planning","description":"Modern Robotics \uc2dc\ub9ac\uc988 \uc804\uccb4\ub97c \uac15\uccb4 \uc6b4\ub3d9, screw theory, Jacobian, \uc5ed\uae30\uad6c\ud559, \ub3d9\uc5ed\ud559, \ubaa8\uc158 \ud50c\ub798\ub2dd\uc758 \ud750\ub984\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.","date":"2026-09-07T00:00:00.000Z","tags":[{"inline":false,"label":"Robotics","permalink":"/ko/blog/tags/robotics","description":"Robot software, systems, and experiments."},{"inline":false,"label":"Modern Robotics","permalink":"/ko/blog/tags/modern-robotics","description":"Concepts, methods, and intuition behind rigid-body motion and robot kinematics."},{"inline":false,"label":"Kinematics","permalink":"/ko/blog/tags/kinematics","description":"Forward and inverse kinematics for robots."},{"inline":false,"label":"Screw Theory","permalink":"/ko/blog/tags/screw-theory","description":"Twists, screw axes, and the geometry of rigid-body motion."}],"readingTime":0.74,"hasTruncateMarker":true,"authors":[{"name":"Jaegyeom Kim","title":"Robotics Software Engineer","url":"https://github.com/CMaybe","page":{"permalink":"/ko/blog/authors/endi"},"socials":{"github":"https://github.com/CMaybe","linkedin":"https://www.linkedin.com/in/Jaegyeom-kim-185b8a2a4/"},"imageURL":"https://github.com/CMaybe.png","key":"endi"}],"frontMatter":{"slug":"modern-robotics-series-summary","title":"Modern Robotics \uc2dc\ub9ac\uc988 \uc815\ub9ac - Geometry, Control, Planning","authors":["endi"],"tags":["robotics","modern-robotics","kinematics","screw-theory"],"description":"Modern Robotics \uc2dc\ub9ac\uc988 \uc804\uccb4\ub97c \uac15\uccb4 \uc6b4\ub3d9, screw theory, Jacobian, \uc5ed\uae30\uad6c\ud559, \ub3d9\uc5ed\ud559, \ubaa8\uc158 \ud50c\ub798\ub2dd\uc758 \ud750\ub984\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4."},"unlisted":false,"prevItem":{"title":"Modern Robotics, Part 6B \u2014 Trajectory, \uc81c\uc57d, \uadf8\ub9ac\uace0 Motion Planning","permalink":"/ko/blog/modern-robotics-part-6b"},"nextItem":{"title":"\ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c \ub9cc\ub098\ub294 Modern Robotics","permalink":"/ko/blog/modern-robotics-wasm"}},"content":"Modern Robotics\ub294 \ub85c\ubd07\uc758 \uc6b4\ub3d9\uc744 \ub2e8\uc21c\ud55c \uad00\uc808 \uac01\ub3c4\uc758 \ub098\uc5f4\uc774 \uc544\ub2c8\ub77c, \uacf5\uac04\uc5d0\uc11c \uc77c\uc5b4\ub098\ub294 \uac15\uccb4\uc758 \uc5f0\uc18d\uc801\uc778 \ubcc0\ud658\uc73c\ub85c \uc774\ud574\ud569\ub2c8\ub2e4. \uc774 \uae00\uc740 \uc2dc\ub9ac\uc988 \uc804\uccb4\uc758 \uac1c\ub150 \uc9c0\ub3c4\ub97c \uc81c\uacf5\ud569\ub2c8\ub2e4.\\n\\n\x3c!-- truncate --\x3e\\n\\n## \ud575\uc2ec \ud750\ub984\\n\\n\ub85c\ubd07 \ub05d\ub2e8\uc758 \uc790\uc138\ub294 $SE(3)$ \uc704\uc758 \uac15\uccb4 \ubcc0\ud658\uc73c\ub85c \ud45c\ud604\ub429\ub2c8\ub2e4. \uadf8 \uc21c\uac04 \uc6b4\ub3d9\uc740 twist\uc640 screw axis\ub85c, \uc720\ud55c\ud55c \uc6b4\ub3d9\uc740 exponential map\uc73c\ub85c \ud45c\ud604\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n$$\\nT(\\\\theta) = e^{\\\\hat{\\\\mathcal{S}}\\\\theta}\\n$$\\n\\nJacobian\uc740 \uad00\uc808 \uc18d\ub3c4\uc640 \uc791\uc5c5 \uacf5\uac04 \uc18d\ub3c4\ub97c \uc5f0\uacb0\ud569\ub2c8\ub2e4.\\n\\n$$\\n\\\\nu = J(\\\\theta)\\\\dot{\\\\theta}\\n$$\\n\\n\uc774\ub97c \ubc14\ud0d5\uc73c\ub85c \uc18d\ub3c4 \uc81c\uc5b4\uc640 \uc5ed\uae30\uad6c\ud559\uc744 \ud480\uace0, \ub3d9\uc5ed\ud559\uacfc \uada4\uc801 \uc0dd\uc131\uc73c\ub85c \ud655\uc7a5\ud569\ub2c8\ub2e4.\\n\\n$$\\nM(\\\\theta)\\\\ddot{\\\\theta} + C(\\\\theta, \\\\dot{\\\\theta})\\\\dot{\\\\theta} + g(\\\\theta) = \\\\tau\\n$$\\n\\n## \uc2dc\ub9ac\uc988 \uc21c\uc11c\\n\\n- Part 1: \uac15\uccb4 \uc6b4\ub3d9\uacfc Product of Exponentials\\n- Part 2A: Screw axis, twist, exponential map\\n- Part 2B: \uc88c\ud45c\uacc4, Lie group, Jacobian\uc758 \uc5f0\uacb0\\n- Part 3-5: Jacobian, manipulability, \uc5ed\uae30\uad6c\ud559\\n- Part 6A-6B: \ub3d9\uc5ed\ud559, \uc81c\uc5b4, \uada4\uc801, \ubaa8\uc158 \ud50c\ub798\ub2dd\\n\\n\uc601\ubb38 \uc6d0\ubb38\uacfc \ud55c\uad6d\uc5b4 \ubc88\uc5ed\uc740 \uac19\uc740 URL \uad6c\uc870\ub97c \uc720\uc9c0\ud569\ub2c8\ub2e4. \ubc88\uc5ed\uc774 \uc644\ub8cc\ub418\ub294 \uc21c\uc11c\ub300\ub85c \uac01 \uc5b8\uc5b4 \ud398\uc774\uc9c0\ub97c \ud655\uc7a5\ud569\ub2c8\ub2e4."},{"id":"modern-robotics-wasm","metadata":{"permalink":"/ko/blog/modern-robotics-wasm","editUrl":"https://github.com/CMaybe/cmaybe.github.io/tree/main/blog/2026-09-07-modern-robotics-wasm.mdx","source":"@site/i18n/ko/docusaurus-plugin-content-blog/2026-09-07-modern-robotics-wasm.mdx","title":"\ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c \ub9cc\ub098\ub294 Modern Robotics","description":"\uc21c\uae30\uad6c\ud559, \uc5ed\uae30\uad6c\ud559, \ud50c\ub798\ub2dd, \ub3d9\uc5ed\ud559\uc744 \uc2e4\ud589\ud574 \ubcfc \uc218 \uc788\ub294 WebGL \ubc0f WebAssembly \ud50c\ub808\uc774\uadf8\ub77c\uc6b4\ub4dc\uc785\ub2c8\ub2e4.","date":"2026-09-07T00:00:00.000Z","tags":[{"inline":false,"label":"Robotics","permalink":"/ko/blog/tags/robotics","description":"Robot software, systems, and experiments."},{"inline":false,"label":"Kinematics","permalink":"/ko/blog/tags/kinematics","description":"Forward and inverse kinematics for robots."},{"inline":false,"label":"WebAssembly","permalink":"/ko/blog/tags/webassembly","description":"Native-performance software in the browser."},{"inline":false,"label":"Motion Planning","permalink":"/ko/blog/tags/motion-planning","description":"Algorithms for finding feasible robot motion."}],"readingTime":0.74,"hasTruncateMarker":true,"authors":[{"name":"Jaegyeom Kim","title":"Robotics Software Engineer","url":"https://github.com/CMaybe","page":{"permalink":"/ko/blog/authors/endi"},"socials":{"github":"https://github.com/CMaybe","linkedin":"https://www.linkedin.com/in/Jaegyeom-kim-185b8a2a4/"},"imageURL":"https://github.com/CMaybe.png","key":"endi"}],"frontMatter":{"slug":"modern-robotics-wasm","title":"\ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c \ub9cc\ub098\ub294 Modern Robotics","authors":["endi"],"tags":["robotics","kinematics","webassembly","motion-planning"],"description":"\uc21c\uae30\uad6c\ud559, \uc5ed\uae30\uad6c\ud559, \ud50c\ub798\ub2dd, \ub3d9\uc5ed\ud559\uc744 \uc2e4\ud589\ud574 \ubcfc \uc218 \uc788\ub294 WebGL \ubc0f WebAssembly \ud50c\ub808\uc774\uadf8\ub77c\uc6b4\ub4dc\uc785\ub2c8\ub2e4."},"unlisted":false,"prevItem":{"title":"Modern Robotics \uc2dc\ub9ac\uc988 \uc815\ub9ac - Geometry, Control, Planning","permalink":"/ko/blog/modern-robotics-series-summary"}},"content":"\ud604\ub300 \ub85c\ubd07\uacf5\ud559 \uc54c\uace0\ub9ac\uc998\uc740 \uc785\ub825\uacfc \ucd9c\ub825\uc744 \uc9c1\uc811 \ud655\uc778\ud560 \uc218 \uc788\uc744 \ub54c \uc774\ud574\ud558\uae30 \uc27d\uc2b5\ub2c8\ub2e4. \uc774 \ud504\ub85c\uc81d\ud2b8\ub294 C++ \uae30\uad6c\ud559 \ubc0f \uc81c\uc5b4 \uc2a4\ud0dd\uc744 \ube0c\ub77c\uc6b0\uc800\uc5d0 \uc62c\ub824, \ub85c\uceec \uc2dc\ubbac\ub808\uc774\uc158 \ud658\uacbd\uc744 \uc124\uc815\ud558\uc9c0 \uc54a\uc544\ub3c4 \ub85c\ubd07\uc744 \uc0b4\ud3b4\ubcf4\uace0 \uc6c0\uc9c1\uc774\uba70 \uacbd\ub85c\ub97c \uacc4\ud68d\ud560 \uc218 \uc788\uac8c \ud569\ub2c8\ub2e4.\\n\\n\x3c!-- truncate --\x3e\\n\\n<iframe\\n  src=\\"https://cmaybe.github.io/modern-robotics-wasm/\\"\\n  title=\\"Modern Robotics WASM interactive viewer\\"\\n  style={{width: \'100%\', height: \'760px\', border: 0}}\\n/>\\n\\n\uc774 \uc778\ud130\ub799\ud2f0\ube0c \ubdf0\uc5b4\ub294 UR5\uc640 Franka Research 3 \ub85c\ubd07 \ud314\uc744 \uc9c0\uc6d0\ud569\ub2c8\ub2e4. \uad00\uc808 \uc2ac\ub77c\uc774\ub354\ub85c \uc21c\uae30\uad6c\ud559\uc744 \uc2e4\ud589\ud560 \uc218 \uc788\uace0, \ub9d0\ub2e8 \uc7a5\uce58 \uae30\uc988\ubaa8\ub85c \uc5ed\uae30\uad6c\ud559 \uc194\ubc84\uc5d0 \ubaa9\ud45c\ub97c \uc804\ub2ec\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uac19\uc740 \uc778\ud130\ud398\uc774\uc2a4\uc5d0\uc11c \ucda9\ub3cc \ucea1\uc290, \uc870\uc791\uc131 \ud0c0\uc6d0\uccb4, RRT-Connect\ub97c \uc774\uc6a9\ud55c \ubaa8\uc158 \ud50c\ub798\ub2dd, Newton-Euler \ub3d9\uc5ed\ud559\ub3c4 \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\uacc4\uc0b0 \uacfc\uc815\uc740 C++\ub85c \uad6c\ud604\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4. Eigen\uacfc Sophus\uac00 \uacf5\uac04 \uc88c\ud45c\uacc4 Product of Exponentials \uc815\uc2dd\ud654\ub97c \uad6c\ud604\ud558\uace0, Emscripten\uc774 \uc774\ub97c WebAssembly\ub85c \ucef4\ud30c\uc77c\ud558\uba70, React\uc640 three.js\uac00 \uc2dc\uac01\uc801 \uc778\ud130\ud398\uc774\uc2a4\ub97c \uc81c\uacf5\ud569\ub2c8\ub2e4.\\n\\n\uc18c\uc2a4 \ucf54\ub4dc\uc640 \uad6c\ud604 \ub178\ud2b8\ub294 [modern-robotics-wasm \uc800\uc7a5\uc18c](https://github.com/CMaybe/modern-robotics-wasm)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4."}]}}')}}]);